g.PLANTUML_THEMES["_none_"]="---\nname: _none_\ndisplay_name: None\ndescription: A no theme named `_none_` (intentionally empty); Especially to have a `no theme` (first or last in alphabetical order) to compare with all the others.\nauthor: The-Lum\n---\n";
g.PLANTUML_THEMES["amiga"]="---\nname: amiga\ndisplay_name: Amiga Workbench 1.x\ndescription: A white on blue theme based on Amiga Workbench 1.x\nauthor: Matthew Leather\nrelease: \nlicense: \nversion: \nsource: \ninspiration: https://en.wikipedia.org/wiki/Workbench_(AmigaOS)#Workbench_1.x\n---\n\n!$THEME = \"amiga\"\n\n!$BLACK  = \"#000121\"\n!$BLUE   = \"#0B58A8\"\n!$ORANGE = \"#FDA325\"\n!$RED    = \"#DB252B\"\n!$WHITE  = \"#FFFFFF\"\n\n!$BGCOLOR = $BLUE\n!$FGCOLOR = $WHITE\n\n!ifndef $FONT_NAME\n  !$FONT_NAME = \"Verdana\"\n!endif\n\n!ifndef $FONT_NAME_MONOSPACED\n  !$FONT_NAME_MONOSPACED = \"Courier\"\n!endif\n\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $FGCOLOR\n    FontName $FONT_NAME\n    HyperLinkColor $ORANGE\n    LineColor $FGCOLOR\n    LineThickness 1\n    Margin 5\n  }\n  document {\n    caption {\n      LineThickness 0\n    }\n    footer {\n      LineThickness 0\n    }\n    header {\n      LineThickness 0\n    }\n    title {\n      FontSize 22\n      LineThickness 0\n    }\n  }\n  groupHeader {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  node {\n    MaximumWidth 300\n  }\n  referenceHeader {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  separator {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  participant {\n    Margin 5 10\n    Padding 5 5\n  }\n</style>\n\nskinparam ArrowLollipopColor $FGCOLOR\nskinparam BackgroundColor $BGCOLOR\nskinparam DefaultFontName $FONT_NAME\nskinparam DefaultMonospacedFontName $FONT_NAME_MONOSPACED\nskinparam LifelineStrategy nosolid\nskinparam SequenceLifeLineBorderColor $FGCOLOR\nskinparam Shadowing false\nskinparam UseBetaStyle true\n\nskinparam Activity {\n  BackgroundColor $BGCOLOR\n  BarColor $FGCOLOR\n  BorderColor $FGCOLOR\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Boundary {\n  FontColor $FGCOLOR\n}\nskinparam Box {\n  Padding 5\n}\nskinparam CircledCharacter {\n  FontColor $BGCOLOR\n  FontName $FONT_NAME_MONOSPACED\n  Radius 9\n}\nskinparam Class {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam ClassAttribute {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam ClassStereotype {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Footer {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Header {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Hyperlink {\n  Color $ORANGE\n}\nskinparam IconPackage {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam IconPrivate {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam IconProtected {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam IconPublic {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam Note {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Object {\n  BorderColor $FGCOLOR\n}\nskinparam Package {\n  BorderColor $FGCOLOR\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam State {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeA {\n  BackgroundColor $FGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeC {\n  BackgroundColor $FGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeE {\n  BackgroundColor $FGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeI {\n  BackgroundColor $FGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeN {\n  BackgroundColor $FGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam UseCaseStereoType {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\n";
g.PLANTUML_THEMES["aws-orange"]="---\nname: aws-orange\ndisplay_name: AWS orange\ndescription: Theme based off of the colors used by Amazon Web Services\nauthor: Brett Schwarz\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/bschwarz/puml-themes\ninspiration: \n---\n\n!$PUML_THEME = \"aws-orange\"\n!$THEME      = \"aws-orange\"\n''\n'' User can specify the PUML_BGCOLOR via command line or set this variable before\n'' loading this theme file. PUML_BGCOLOR is the background color of the image that is \n'' generated by plantuml\n''\n!if %not(%variable_exists(\"$PUML_BGCOLOR\"))\n    !$PUML_BGCOLOR = \"transparent\"\n!endif\n''\n'' If no gradient is given, default to 20\n''\n!if %not(%variable_exists(\"$PUML_GRADIENT\"))\n    !$PUML_GRADIENT = 20\n!endif\n''\n'' User can specify the PUML_MODE via command line or set this variable before\n'' loading this theme file. PUML_MODE is either 'light' PUML_MODE or 'dark' PUML_MODE.\n''\n!if %not(%variable_exists(\"$PUML_MODE\"))\n    !$PUML_MODE = \"light\"\n!endif\n''\n'' User can specify the PUML_OUTLINE via command line or set this variable before\n'' loading this theme file. PUML_OUTLINE is either 'true' or 'false'.\n''\n!if %not(%variable_exists(\"$PUML_OUTLINE\"))\n    !$PUML_OUTLINE = \"false\"\n!endif\n''\nskinparam BackgroundColor $PUML_BGCOLOR\nskinparam useBetaStyle false\n''\n'' Supplementary Colors\n''\n!$WHITE      = \"#FFF\"\n!$GRAY_LIGHT = \"#222\"\n!$GRAY       = \"#868e96\"\n!$PRIMARY    = \"#EC7211\"\n!$WARNING    = \"#EC7211\"\n!$LIGHT      = \"#abb6c2\"\n!$DARK       = \"#4E5D6C\"\n''\n'' define colors based on PUML_MODE\n''\n!if ($PUML_MODE == \"light\")\n    !$SECONDARY      = \"#eeeeee\"\n    '' hardcode $SECONDARY_LIGHT since it is so close to white\n    !$SECONDARY_LIGHT = \"ffffff\"\n    !$SUCCESS        = \"#1D8102\"\n    !$INFO           = \"#0073bb\"\n    !$DANGER         = \"#d13212\"\n    !$SECONDARY_TEXT = $DARK\n    !$FGCOLOR        = $DARK\n\t!$DIAMOND_BD     = %darken($SECONDARY, $PUML_GRADIENT)\n    ''\n    '' Assume if the background is transparent, that the \n    '' background will be dark for this theme\n    ''\n    !assume transparent light\n!else\n    !$SECONDARY      = \"#2a2e33\"\n    !$SECONDARY_LIGHT = %lighten($SECONDARY, $PUML_GRADIENT)\n    !$SUCCESS        = \"#6aaf35\"\n    !$INFO           = \"#44b9d6\"\n    !$DANGER         = \"#ff5d64\"\n    !$SECONDARY_TEXT = $WHITE\n    !$FGCOLOR        = $WHITE\n\t!$DIAMOND_BD     = %lighten($SECONDARY, $PUML_GRADIENT)\n    ''\n    '' Assume if the background is transparent, that the \n    '' background will be dark for this theme\n    ''\n    !assume transparent dark\n!endif\n''\n'' *_DARK = tint (lighter) of the main color \n'' *_LIGHT = shade (darker) of the main color\n''\n!$PRIMARY_DARK    = %darken($PRIMARY, $PUML_GRADIENT)\n!$PRIMARY_LIGHT   = %lighten($PRIMARY, $PUML_GRADIENT)\n!$SECONDARY_DARK  = %darken($SECONDARY, $PUML_GRADIENT)\n!$SUCCESS_DARK    = %darken($SUCCESS, $PUML_GRADIENT)\n!$SUCCESS_LIGHT   = %lighten($SUCCESS, $PUML_GRADIENT)\n!$INFO_DARK       = %darken($INFO, $PUML_GRADIENT)\n!$INFO_LIGHT      = %lighten($INFO, $PUML_GRADIENT)\n!$DANGER_DARK     = %darken($DANGER, $PUML_GRADIENT)\n!$DANGER_LIGHT    = %lighten($DANGER, $PUML_GRADIENT)\n!$WARNING_DARK    = %darken($WARNING, $PUML_GRADIENT)\n!$WARNING_LIGHT   = %lighten($WARNING, $PUML_GRADIENT)\n!$DARK_DARK       = %darken($DARK, $PUML_GRADIENT)\n!$DARK_LIGHT      = %lighten($DARK, $PUML_GRADIENT)\n!$LIGHT_DARK      = %darken($LIGHT, $PUML_GRADIENT)\n!$LIGHT_LIGHT     = %lighten($LIGHT, $PUML_GRADIENT)\n''\n'' Set text colors\n''\n!$INFO_TEXT    = $WHITE\n!$SUCCESS_TEXT = $WHITE\n!$WARNING_TEXT = $WHITE\n!$DANGER_TEXT  = $WHITE\n!$PRIMARY_TEXT = $WHITE\n!$HEADER_TEXT  = $WHITE\n''\n!if ($PUML_OUTLINE == \"true\")\n\t!$HEADER_TEXT  = $PRIMARY_TEXT\n\t!$PRIMARY_TEXT = $PRIMARY_LIGHT\n\t!$INFO_TEXT    = $INFO_LIGHT\n\t!$WARNING_TEXT = $WARNING_LIGHT\n\t!$DARK_BG      = $PUML_BGCOLOR\n\t!$INFO_BG      = $PUML_BGCOLOR\n\t!$DANGER_BG    = $PUML_BGCOLOR\n\t!$WARNING_BG   = $PUML_BGCOLOR\n\t!$SECONDARY_BG = $PUML_BGCOLOR\n!else\n\t!$DARK_BG      = $DARK\n\t!$INFO_BG      = $INFO\n\t!$DANGER_BG    = $DANGER\n\t!$WARNING_BG   = $WARNING\n\t!$SECONDARY_BG = $SECONDARY\n!endif\n''\n'' Called to make the text in the color of SUCCESS\n''\n!procedure $success($msg)\n  <font color=$SUCCESS><b>$msg\n!endprocedure\n''\n'' Called to make the text in the color of DANGER\n''\n!procedure $failure($msg)\n  <font color=$DANGER><b>$msg\n!endprocedure\n''\n'' Called to make the text in the color of WARNING\n''\n!procedure $warning($msg)\n  <font color=$WARNING><b>$msg\n!endprocedure\n''\n'' Called to use the primary color scheme\n'' Different colors based on if PUML_OUTLINE\n'' is true or not\n''\n!procedure $primary_scheme()\n\t!if ($PUML_OUTLINE == \"true\")\n\t\tFontColor $PRIMARY\n\t\tBorderColor $PRIMARY\n\t\tBackgroundColor $PUML_BGCOLOR\n\t!else\n\t\tFontColor $PRIMARY_TEXT\n\t\tBorderColor $PRIMARY\n\t\tBackgroundColor $PRIMARY_LIGHT-$PRIMARY\n\t!endif\n!endprocedure\n''\n'' Called to use the secondary color scheme\n''\n!procedure $secondary_scheme()\n\t!if ($PUML_OUTLINE == \"true\")\n\t\tFontColor $SECONDARY_DARK\n\t\tBorderColor $SECONDARY_DARK\n\t\tBackgroundColor $PUML_BGCOLOR\n\t!else\n\t\tFontColor $SECONDARY_TEXT\n\t\tBorderColor $SECONDARY_DARK\n\t\tBackgroundColor $SECONDARY_LIGHT-$SECONDARY\n\t!endif\n!endprocedure\n''\n'' HTTP Methods\n''\n!_POST   = \"<color #007a3e>POST</color>\"\n!_PUT    = \"<color #ea7400>PUT</color>\"\n!_DELETE = \"<color #cf2a2a>DELETE</color>\"\n!_GET    = \"<color #009fdb>GET</color>\"\n!_PATCH  = \"<color #b5bd00>PATCH</color>\"\n!_HEAD   = \"<color #9012fe>HEAD</color>\"\n''\n'' Global Default Values\n''\nskinparam defaultFontName       \"Verdana\"\nskinparam defaultFontSize       12\nskinparam dpi                   100\nskinparam shadowing             false\nskinparam roundcorner           8\nskinparam BoxPadding            40\nskinparam ArrowColor            $DARK\nskinparam stereotype {\n    CBackgroundColor $SECONDARY_LIGHT\n    CBorderColor $SECONDARY_DARK\n    ABackgroundColor $SUCCESS_LIGHT\n    ABorderColor $SUCCESS_DARK\n    IBackgroundColor $DANGER_LIGHT\n    IBorderColor $DANGER_DARK\n    EBackgroundColor $WARNING_LIGHT\n    EBorderColor $WARNING_DARK\n    NBackgroundColor $INFO_LIGHT\n    NBorderColor $INFO_DARK\n}\nskinparam title {\n\tFontSize\t    \t         20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tFontColor $PRIMARY\n\tBorderColor $SECONDARY\n}\n\nskinparam legend {\n    $secondary_scheme()\n    BackgroundColor transparent\n}\n\n!startsub swimlane\nskinparam swimlane {\n\tBorderColor $INFO\n\tBorderThickness 2\n\tTitleBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tTitleFontColor $PRIMARY\n}\n!endsub\n\n' <style> \n' mindmapDiagram {\n' \tPadding 15\n' \tMargin 10\n' \tFontSize 12\n' \tFontName Verdana\n' \tShadowing 0.0\n' \tLineThickness 1.5\n' \tFontColor $PRIMARY_TEXT\n' \tLineColor $PRIMARY_DARK\n'     node {\n' \t    LineColor $PRIMARY\n' \t    BackGroundColor $PRIMARY_LIGHT-$PRIMARY\n'     }\n' }\n' </style>\n\n!startsub activity\nskinparam activity {\n\t$primary_scheme()\n\tBarColor $SUCCESS\n\tStartColor $INFO\n\tEndColor $INFO\n\t''\n\tDiamondBackgroundColor $SECONDARY_BG\n  \tDiamondBorderColor $DIAMOND_BD\n  \tDiamondFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub participant\nskinparam participant {\n\t$primary_scheme()\n\tParticipantBorderThickness 2\n}\n!endsub\n\n!startsub actor\nskinparam actor {\n\t$primary_scheme()\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub arrow\nskinparam arrow {\n\tThickness 3\n\tColor $PRIMARY\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub sequence\nskinparam sequence {\n\tArrowThickness 3\n\tBorderColor $PRIMARY\n\t' For some reason sequence title font color does not pick up from global\n\tTitleFontColor $PRIMARY\n\tBackgroundColor $PUML_BGCOLOR\n\tStartColor $PRIMARY\n\tEndColor $PRIMARY\n\t''\n\tBoxBackgroundColor $PUML_BGCOLOR\n\tBoxBorderColor $DARK\n\tBoxFontColor $DARK\n\t''\n\tDelayFontColor $DARK\n\t''\n\tLifeLineBorderColor $LIGHT\n\tLifeLineBorderThickness 2\n\tLifeLineBackgroundColor $LIGHT_DARK\n\t''\n\tGroupBorderColor $DARK\n\tGroupFontColor $DARK\n\tGroupHeaderFontColor $INFO\n\tGroupBackgroundColor $SECONDARY\n\tGroupBodyBackgroundColor $PUML_BGCOLOR\n\tGroupHeaderBackgroundColor $PUML_BGCOLOR\n\t''\n\tDividerBackgroundColor $DARK\n    DividerBorderColor $DARK\n    DividerBorderThickness 2\n    DividerFontColor $LIGHT\n\t''\n\tReferenceBackgroundColor $PUML_BGCOLOR\n\tReferenceBorderColor $DARK\n\tReferenceFontColor $DARK\n\tReferenceHeaderFontColor $INFO\n\tReferenceHeaderBackgroundColor $SECONDARY\n\t''\n\tStereotypeFontColor $PRIMARY_TEXT\n\tStereotypeFontSize 12\n}\n!endsub\n\n!startsub partition\nskinparam partition {\n\tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBackgroundColor $PUML_BGCOLOR\n}\n!endsub\n\n!startsub collections\nskinparam collections {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub control\nskinparam control {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub entity\nskinparam entity {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub boundary\nskinparam boundary {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub agent\nskinparam agent {\n\tBackgroundColor $WARNING\n\tBorderColor $WARNING_LIGHT\n\tFontColor $DARK\n}\n!endsub\n\n!startsub note\nskinparam note {\n\tBorderThickness 1\n\tBackgroundColor $INFO_BG\n\tBorderColor $INFO_DARK\n\tFontColor $INFO_TEXT\n}\n!endsub\n\n!startsub artifact\nskinparam artifact {\n\tBackgroundColor $DARK_BG\n\tBorderColor $DARK_DARK\n\tFontColor $LIGHT\n}\n!endsub\n\n!startsub component\nskinparam component {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub interface\nskinparam interface {\n\tBackgroundColor  $DANGER_DARK\n\tBorderColor  $DANGER\n\tFontColor $DARK\n}\n!endsub\n\n!startsub storage\nskinparam storage {\n\tBackgroundColor $WARNING_BG\n  \tBorderColor $WARNING_DARK\n\tFontColor $WARNING_TEXT\n}\n!endsub\n\n!startsub node\nskinparam node {\n\tBackgroundColor  $PUML_BGCOLOR\n\tBorderColor $LIGHT\n\tFontColor $LIGHT\n}\n!endsub\n\n!startsub cloud\nskinparam cloud {\n\tBackgroundColor transparent\n\tBorderColor $DARK\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub database\nskinparam database {\n\t$primary_scheme()\n\tFontColor $FGCOLOR\n\tStereotypeFontColor $FGCOLOR\n}\n!endsub\n\n!startsub class\nskinparam class {\n\t$primary_scheme()\n\tFontColor $HEADER_TEXT\n\tHeaderBackgroundColor $PRIMARY_LIGHT-$PRIMARY\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $PRIMARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub object\nskinparam object {\n\t$primary_scheme()\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $PRIMARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub usecase\nskinparam usecase {\n\t$primary_scheme()\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub rectangle\nskinparam rectangle {\n\tBackgroundColor $PUML_BGCOLOR\n\tFontColor $SECONDARY_TEXT\n\tBorderColor $SECONDARY_TEXT\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub package\nskinparam package {\n\tBackgroundColor $PUML_BGCOLOR\n  \tBorderColor $SECONDARY_TEXT\n\tFontColor $SECONDARY_TEXT\n\tBorderThickness 2\n}\n!endsub\n\n!startsub folder\nskinparam folder {\n\tBackgroundColor $SECONDARY_BG\n  \tBorderColor $WARNING\n\tFontColor $WARNING\n\tBorderThickness 2\n}\n!endsub\n\n!startsub frame\nskinparam frame {\n\tBackgroundColor $SECONDARY_BG\n  \tBorderColor $INFO\n\tFontColor $INFO\n\tBorderThickness 2\n}\n!endsub\n\n!startsub state\nskinparam state {\n\t$primary_scheme()\n\tStartColor $INFO\n\tEndColor $INFO\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub queue\nskinparam queue {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub card\nskinparam card {\n\tBackgroundColor $INFO_BG\n\tBorderColor $INFO_DARK\n\tFontColor $INFO_TEXT\n}\n!endsub\n\n!startsub file\nskinparam file {\n\tBackgroundColor $SECONDARY_BG\n\tBorderColor $LIGHT\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub stack\nskinparam stack {\n\t$primary_scheme()\n}\n!endsub\n\n\n!startsub map\nskinparam map {\n\t$primary_scheme()\n}\n!endsub\n\n''\n'' When mixing skinparam and <style>, it is very important to put <style> after skinparam\n''\n'' Style settings\n''\n<style>\nparticipant {\n  Margin 5 40\n  Padding 15 20\n}\nwbsDiagram, mindmapDiagram {\n  root {\n    BackgroundColor $PUML_BGCOLOR\n    FontColor $PRIMARY_TEXT\n    HyperLinkColor $INFO_BG\n    LineColor $PRIMARY_DARK\n    LineThickness 1\n    Margin 10\n    Padding 6\n    Shadowing 0.0\n  }\n  node {\n    $primary_scheme()\n    Padding 15\n    RoundCorner 20\n  }\n  caption {\n    LineThickness 0\n  }\n  footer {\n    LineThickness 0\n  }\n  groupHeader {\n    BackgroundColor $SECONDARY_BG\n    FontColor $INFO_BG\n    FontStyle bold\n  }\n  header {\n    LineThickness 0\n  }\n  referenceHeader {\n    BackgroundColor $PUML_BGCOLOR\n    FontColor $DARK_BG\n    FontStyle bold\n  }\n  separator {\n    BackgroundColor $FGCOLOR\n    FontColor $PUML_BGCOLOR\n    FontStyle bold\n  }\n  title {\n\tFontSize 20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor  $SECONDARY_LIGHT-$SECONDARY_BG\n\tFontColor $PRIMARY_TEXT\n\tBorderColor $SECONDARY_BG\n  }\n}\nnwdiagDiagram {\n  network {\n    $primary_scheme()    \n    LineColor $PRIMARY_BG\n    LineThickness 1.0\n    FontColor $PRIMARY_DARK\n  }\n  server {\n    $primary_scheme()\n  }\n  arrow {\n    FontColor $PRIMARY_DARK\n    LineColor $PRIMARY_DARK\n  }\n  group {\n    BackGroundColor $LIGHT_BG\n    LineColor $LIGHT_DARK\n    LineThickness 2.0\n    Margin 5\n    Padding 5\n  }\n}\nganttDiagram {\n  task {\n    $primary_scheme()\n\tLineColor $PRIMARY_BG\n    Margin 10 2 2 2\n    Padding 6\n  }\n  note {\n\tFontColor $INFO_TEXT\n\tLineColor $INFO_DARK\n    BackGroundColor $INFO_BG\n  }\n  separator {\n\tLineColor $SECONDARY_BG\n    BackGroundColor $secondary_scheme()\n    FontColor $SECONDARY_TEXT\n  }\n  milestone {\n\tFontColor $INFO_BG\n\tFontSize 16\n\tFontStyle italic\n\tBackGroundColor $DIAMOND_BG\n\tLineColor $SECONDARY_DARK\n  }\n  timeline {\n    BackgroundColor $SECONDARY_BG\n    FontColor $SECONDARY_TEXT\n  }\n  closed {\n\tBackgroundColor $WARNING_DARK\n\tFontColor $WARNING_TEXT\n  }\n}\n</style>\n\n";
g.PLANTUML_THEMES["black-knight"]="---\nname: black-knight\ndisplay_name: Black Knight\ndescription: Colors representing the black knight. Looks best on a dark background.\nauthor: Brett Schwarz\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/bschwarz/puml-themes\ninspiration: \n---\n\n!$THEME = \"black-knight\"\n''\n'' Assume if the background is transparent, that the \n'' background will be dark for this theme\n''\n!assume transparent dark\n''\n'' If no background color is given, then default transparent\n''\n!if %not(%variable_exists(\"$BGCOLOR\"))\n!$BGCOLOR = \"transparent\"\n!endif\n''\n''\n'' If no gradient is given, default to 20\n''\n!if %not(%variable_exists(\"$GRADIENT\"))\n!$GRADIENT = 20\n!endif\n''\nskinparam backgroundColor $BGCOLOR\nskinparam useBetaStyle false\n''\n'' Default color palette to be used in the definitions below\n''\n!$PRIMARY = \"#303030\"\n!$PRIMARY_DARK = %darken($PRIMARY, $GRADIENT)\n!$PRIMARY_LIGHT = %lighten($PRIMARY, $GRADIENT)\n!$PRIMARY_TEXT = \"#fff200\"\n!$SECONDARY = \"#484848\"\n!$SECONDARY_DARK = %darken($SECONDARY, $GRADIENT)\n!$SECONDARY_LIGHT = %lighten($SECONDARY, $GRADIENT)\n!$SECONDARY_TEXT = \"#fefefe\"\n!$SUCCESS = \"#00FF00\"\n!$SUCCESS_DARK = %darken($SUCCESS, $GRADIENT)\n!$SUCCESS_LIGHT = %lighten($SUCCESS, $GRADIENT)\n!$SUCCESS_TEXT = \"ffffff\"\n!$INFO = \"#0060a8\"\n!$INFO_DARK = %darken($INFO, $GRADIENT)\n!$INFO_LIGHT = %lighten($INFO, $GRADIENT)\n!$INFO_TEXT = \"ffffff\"\n!$WARNING = \"#ff8000\"\n!$WARNING_DARK = %darken($WARNING, $GRADIENT)\n!$WARNING_LIGHT = %lighten($WARNING, $GRADIENT)\n!$WARNING_TEXT = \"#222222\"\n!$DANGER = \"#ff0000\"\n!$DANGER_DARK = %darken($DANGER, $GRADIENT)\n!$DANGER_LIGHT = %lighten($DANGER, $GRADIENT)\n!$DANGER_TEXT = \"ffffff\"\n!$LIGHT = \"#fff200\"\n!$DARK = \"#484848\"\n''\n'' proc to highlight text in the success color\n'' \n!procedure $success($msg)\n  <font color=$SUCCESS><b>$msg\n!endprocedure\n''\n'' proc to highlight text in the danger color\n'' \n!procedure $failure($msg)\n  <font color=$DANGER><b>$msg\n!endprocedure\n''\n'' proc to highlight text in the warning color\n'' \n!procedure $warning($msg)\n  <font color=$WARNING><b>$msg\n!endprocedure\n''\n'' proc to highlight text in the info color\n'' \n!procedure $info($msg)\n  <font color=$INFO><b>$msg\n!endprocedure\n''\n'' proc to generate color scheme for primary color\n'' \n!procedure $primary_scheme()\n\tFontColor $PRIMARY_TEXT\n\tBorderColor $PRIMARY_DARK\n\tBackgroundColor $PRIMARY_LIGHT-$PRIMARY_DARK\n!endprocedure\n''\n'' proc to generate color scheme for secondary color\n'' \n!procedure $secondary_scheme()\n\tFontColor $SECONDARY_TEXT\n\tBorderColor $SECONDARY_DARK\n\tBackgroundColor $SECONDARY_LIGHT-$SECONDARY_DARK\n!endprocedure\n\nskinparam  {\n    defaultFontName   \"Verdana\"\n    defaultFontSize   12\n    defaultTextAlignment center\n    shadowing false\n    RoundCorner 10\n    TitleFontSize 18\n    ' TitleFontColor $PRIMARY_TEXT\n}\n''\n'' Style settings\n''\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $PRIMARY_TEXT\n    HyperLinkColor $ORANGE\n    LineColor $PRIMARY_DARK\n    LineThickness 1\n    Margin 10\n    Padding 6\n    Shadowing 0.0\n  }\n  node {\n   Padding 15\n   roundcorner 20\n   BackgroundColor $PRIMARY-$PRIMARY_DARK\n  }\n  caption {\n    LineThickness 0\n  }\n  footer {\n    LineThickness 0\n  }\n  groupHeader {\n    BackgroundColor $SECONDARY\n    FontColor $INFO\n    FontStyle bold\n  }\n  header {\n    LineThickness 0\n  }\n  referenceHeader {\n    BackgroundColor $BGCOLOR\n    FontColor $DARK\n    FontStyle bold\n  }\n  separator {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  title {\n\tFontSize 20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tFontColor $PRIMARY\n\tBorderColor $SECONDARY\n  }\n  nwdiagDiagram {\n\tnetwork {\n\t\t$primary_scheme()    \n\t\tLineColor $PRIMARY\n\t\tLineThickness 1.0\n\t\tFontColor $PRIMARY_LIGHT\n\t}\n\tserver {\n\t\t$primary_scheme()\n\t}\n\tarrow {\n\t\tFontColor $PRIMARY_LIGHT\n\t\tLineColor $PRIMARY_LIGHT\n\t}\n\tgroup {\n\t\tBackGroundColor $LIGHT\n\t\tLineColor $LIGHT_DARK\n\t\tLineThickness 2.0\n\t\tMargin 5\n\t\tPadding 5\n\t}\n  }\n  participant {\n    Margin 5 40\n    Padding 15 20\n  }\n  ganttDiagram {\n\ttask {\n\t\t$primary_scheme()\n\t\tLineColor $PRIMARY\n\t\tMargin 10 2 2 2\n\t\tPadding 6\n\t}\n\tnote {\n\t\tFontColor $INFO_TEXT\n\t\tLineColor $INFO_DARK\n\t\tBackGroundColor $INFO\n\t}\n\tseparator {\n\t\tLineColor $SECONDARY\n\t\tBackGroundColor $SECONDARY-$SECONDARY_DARK\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tmilestone {\n\t\tFontColor $INFO\n\t\tFontSize 16\n\t\tFontStyle italic\n\t\tBackGroundColor $SECONDARY\n\t\tLineColor $SECONDARY_DARK\n\t}\n\ttimeline {\n\t\tBackgroundColor $SECONDARY\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tclosed {\n\t\tBackgroundColor $WARNING_DARK\n\t\tFontColor $WARNING_TEXT\n\t}\n  }\n</style>\n''\n'' Global Default Values\n''\nskinparam defaultFontName       \"Verdana\"\nskinparam defaultFontSize       12\nskinparam dpi                   100\nskinparam shadowing             false\nskinparam roundcorner           8\nskinparam BoxPadding            40\nskinparam ArrowColor            $DARK\nskinparam stereotype {\n    CBackgroundColor $SECONDARY_DARK\n    CBorderColor $SECONDARY_LIGHT\n    ABackgroundColor $SUCCESS_LIGHT\n    ABorderColor $SUCCESS_DARK\n    IBackgroundColor $DANGER_LIGHT\n    IBorderColor $DANGER_DARK\n    EBackgroundColor $WARNING_LIGHT\n    EBorderColor $WARNING_DARK\n    NBackgroundColor $INFO_LIGHT\n    NBorderColor $INFO_DARK\n}\n\nskinparam title {\n\tFontColor\t                 $SECONDARY_TEXT\n\tBorderColor\t                 $SECONDARY_DARK\n\tFontSize\t    \t         20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor              $SECONDARY_LIGHT-$SECONDARY\n}\n\nskinparam legend {\n\tBackgroundColor $PRIMARY\n\tBorderColor $PRIMARY_DARK\n\tFontColor $PRIMARY_TEXT\n}\n\n!startsub swimlane\nskinparam swimlane {\n\tBorderColor $INFO\n\tBorderThickness 2\n\tTitleBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tTitleFontColor $PRIMARY\n}\n!endsub\n\n!startsub activity\nskinparam activity {\n\t$primary_scheme()\n\tBarColor $SUCCESS\n\tStartColor $INFO\n\tEndColor $INFO\n\t''\n\tDiamondBackgroundColor $SECONDARY_LIGHT-$SECONDARY_DARK\n  \tDiamondBorderColor $SECONDARY_DARK\n  \tDiamondFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub participant\nskinparam participant {\n\t$primary_scheme()\n\tParticipantBorderThickness 2\n}\n!endsub\n\n!startsub actor\nskinparam actor {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub arrow\nskinparam arrow {\n\tThickness 3\n\tColor $PRIMARY\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub sequence\nskinparam sequence {\n\tBorderColor $PRIMARY\n\t' For some reason sequence title font color does not pick up from global\n\tTitleFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n\tStartColor $PRIMARY\n\tEndColor $PRIMARY\n\t''\n\tBoxBackgroundColor $BGCOLOR\n\tBoxBorderColor $DARK\n\tBoxFontColor $DARK\n\t''\n\tDelayFontColor $DARK\n\t''\n\tLifeLineBorderColor $SECONDARY\n\tLifeLineBorderThickness 2\n\tLifeLineBackgroundColor $SECONDARY_DARK\n\t''\n\tGroupBorderColor $DARK\n\tGroupFontColor $DARK\n\tGroupHeaderFontColor $INFO\n\tGroupBackgroundColor $SECONDARY\n\tGroupBodyBackgroundColor $BGCOLOR\n\tGroupHeaderBackgroundColor $BGCOLOR\n\t''\n\tDividerBackgroundColor $DARK\n    DividerBorderColor $DARK\n    DividerBorderThickness 2\n    DividerFontColor $LIGHT\n\t''\n\tReferenceBackgroundColor $BGCOLOR\n\tReferenceBorderColor $DARK\n\tReferenceFontColor $SECONDARY_TEXT\n\tReferenceHeaderBackgroundColor $SECONDARY\n\t''\n\tStereotypeFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub partition\nskinparam partition {\n\tBorderColor $PRIMARY\n\tFontColor $PRIMARY_LIGHT\n\tBackgroundColor $BGCOLOR\n}\n!endsub\n\n!startsub collections\nskinparam collections {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub control\nskinparam control {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub entity\nskinparam entity {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub boundary\nskinparam boundary {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub agent\nskinparam agent {\n\tBackgroundColor $WARNING\n\tBorderColor $WARNING_LIGHT\n\tFontColor $DARK\n}\n!endsub\n\n!startsub note\nskinparam note {\n\tBorderThickness 1\n\tBackgroundColor $INFO\n\tBorderColor $INFO_DARK\n\tFontColor $INFO_TEXT\n}\n!endsub\n\n!startsub artifact\nskinparam artifact {\n\tBackgroundColor $SECONDARY_LIGHT-$SECONDARY_DARK\n\tBorderColor $LIGHT\n\tFontColor $LIGHT\n}\n!endsub\n\n!startsub component\nskinparam component {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub interface\nskinparam interface {\n\tBackgroundColor  $DANGER_DARK\n\tBorderColor  $DANGER\n\tFontColor $DARK\n}\n!endsub\n\n!startsub storage\nskinparam storage {\n\tBackgroundColor $WARNING_LIGHT-$WARNING_DARK\n  \tBorderColor $WARNING_DARK\n\tFontColor $WARNING_TEXT\n}\n!endsub\n\n!startsub node\nskinparam node {\n\tBackgroundColor $BGCOLOR\n\tBorderColor $PRIMARY_LIGHT\n\tFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub cloud\nskinparam cloud {\n\tBackgroundColor transparent\n\tBorderColor $PRIMARY_LIGHT\n\tFontColor $LIGHT\n}\n!endsub\n\n!startsub database\nskinparam database {\n\t$primary_scheme()\n\tBackgroundColor  $BGCOLOR\n}\n!endsub\n\n!startsub class\nskinparam class {\n\t$primary_scheme()\n\tHeaderBackgroundColor $SECONDARY_DARK-$SECONDARY\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $LIGHT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub object\nskinparam object {\n\t$primary_scheme()\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub usecase\nskinparam usecase {\n\t$primary_scheme()\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub rectangle\nskinparam rectangle {\n\t$primary_scheme()\n\tBackgroundColor $BGCOLOR\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub package\nskinparam package {\n\t$primary_scheme()\n\tBackgroundColor $BGCOLOR\n\tBorderThickness 2\n}\n!endsub\n\n!startsub folder\nskinparam folder {\n\tBackgroundColor $SECONDARY_LIGHT\n  \tBorderColor $WARNING\n\tFontColor $WARNING\n\tBorderThickness 2\n}\n!endsub\n\n!startsub frame\nskinparam frame {\n\tBackgroundColor $SECONDARY_LIGHT\n  \tBorderColor $INFO\n\tFontColor $INFO\n\tBorderThickness 2\n}\n!endsub\n\n!startsub state\nskinparam state {\n\t$primary_scheme()\n\tStartColor $INFO\n\tEndColor $INFO\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub queue\nskinparam queue {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub card\nskinparam card {\n\tBackgroundColor $INFO_LIGHT-$INFO_DARK\n\tBorderColor $INFO_DARK\n\tFontColor $INFO_TEXT\n}\n!endsub\n\n!startsub file\nskinparam file {\n\tBackgroundColor $SECONDARY_LIGHT-$SECONDARY_DARK\n\tBorderColor $INFO\n\tFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub stack\nskinparam stack {\n\t$primary_scheme()\n}\n!endsub\n\n!if %variable_exists(\"NEWSTYLE\")\n<>\nwbsDiagram {\n    LineColor $PRIMARY\n    BorderThickness 3\n    BackgroundColor $LIGHT\n    FontColor $PRIMARY_TEXT\n    :depth(0) {\n        fontSize 16\n        fontStyle bold\n        fontColor $SECONDARY\n    }\n    :depth(1) {\n        fontSize 14\n        padding 5\n        fontStyle bold\n    }\n    :depth(2) {\n        fontSize 12\n        padding 4\n    }\n    :depth(3) {\n        fontSize 11\n        padding 3\n        fontColor $INFO\n    }\n\n}\n</>\n!endif\n";
g.PLANTUML_THEMES["bluegray"]="---\nname: bluegray\ndisplay_name: Blue Gray\ndescription: A blue gray theme\nauthor: Brett Schwarz\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/bschwarz/puml-themes\ninspiration: \n---\n\n!$THEME = \"bluegray\"\n\n!if %not(%variable_exists(\"$BGCOLOR\"))\n!$BGCOLOR = \"transparent\"\n!endif\n\nskinparam backgroundColor $BGCOLOR\nskinparam useBetaStyle false\n\n\n!$WHITE = \"#fff\"\n!$GRAY_DARK = \"#5a5a5a\"\n!$GRAY = \"#959595\"\n!$PRIMARY = \"#009fdb\"\n!$SECONDARY = \"#f2f2f2\"\n!$SUCCESS = \"#b5bd00\"\n!$INFO = \"#0568ae\"\n!$WARNING = \"#ea7400\"\n!$DANGER = \"#cf2a2a\"\n!$LIGHT = \"#d2d2d2\"\n!$DARK = \"#5a5a5a\"\n\n!$FGCOLOR = $DARK\n!$PRIMARY_LIGHT = \"#33b2e2\"\n!$PRIMARY_DARK = \"#007faf\"\n!$PRIMARY_TEXT = $WHITE\n!$SECONDARY_LIGHT = \"#f5f5f5\"\n!$SECONDARY_DARK = \"#c2c2c2\"\n!$SECONDARY_TEXT = $DARK\n!$INFO_LIGHT = \"#3786be\"\n!$INFO_DARK = \"#04538b\"\n!$INFO_TEXT = $WHITE\n!$SUCCESS_LIGHT = \"#c4ca33\"\n!$SUCCESS_DARK = \"#919700\"\n!$SUCCESS_TEXT = $WHITE\n!$WARNING_LIGHT = \"#ee9033\"\n!$WARNING_DARK = \"#bb5d00\"\n!$WARNING_TEXT = $WHITE\n!$DANGER_LIGHT = \"#d95555\"\n!$DANGER_DARK = \"#a62222\"\n!$DANGER_TEXT = $WHITE\n\n!procedure $success($msg)\n  <font color=$SUCCESS><b>$msg\n!endprocedure\n\n!procedure $failure($msg)\n  <font color=$DANGER><b>$msg\n!endprocedure\n\n!procedure $warning($msg)\n  <font color=$WARNING><b>$msg\n!endprocedure\n\n!procedure $primary_scheme()\n\n\tFontColor $PRIMARY_TEXT\n\tBorderColor $PRIMARY_LIGHT\n\tBackgroundColor $PRIMARY_LIGHT-$PRIMARY\n\n!endprocedure\n\n!procedure $secondary_scheme()\n\tFontColor $SECONDARY_TEXT\n\tBorderColor $SECONDARY_DARK\n\tBackgroundColor $WHITE-#fefefe\n!endprocedure\n''\n'' Style settings\n''\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $PRIMARY_TEXT\n    HyperLinkColor $ORANGE\n    LineColor $PRIMARY_DARK\n    LineThickness 1\n    Margin 10\n    Padding 6\n    Shadowing 0.0\n  }\n  node {\n   Padding 15\n   roundcorner 20\n   BackgroundColor $PRIMARY-$PRIMARY_DARK\n  }\n  caption {\n    LineThickness 0\n  }\n  footer {\n    LineThickness 0\n  }\n  groupHeader {\n    BackgroundColor $SECONDARY\n    FontColor $INFO\n    FontStyle bold\n  }\n  header {\n    LineThickness 0\n  }\n  referenceHeader {\n    BackgroundColor $BGCOLOR\n    FontColor $DARK\n    FontStyle bold\n  }\n  separator {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  title {\n\tFontSize 20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tFontColor $PRIMARY\n\tBorderColor $SECONDARY\n  }\n  nwdiagDiagram {\n\tnetwork {\n\t\t$primary_scheme()    \n\t\tLineColor $PRIMARY\n\t\tLineThickness 1.0\n\t\tFontColor $PRIMARY_DARK\n\t}\n\tserver {\n\t\t$primary_scheme()\n\t}\n\tarrow {\n\t\tFontColor $PRIMARY_DARK\n\t\tLineColor $PRIMARY_DARK\n\t}\n\tgroup {\n\t\tBackGroundColor $LIGHT\n\t\tLineColor $LIGHT_DARK\n\t\tLineThickness 2.0\n\t\tMargin 5\n\t\tPadding 5\n\t}\n  }\n  participant {\n    Margin 5 30\n    Padding 15 20\n  }\n  ganttDiagram {\n\ttask {\n\t\t$primary_scheme()\n\t\tLineColor $PRIMARY\n\t\tMargin 10 2 2 2\n\t\tPadding 6\n\t}\n\tnote {\n\t\tFontColor $INFO_TEXT\n\t\tLineColor $INFO_DARK\n\t\tBackGroundColor $INFO\n\t}\n\tseparator {\n\t\tLineColor $SECONDARY\n\t\tBackGroundColor $SECONDARY-$SECONDARY_DARK\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tmilestone {\n\t\tFontColor $INFO\n\t\tFontSize 16\n\t\tFontStyle italic\n\t\tBackGroundColor $SECONDARY\n\t\tLineColor $SECONDARY_DARK\n\t}\n\ttimeline {\n\t\tBackgroundColor $SECONDARY\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tclosed {\n\t\tBackgroundColor $WARNING_DARK\n\t\tFontColor $WARNING_TEXT\n\t}\n  }\n</style>\n''\n'' Global Default Values\n''\nskinparam defaultFontName        \"Verdana\"\nskinparam defaultFontSize        12\nskinparam dpi                    100\nskinparam shadowing              false\nskinparam roundcorner            20\nskinparam BoxPadding             40\nskinparam ArrowColor             $GRAY\nskinparam stereotype {\n    CBackgroundColor $SECONDARY_LIGHT\n    CBorderColor $SECONDARY_DARK\n    ABackgroundColor $SUCCESS_LIGHT\n    ABorderColor $SUCCESS_DARK\n    IBackgroundColor $DANGER_LIGHT\n    IBorderColor $DANGER_DARK\n    EBackgroundColor $WARNING_LIGHT\n    EBorderColor $WARNING_DARK\n    NBackgroundColor $INFO_LIGHT\n    NBorderColor $INFO_DARK\n}\nskinparam title {\n\tFontColor\t                 $PRIMARY\n\tBorderColor\t                 $SECONDARY_DARK\n\tFontSize\t    \t         20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor              $SECONDARY_LIGHT-$SECONDARY\n}\n\n\nskinparam legend {\n\tBackgroundColor $SECONDARY\n\tBorderColor $SECONDARY_DARK\n\tFontColor $DARK\n}\n\n!startsub swimlane\nskinparam swimlane {\n\tBorderColor $INFO\n\tBorderThickness 2\n\tTitleBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tTitleFontColor $PRIMARY\n}\n!endsub\n\n!startsub activity\n\nskinparam activity {\n\tFontColor $PRIMARY_TEXT\n\tBorderColor $PRIMARY\n\tBackgroundColor $PRIMARY_LIGHT-$PRIMARY\n\tBarColor $SUCCESS\n\tStartColor $INFO\n\tEndColor $INFO\n\t''\n\tDiamondBackgroundColor $SECONDARY_LIGHT-$SECONDARY_DARK\n  \tDiamondBorderColor $SECONDARY_DARK\n\tDiamondFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub participant\n\nskinparam participant {\n\t$primary_scheme()\n\tParticipantBorderThickness 2\n}\n!endsub\n\n!startsub actor\n\nskinparam actor {\n\t$primary_scheme()\n\tFontColor $PRIMARY\n}\n!endsub\n\n!startsub arrow\n\nskinparam arrow {\n\tThickness 3\n\tColor $PRIMARY\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub sequence\n\nskinparam sequence {\n\tBorderColor $PRIMARY\n\t' For some reason sequence title font color does not pick up from global\n\tTitleFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n\tStartColor $PRIMARY\n\tEndColor $PRIMARY\n\t''\n\tBoxBackgroundColor $LIGHT\n\tBoxBorderColor $GRAY\n\tBoxFontColor $DARK\n\t''\n\tDelayFontColor $DARK\n\t''\n\tLifeLineBorderColor $SECONDARY_DARK\n\tLifeLineBorderThickness 2\n\tLifeLineBackgroundColor $SECONDARY_LIGHT\n\t''\n\tGroupBorderColor $GRAY\n\tGroupFontColor $DARK\n\tGroupHeaderFontColor $INFO\n\t''\n\tDividerBackgroundColor $WHITE-$LIGHT\n    DividerBorderColor $GRAY\n    DividerBorderThickness 2\n    DividerFontColor $DARK\n\t''\n\tReferenceBackgroundColor $BGCOLOR\n\tReferenceBorderColor $GRAY\n\tReferenceFontColor $DARK\n\tReferenceHeaderFontColor $INFO\n\t''\n\tStereotypeFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub partition\n\nskinparam partition {\n\tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n}\n!endsub\n\n!startsub collections\n\nskinparam collections {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub control\n\nskinparam control {\n\t$primary_scheme()\n\tFontColor $PRIMARY\n}\n!endsub\n\n!startsub entity\n\nskinparam entity {\n\t$primary_scheme()\n\tFontColor $PRIMARY\n}\n!endsub\n\n!startsub boundary\n\nskinparam boundary {\n\t$primary_scheme()\n\tFontColor $PRIMARY\n}\n!endsub\n\n!startsub agent\n\nskinparam agent {\n\tBackgroundColor #orange\n\tBorderColor #999999\n\tFontColor #333333\n}\n!endsub\n\n!startsub note\n\nskinparam note {\n\tBorderThickness 1\n\tBackgroundColor $INFO_LIGHT-$INFO\n\tBorderColor $INFO\n\tFontColor $WHITE\n}\n!endsub\n\n!startsub artifact\n\nskinparam artifact {\n\tBackgroundColor $WHITE-$LIGHT\n\tBorderColor $SECONDARY_DARK\n\tFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub component\n\nskinparam component {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub interface\n\nskinparam interface {\n\tBackgroundColor  $DANGER_LIGHT\n\tBorderColor  $DANGER\n\tFontColor $DARK\n}\n!endsub\n\n!startsub storage\n\nskinparam storage {\n\tBackgroundColor $WARNING_LIGHT-$WARNING\n  \tBorderColor $WARNING\n\tFontColor $WARNING_TEXT\n}\n!endsub\n\n!startsub node\n\nskinparam node {\n\tBackgroundColor $SECONDARY_LIGHT-$SECONDARY\n\tBorderColor $SECONDARY_DARK\n\tFontColor $PRIMARY\n}\n!endsub\n\n!startsub cloud\n\nskinparam cloud {\n\tBackgroundColor #F2FCFE-#eeeeee\n\tBorderColor #F2FCFE\n\tFontColor $PRIMARY\n}\n!endsub\n\n!startsub database\n\nskinparam database {\n\t$primary_scheme()\n\t' FontColor $PRIMARY\n\tBorderColor $PRIMARY_DARK\n\t' BackgroundColor  $BGCOLOR\n}\n!endsub\n\n!startsub class\n\nskinparam class {\n\t$primary_scheme()\n\tHeaderBackgroundColor $PRIMARY_LIGHT-$PRIMARY\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $LIGHT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub object\n\nskinparam object {\n\t$primary_scheme()\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $LIGHT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub usecase\n\nskinparam usecase {\n\t$primary_scheme()\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub rectangle\n\nskinparam rectangle {\n\t$secondary_scheme()\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub package\n\nskinparam package {\n\tFontColor $PRIMARY\n\tBorderColor $PRIMARY_LIGHT\n\tBackgroundColor $BGCOLOR\n\tBorderThickness 2\n}\n!endsub\n\n!startsub folder\n\nskinparam folder {\n\tBackgroundColor $WHITE-$SECONDARY_LIGHT\n  \tBorderColor $WARNING\n\tFontColor $WARNING\n\tBorderThickness 2\n}\n!endsub\n\n!startsub frame\n\nskinparam frame {\n\tBackgroundColor $WHITE-$SECONDARY_LIGHT\n  \tBorderColor $INFO\n\tFontColor $INFO\n\tBorderThickness 2\n}\n!endsub\n\n!startsub state\n\nskinparam state {\n\t$primary_scheme()\n\tBorderColor $PRIMARY_DARK\n\tStartColor $INFO\n\tEndColor $INFO\n\tAttributeFontColor $LIGHT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub queue\n\nskinparam queue {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub card\n\nskinparam card {\n\tBackgroundColor $INFO_LIGHT-$INFO\n\tBorderColor $INFO\n\tFontColor $INFO_TEXT\n}\n!endsub\n\n!startsub file\n\nskinparam file {\n\tBackgroundColor $SECONDARY_LIGHT-$SECONDARY\n\tBorderColor $INFO\n\tFontColor $SECONDARY_TEXT\n\n}\n!endsub\n\n!startsub stack\n\nskinparam stack {\n\t$primary_scheme()\n}\n!endsub\n";
g.PLANTUML_THEMES["blueprint"]="---\nname: blueprint\ndisplay_name: Blueprint\ndescription: A white on blue theme based on the Blueprint reproduction process\nauthor: Matthew Leather\nrelease: \nlicense: \nversion: \nsource: \ninspiration: https://en.wikipedia.org/wiki/Blueprint\n---\n\n!$THEME = \"blueprint\"\n\n!$BGCOLOR = \"#003153\"\n!$FGCOLOR = \"#D9D3D0\"\n\n!ifndef $FONT_NAME\n  !$FONT_NAME = \"Verdana\"\n!endif\n\n!ifndef $FONT_NAME_MONOSPACED\n  !$FONT_NAME_MONOSPACED = \"Courier\"\n!endif\n\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $FGCOLOR\n    FontName $FONT_NAME\n    HyperLinkColor $FGCOLOR\n    LineColor $FGCOLOR\n    LineThickness 1\n    Margin 5\n  }\n  document {\n    caption {\n      LineThickness 0\n    }\n    footer {\n      LineThickness 0\n    }\n    header {\n      LineThickness 0\n    }\n    title {\n      FontSize 22\n      LineThickness 0\n    }\n  }\n  node {\n    MaximumWidth 300\n  }\n  participant {\n    Margin 5 10\n    Padding 5 5\n  }\n</style>\n\nskinparam ArrowLollipopColor $FGCOLOR\nskinparam BackgroundColor $BGCOLOR\nskinparam DefaultFontName $FONT_NAME\nskinparam DefaultMonospacedFontName $FONT_NAME_MONOSPACED\nskinparam LifelineStrategy nosolid\nskinparam SequenceLifeLineBorderColor $FGCOLOR\nskinparam Shadowing false\nskinparam UseBetaStyle true\n\nskinparam Activity {\n  BackgroundColor $BGCOLOR\n  BarColor $FGCOLOR\n  BorderColor $FGCOLOR\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Boundary {\n  FontColor $FGCOLOR\n}\nskinparam Box {\n  Padding 5\n}\nskinparam CircledCharacter {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME_MONOSPACED\n  Radius 9\n}\nskinparam Class {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam ClassAttribute {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam ClassStereotype {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Footer {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Header {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Hyperlink {\n  Color $FGCOLOR\n}\nskinparam IconPackage {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam IconPrivate {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam IconProtected {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam IconPublic {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam Note {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Object {\n  BorderColor $FGCOLOR\n}\nskinparam Package {\n  BorderColor $FGCOLOR\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam State {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeA {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeC {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeE {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeI {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeN {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam UseCaseStereoType {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\n";
g.PLANTUML_THEMES["carbon-gray"]="---\nname: carbon-gray\ndisplay_name: Carbon Gray\ndescription: A gray theme using the IBM Carbon Design Gray palette\nauthor: Bharat Rajagopalan\nrelease: \nlicense: \nversion: \nsource: \ninspiration: https://carbondesignsystem.com/elements/color/overview/\n---\n\n!$THEME = \"carbon-gray\"\n\n'!$BGCOLOR = \"#f5f5f5\"\n\n!if %not(%variable_exists(\"$BGCOLOR\"))\n!$BGCOLOR = \"transparent\"\n!endif\n\nskinparam backgroundColor $BGCOLOR\nskinparam useBetaStyle false\n\n!$RED_80 = '#750e13'\n!$RED_70 = '#a2191f'\n!$RED_60 = '#da1e28'\n!$RED_50 = '#fa4d56'\n!$RED_40 = '#ff8389'\n!$RED_30 = '#ffb3b8'\n!$RED_20 = '#ffd7d9'\n!$RED_10 =  '#fff1f1'\n\n!$CYAN_10 = '#e5f6ff'\n!$CYAN_20 = '#bae6ff'\n!$CYAN_30 = '#82cfff'\n!$CYAN_40 = '#33b1ff'\n!$CYAN_50 = '#1192e8'\n!$CYAN_60 = '#0072c3'\n!$CYAN_70 = '#00539a'\n!$CYAN_80 = '#003a6d'\n\n\n!$PURPLE_80 ='#491d8b'\n!$PURPLE_70 = '#6929c4'\n!$PURPLE_60 = '#8a3ffc'\n!$PURPLE_50 = '#a56eff'\n!$PURPLE_40 = '#be95ff'\n!$PURPLE_30 = '#d4bbff'\n!$PURPLE_20 = '#e8daff'\n!$PURPLE_10 = '#f6f2ff'\n\n!$TEAL_10 = '#d9fbfb'\n!$TEAL_20 = '#9ef0f0'\n!$TEAL_30 = '#3ddbd9'\n!$TEAL_40 = '#08bdba'\n!$TEAL_50 = '#009d9a'\n!$TEAL_60 = '#007d79'\n!$TEAL_70 = '#005d5d'\n!$TEAL_80 = '#004144'\n\n!$GRAY_10 = '#f4f4f4'\n!$GRAY_20 = '#e0e0e0'\n!$GRAY_30 = '#c6c6c6'\n!$GRAY_40 = '#a8a8a8'\n!$GRAY_50 = '#8d8d8d'\n!$GRAY_60 = '#6f6f6f'\n!$GRAY_70 = '#525252'\n!$GRAY_80 = '#393939'\n!$GRAY_90 = '#262626'\n!$GRAY_100 = '#161616'\n!$WHITE = '#FFFFF'\n\n!$GRAY_DARK = $GRAY_100\n!$GRAY = $GRAY_30\n!$LIGHT = $GRAY_70\n!$DARK = $GRAY_90\n\n'' *_LIGHT = tint (lighter) of the main color of 80%\n''          where TINT is calculated by clr + (255-clr) * tint_factor\n'' *_DARK = shade (darker) of the main color of 80%\n''          and SHADE is calculated by clr * (1 - shade_factor)\n''\n!$FGCOLOR = $DARK\n!$PRIMARY = $GRAY_10\n!$PRIMARY_LIGHT = $GRAY_10 \n!$PRIMARY_DARK = $GRAY_30\n!$PRIMARY_TEXT = $DARK\n!$SECONDARY = $GRAY_10 \n!$SECONDARY_LIGHT = $GRAY_10\n!$SECONDARY_DARK = $GRAY_30\n!$SECONDARY_TEXT = $DARK\n!$INFO = $WHITE\n!$INFO_LIGHT = $GRAY_20\n!$INFO_DARK = $GRAY_30\n!$INFO_TEXT = $DARK\n!$SUCCESS = $DARK\n!$SUCCESS_LIGHT = $DARK\n!$SUCCESS_DARK = $DARK\n!$SUCCESS_TEXT = $WHITE\n!$WARNING = $WHITE\n!$WARNING_LIGHT = $WHITE\n!$WARNING_DARK = $WHITE\n!$WARNING_TEXT = $DARK\n!$DANGER = $WHITE\n!$DANGER_LIGHT = $WHITE\n!$DANGER_DARK = $WHITE\n!$DANGER_TEXT = $DARK\n\n!$OTHER_BG = $WHITE\n!$DB_BG = $GRAY\n!$LINE_THICKNESS = 1\n!$BORDER_THICKNESS = 1\n\n!procedure $success($msg)\n  <font color=$SUCCESS><b>$msg\n!endprocedure\n\n!procedure $failure($msg)\n  <font color=$DANGER><b>$msg\n!endprocedure\n\n!procedure $warning($msg)\n  <font color=$WARNING><b>$msg\n!endprocedure\n\n!procedure $primary_scheme()\n\tFontColor $PRIMARY_TEXT\n\tBorderColor $PRIMARY_DARK\n\tBackgroundColor $PRIMARY_LIGHT-$PRIMARY\n\tRoundCorner 0\n!endprocedure\n\n''\n'' Global Default Values\n''\nskinparam defaultFontName        \"IBM Plex Sans, Noto Sans, Verdana\"\nskinparam defaultFontSize        12\n'skinparam dpi                    125\nskinparam shadowing              false\nskinparam roundcorner            0\nskinparam BoxPadding             30\nskinparam ArrowColor             $GRAY\n<style>\nparticipant {\n  Margin 5 30\n  Padding 15 20\n}\n</style>\nskinparam stereotype {\n    CBackgroundColor $SECONDARY_LIGHT\n    CBorderColor $SECONDARY_DARK\n    ABackgroundColor $SUCCESS_LIGHT\n    ABorderColor $SUCCESS_DARK\n    IBackgroundColor $DANGER_LIGHT\n    IBorderColor $DANGER_DARK\n    EBackgroundColor $WARNING_LIGHT\n    EBorderColor $WARNING_DARK\n    NBackgroundColor $INFO_LIGHT\n    NBorderColor $INFO_DARK\n}\nskinparam title {\n\tFontColor\t                 $SECONDARY_TEXT\n\tBorderColor\t                 $SECONDARY\n\tFontSize\t    \t         20\n\tBorderRoundCorner            8\n\tBorderThickness \t         0\n\tBackgroundColor              $BGCOLOR\n}\n\n\nskinparam legend {\n\tBackgroundColor $OTHER_BG\n\tBorderColor $DARK\n\tFontColor $PRIMARY_TEXT\n}\n\n!startsub swimlane\nskinparam swimlane {\n\tBorderColor $PRIMARY\n\tBorderThickness $LINE_THICKNESS\n\tTitleBackgroundColor  $PRIMARY_LIGHT-$PRIMARY\n\tTitleFontColor $PRIMARY_TEXT\n\tBackgroundColor $BG_COLOR\n\tTitleFontStyle bold\n}\n!endsub\n\n!startsub activity\n\nskinparam activity {\n\t$primary_scheme()\n\tBarColor $DARK\n\tStartColor $LIGHT-$DARK\n\tEndColor $LIGHT-$DARK\n\t''\n\tDiamondBackgroundColor $SECONDARY_LIGHT-$SECONDARY\n  \tDiamondBorderColor $SECONDARY\n\tDiamondFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub participant\n\nskinparam participant {\n\t$primary_scheme()\n\tParticipantBorderThickness $BORDER_THICKNESS\n}\n!endsub\n\n!startsub actor\n\nskinparam actor {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub arrow\n\nskinparam arrow {\n\tThickness $LINE_THICKNESS\n\tColor $GRAY\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub sequence\n\nskinparam sequence {\n\tBorderColor $PRIMARY_DARK\n\t' For some reason sequence title font color does not pick up from global\n\tTitleFontColor $SECONDARY_TEXT\n\tBackgroundColor $OTHER_BG\n\tStartColor $PRIMARY\n\tEndColor $PRIMARY\n\t''\n\tBoxBackgroundColor $OTHER_BG\n\tBoxBorderColor $PRIMARY_DARK\n\tBoxFontColor $PRIMARY_TEXT\n\t''\n\tDelayFontColor $PRIMARY_TEXT\n\t''\n\tLifeLineBorderColor $PRIMARY_DARK\n\tLifeLineBorderThickness $LINE_THICKNESS\n\tLifeLineBackgroundColor $PRIMARY\n\t''\n\tGroupBorderColor $PRIMARY_DARK\n\tGroupFontColor $PRIMARY_TEXT\n\tGroupFontStyle bold\n\tGroupHeaderFontColor $INFO_TEXT\n\tGroupBackgroundColor $PRIMARY\n\tGroupBodyBackgroundColor $OTHER_BG\n\tGroupHeaderBackgroundColor $PRIMARY\n\t''\n\tDividerBackgroundColor $PRIMARY\n    DividerBorderColor $PRIMARY_DARK\n    DividerBorderThickness $LINE_THICKNESS\n    DividerFontColor $PRIMARY_TEXT\n\t''\n\tReferenceBackgroundColor $BGCOLOR\n\tReferenceHeaderBorderColor $PRIMARY_DARK\n\tReferenceHeaderBackgroundColor $PRIMARY\n\tReferenceBorderColor $PRIMARY_DARK\n\tReferenceFontColor $DARK\n\tReferenceHeaderFontColor $INFO_TEXT\n\t''\n\tStereotypeFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub partition\n\nskinparam partition {\n\tBorderColor $PRIMARY\n\tFontColor $PRIMARY_TEXT\n\tBackgroundColor $OTHER_BG\n\tfontStyle bold\n}\n!endsub\n\n!startsub collections\n\nskinparam collections {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub control\n\nskinparam control {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub entity\n\nskinparam entity {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub boundary\n\nskinparam boundary {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub agent\n\nskinparam agent {\n\tBackgroundColor $PRIMARY_LIGHT\n\tBorderColor $PRIMARY_DARK\n\tFontColor $PRIMARY_TEXT\n\tRoundCorner 0\n}\n!endsub\n\n!startsub note\n\nskinparam note {\n\tBorderThickness 1\n\tBackgroundColor $INFO_LIGHT-$INFO\n\tBorderColor $DARK\n\tFontColor $INFO_TEXT\n\tRoundCorner 0\n}\n!endsub\n\n!startsub artifact\n\nskinparam artifact {\n\tBackgroundColor $PRIMARY\n\tBorderColor $PRIMARY_DARK\n\tFontColor $DARK\n\tRoundCorner 0\n}\n!endsub\n\n!startsub component\n\nskinparam component {\n\t$primary_scheme()\n\tBackgroundColor $PRIMARY\n\tBorderColor $PRIMARY_DARK\n}\n!endsub\n\n!startsub interface\n\nskinparam interface {\n\tBackgroundColor  $PRIMARY_DARK\n\tBorderColor  $PRIMARY_DARK\n\tFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub storage\n\nskinparam storage {\n\tBackgroundColor $OTHER_BG\n  \tBorderColor $DARK\n\tFontColor $WARNING_TEXT\n}\n!endsub\n\n!startsub node\n\nskinparam node {\n\tBackgroundColor $OTHER_BG\n\tBorderColor $PRIMARY_DARK\n\tFontColor $PRIMARY_TEXT\n\tRoundcorner 0\n}\n!endsub\n\n!startsub cloud\n\nskinparam cloud {\n\tBackgroundColor $OTHER_BG\n\tBorderColor $PRIMARY_DARK\n\tFontColor $PRIMARY_TEXT\n\tRoundcorner 0\n}\n!endsub\n\n!startsub database\n\nskinparam database {\n\t$primary_scheme()\n\tBorderColor $PRIMARY_DARK\n\tBackgroundColor  $OTHER_BG\n\tRoundcorner 0\n}\n!endsub\n\n!startsub class\n\nskinparam class {\n\t$primary_scheme()\n\tHeaderBackgroundColor $PRIMARY_LIGHT-$PRIMARY\n\tStereotypeFontColor $PRIMARY_TEXT\n\tStereotypeFontSize 9\n\tBorderThickness $LINE_THICKNESS\n\tAttributeFontColor $PRIMARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub object\n\nskinparam object {\n\t$primary_scheme()\n\tStereotypeFontColor $PRIMARY_TEXT\n\tBorderThickness $BORDER_THICKNESS\n\tAttributeFontColor $PRIMARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub usecase\n\nskinparam usecase {\n\t$primary_scheme()\n\tBorderThickness $BORDER_THICKNESS\n\tStereotypeFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub rectangle\n\nskinparam rectangle {\n\t$primary_scheme()\n\tBackgroundColor $OTHER_BG\n\tBorderThickness $BORDER_THICKNESS\n\tStereotypeFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub package\n\nskinparam package {\n\t$primary_scheme()\n\tBackgroundColor $OTHER_BG\n\tBorderThickness $BORDER_THICKNESS\n}\n!endsub\n\n!startsub folder\n\nskinparam folder {\n\tBackgroundColor $OTHER_BG\n  \tBorderColor $PRIMARY_DARK\n\tFontColor $WARNING_TEXT\n\tBorderThickness $BORDER_THICKNESS\n\tRoundcorner 0\n}\n!endsub\n\n!startsub frame\n\nskinparam frame {\n\tBackgroundColor $OTHER_BG\n  \tBorderColor $PRIMARY_DARK\n\tFontColor $DARK\n\tBorderThickness $BORDER_THICKNESS\n\tRoundcorner 0\n}\n!endsub\n\n!startsub state\n\nskinparam state {\n\t$primary_scheme()\n\tBorderColor $PRIMARY_DARK\n\tStartColor $INFO\n\tEndColor $INFO\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub queue\n\nskinparam queue {\n\t$primary_scheme()\n\t\n}\n!endsub\n\n!startsub card\n\nskinparam card {\n\tBackgroundColor $OTHER_BG\n\tBorderColor $PRIMARY_DARK\n\tFontColor $INFO_TEXT\n\tRoundCorner 0\n}\n!endsub\n\n!startsub file\n\nskinparam file {\n\tBackgroundColor $SECONDARY_LIGHT-$SECONDARY\n\tBorderColor $SECONDARY_DARK\n\tFontColor $SECONDARY_TEXT\n\tRoundCorner 0\n\n}\n!endsub\n\n!startsub stack\n\nskinparam stack {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub person\n\nskinparam person {\n\t$primary_scheme()\n}\n!endsub\n\n\n!if (%variable_exists(\"LEGACY\"))\n!$LEGACY = \"true\"\n!endif\n\n!if (%getenv(\"LEGACY\") == \"true\")\n!$LEGACY = \"true\"\n!endif\n\n'!if (not %variable_exists(\"$LEGACY\"))\n\nskinparam useBetaStyle true\n\n!startsub mindmap\n\n<style>\n\nboardDiagram {\n\tnode {\n\t$primary_scheme()\n    BackGroundColor  $PRIMARY\n    LineColor $PRIMARY_DARK\n    FontName \"IBM Plex Sans, Noto Sans, Verdana\"\n    'FontColor \n    FontSize 12\n    'FontStyle bold\n    RoundCorner 0\n    'LineThickness 2\n    'LineStyle 10-5\n    separator {\n      LineThickness $LINE_THICKNESS\n      LineColor $PRIMARY_DARK\n      'LineStyle 1-5\n    }\n  }\n}\n\nganttDiagram {\n\t\n  task {\n    BackGroundColor $PRIMARY\n    LineColor $PRIMARY_DARK\n\tFontStyle Bold\n\tFontSize 12\n    unstarted {\n      BackGroundColor $PRIMARY_LIGHT\n      LineColor $PRIMARY_DARK\n\t  'FontColor $RED_80\n    }\n\tPadding 3\n\tMargin 3\n\t\n  }\n  timeline {\n\tLineColor $PRIMARY\n\tFontColor $WHITE\n\tBackgroundColor $DARK\n    FontName Helvetica\n    'FontSize 12\n    FontStyle bold\n\tYearFontColor $WHITE\n\tQuarterFontColor $WHITE\n\tMonthFontColor $WHITE\n\tWeekFontColor $WHITE\n\tWeekdayFontColor $WHITE\n\tDayFontColor $WHITE\n  }\n  arrow {\n\t\t'FontName Helvetica\n\t\t'FontColor red\n\t\tFontSize 12\n\t\tFontStyle bold\n\t\t'BackGroundColor GreenYellow\n\t\tLineColor $PRIMARY_DARK\n\t\t'LineStyle 8.0-13.0\n\t\t'LineThickness 3.0\n\t}\n\n  milestone {\n\t\tFontColor $PRIMARY_TEXT\n\t\tFontSize 12\n\t\tFontStyle  bold\n\t\tBackGroundColor $DARK\n\t\tLineColor $DARK\n\t}\n  separator {\n\t\tBackgroundColor $PRIMARY\n\t\t'LineStyle 8.0-3.0\n\t\tLineColor $PRIMARY\n\t\tLineThickness 1.0\n\t\tFontSize 12\n\t\tFontStyle bold\n\t\tFontColor  $PRIMARY_TEXT\n\t\tMargin 3\n\t\t'Padding 20\n\t}\n\tclosed {\n\t\tBackgroundColor $RED_20\n\t\tFontColor $RED_20\n\t}\n}\n\njsonDiagram {\n  node {\n\t$primary_scheme()\n    BackGroundColor  $PRIMARY\n    LineColor $PRIMARY_DARK\n    FontName \"IBM Plex Sans, Noto Sans, Verdana\"\n    'FontColor \n    FontSize 12\n    'FontStyle bold\n    RoundCorner 0\n    'LineThickness 2\n    'LineStyle 10-5\n    separator {\n      LineThickness $LINE_THICKNESS\n      LineColor $PRIMARY_DARK\n      'LineStyle 1-5\n    }\n  }\n  arrow {\n    BackGroundColor $PRIMARY_DARK\n    LineColor $PRIMARY_DARK\n    LineThickness $LINE_THICKNESS\n    LineStyle 3-6\n  }\n  highlight {\n    BackGroundColor $PRIMARY_DARK\n    FontColor $PRIMARY_TEXT\n    FontStyle italic\n  }\n}\n\n\nmindmapDiagram {\n  'Padding 8\n  'Margin 8\n  LineThickness $LINE_THICKNESS\n  FontColor $PRIMARY_TEXT\n  LineColor $PRIMARY_DARK\n  'BackgroundColor $PRIMARY_LIGHT-$PRIMARY\n  Roundcorner 0\n  node {\n    'Padding 12\n    'Margin 3\n    'HorizontalAlignment center\n    LineColor $PRIMARY_DARK\n    LineThickness $BORDER_THICKNESS\n    BackgroundColor $PRIMARY_LIGHT-$PRIMARY\n    RoundCorner 0\n    MaximumWidth 100\n\tFontColor $DARK\n\t'FontStyle bold\n  }\n}\n\n'Salt Diagram only has limited skinning\nsaltDiagram {\n  BackGroundColor $BG_COLOR\n  'Fontname Monospaced\n  'FontSize 10\n  'FontStyle italic\n  'LineThickness 0.5\n  'LineColor PRIMARY_DARK\n}\n\ntimingDiagram {\n  document {\n    BackGroundColor $BG_COLOR\n\tLineColor $PRIMARY\n\tBorderColor $PRIMARY\n\tFontColor $PRIMARY_TEXT\n\n  }\n  highlight {\n\t BackGroundColor $PRIMARY\n  }\n\n constraintArrow {\n  'LineStyle 2-1\n  LineThickness 2\n  LineColor $RED_80\n  FontColor $RED_80\n  FontStyle bold\n }\n}\n\nwbsDiagram {\n  'Padding 8\n  node {\n    'Padding 12\n    'Margin 3\n    'HorizontalAlignment center\n    LineColor $PRIMARY_DARK\n    LineThickness $BORDER_THICKNESS\n    BackgroundColor $PRIMARY_LIGHT-$PRIMARY\n    RoundCorner 0\n    MaximumWidth 100\n\tFontColor $PRIMARY_TEXT\n\t'FontStyle bold\n  }\n  'Margin 8\n  'LineThickness $LINE_THICKNESS\n  'FontColor $PRIMARY_TEXT\n  'LineColor $PRIMARY\n  'BorderColor $PRIMARY\n  'BackgroundColor $PRIMARY_LIGHT-$PRIMARY\n  'RoundCorner 0\n\n  arrow {\n\t' note that Connectors are actually \"Arrows\"; this may change in the future\n\t' so this means all Connectors and Arrows are now going to be green\n\n    lineColor $PRIMARY_DARK\n    fontColor $PRIMARY_TEXT\n    thickness $LINE_THICKNESS\n  }\n  \n  noteBorderColor $DARK\n}\n\n'Placeholder for adding wirediagram skins\nwireDiagram {\n}\n\nyamlDiagram {\n  node {\n\t$primary_scheme()\n    BackGroundColor  $PRIMARY\n    LineColor $PRIMARY_DARK\n    FontName \"IBM Plex Sans, Noto Sans, Verdana\"\n    'FontColor \n    FontSize 12\n    'FontStyle bold\n    RoundCorner 0\n    'LineThickness 2\n    'LineStyle 10-5\n    separator {\n      LineThickness $LINE_THICKNESS\n      LineColor $PRIMARY_DARK\n      'LineStyle 1-5\n    }\n  }\n  arrow {\n    BackGroundColor $PRIMARY_DARK\n    LineColor $PRIMARY_DARK\n    LineThickness $LINE_THICKNESS\n    LineStyle 3-6\n  }\n  highlight {\n    BackGroundColor $PRIMARY_DARK\n    FontColor $PRIMARY_TEXT\n    FontStyle italic\n  }\n}\n</style>\n!endsub\n'!endif\n";
g.PLANTUML_THEMES["cerulean"]="---\nname: cerulean\ndisplay_name: Cerulean\ndescription: Cerulean theme based off of the bootstrap theme of the same name\nauthor: Brett Schwarz\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/bschwarz/puml-themes\ninspiration: https://bootswatch.com/cerulean/\n---\n\n!$THEME = \"cerulean\"\n\n!if %not(%variable_exists(\"$BGCOLOR\"))\n!$BGCOLOR = \"transparent\"\n!endif\n\nskinparam backgroundColor $BGCOLOR\nskinparam useBetaStyle false\n\n''\n'' Colors taken from the css file of the BS theme\n''\n!$BLUE = \"#033C73\"\n!$INDIGO = \"#6610F2\"\n!$PURPLE = \"#6F42C1\"\n!$PINK = \"#E83E8C\"\n!$RED = \"#C71C22\"\n!$ORANGE = \"#FD7E14\"\n!$YELLOW = \"#DD5600\"\n!$GREEN = \"#73A839\"\n!$TEAL = \"#20C997\"\n!$CYAN = \"#2FA4E7\"\n!$WHITE = \"#FFF\"\n!$GRAY_DARK = \"#343A40\"\n!$GRAY = \"#868E96\"\n!$PRIMARY = \"#2FA4E7\"\n!$SECONDARY = \"#E9ECEF\"\n!$SUCCESS = \"#73A839\"\n!$INFO = \"#033C73\"\n!$WARNING = \"#DD5600\"\n!$DANGER = \"#C71C22\"\n!$LIGHT = \"#F8F9FA\"\n!$DARK = \"#343A40\"\n\n'' *_LIGHT = tint (lighter) of the main color of 80%\n''          where TINT is calculated by clr + (255-clr) * tint_factor\n'' *_DARK = shade (darker) of the main color of 80%\n''          and SHADE is calculated by clr * (1 - shade_factor)\n''\n!$FGCOLOR = $DARK\n!$PRIMARY_LIGHT = \"#59B6EC\"\n!$PRIMARY_DARK = \"#2683B9\"\n!$PRIMARY_TEXT = $WHITE\n!$SECONDARY_LIGHT = \"#EDF0F2\"\n!$SECONDARY_DARK = \"#BABDBF\"\n!$SECONDARY_TEXT = $DARK\n!$INFO_LIGHT = \"#35638F\"\n!$INFO_DARK = \"#02305C\"\n!$INFO_TEXT = $WHITE\n!$SUCCESS_LIGHT = \"#8FB961\"\n!$SUCCESS_DARK = \"#5C862E\"\n!$SUCCESS_TEXT = $WHITE\n!$WARNING_LIGHT = \"#E47833\"\n!$WARNING_DARK = \"#B14500\"\n!$WARNING_TEXT = $WHITE\n!$DANGER_LIGHT = \"#D2494E\"\n!$DANGER_DARK = \"#9F161B\"\n!$DANGER_TEXT = $WHITE\n\n!procedure $success($msg)\n  <font color=$SUCCESS><b>$msg\n!endprocedure\n\n!procedure $failure($msg)\n  <font color=$DANGER><b>$msg\n!endprocedure\n\n!procedure $warning($msg)\n  <font color=$WARNING><b>$msg\n!endprocedure\n\n!procedure $primary_scheme()\n\tFontColor $PRIMARY_TEXT\n\tBorderColor $PRIMARY\n\tBackgroundColor $PRIMARY_LIGHT-$PRIMARY\n!endprocedure\n''\n'' Style settings\n''\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $PRIMARY_TEXT\n    HyperLinkColor $ORANGE\n    LineColor $PRIMARY_DARK\n    LineThickness 1\n    Margin 10\n    Padding 6\n    Shadowing 0.0\n  }\n  node {\n   Padding 15\n   roundcorner 20\n   BackgroundColor $PRIMARY-$PRIMARY_DARK\n  }\n  caption {\n    LineThickness 0\n  }\n  footer {\n    LineThickness 0\n  }\n  groupHeader {\n    BackgroundColor $SECONDARY\n    FontColor $INFO\n    FontStyle bold\n  }\n  header {\n    LineThickness 0\n  }\n  referenceHeader {\n    BackgroundColor $BGCOLOR\n    FontColor $DARK\n    FontStyle bold\n  }\n  separator {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  title {\n\tFontSize 20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tFontColor $PRIMARY\n\tBorderColor $SECONDARY\n  }\n  nwdiagDiagram {\n\tnetwork {\n\t\t$primary_scheme()    \n\t\tLineColor $PRIMARY\n\t\tLineThickness 1.0\n\t\tFontColor $PRIMARY_DARK\n\t}\n\tserver {\n\t\t$primary_scheme()\n\t}\n\tarrow {\n\t\tFontColor $PRIMARY_DARK\n\t\tLineColor $PRIMARY_DARK\n\t}\n\tgroup {\n\t\tBackGroundColor $LIGHT\n\t\tLineColor $LIGHT_DARK\n\t\tLineThickness 2.0\n\t\tMargin 5\n\t\tPadding 5\n\t}\n  }\n  participant {\n    Margin 5 40\n    Padding 15 20\n  }\n  ganttDiagram {\n\ttask {\n\t\t$primary_scheme()\n\t\tLineColor $PRIMARY\n\t\tMargin 10 2 2 2\n\t\tPadding 6\n\t}\n\tnote {\n\t\tFontColor $INFO_TEXT\n\t\tLineColor $INFO_DARK\n\t\tBackGroundColor $INFO\n\t}\n\tseparator {\n\t\tLineColor $SECONDARY\n\t\tBackGroundColor $SECONDARY-$SECONDARY_DARK\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tmilestone {\n\t\tFontColor $INFO\n\t\tFontSize 16\n\t\tFontStyle italic\n\t\tBackGroundColor $SECONDARY\n\t\tLineColor $SECONDARY_DARK\n\t}\n\ttimeline {\n\t\tBackgroundColor $SECONDARY\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tclosed {\n\t\tBackgroundColor $WARNING_DARK\n\t\tFontColor $WARNING_TEXT\n\t}\n  }\n</style>\n''\n'' Global Default Values\n''\nskinparam defaultFontName        \"Verdana\"\nskinparam defaultFontSize        12\nskinparam dpi                    100\nskinparam shadowing              false\nskinparam roundcorner            8\nskinparam BoxPadding             40\nskinparam ArrowColor             $GRAY\nskinparam stereotype {\n    CBackgroundColor $SECONDARY_LIGHT\n    CBorderColor $SECONDARY_DARK\n    ABackgroundColor $SUCCESS_LIGHT\n    ABorderColor $SUCCESS_DARK\n    IBackgroundColor $DANGER_LIGHT\n    IBorderColor $DANGER_DARK\n    EBackgroundColor $WARNING_LIGHT\n    EBorderColor $WARNING_DARK\n    NBackgroundColor $INFO_LIGHT\n    NBorderColor $INFO_DARK\n}\nskinparam title {\n\tFontColor\t                 $PRIMARY\n\tBorderColor\t                 $SECONDARY_DARK\n\tFontSize\t    \t         20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor              $SECONDARY_LIGHT-$SECONDARY\n}\n\n\nskinparam legend {\n\tBackgroundColor $SECONDARY\n\tBorderColor $SECONDARY_DARK\n\tFontColor $DARK\n}\n\n!startsub swimlane\nskinparam swimlane {\n\tBorderColor $INFO\n\tBorderThickness 2\n\tTitleBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tTitleFontColor $PRIMARY\n}\n!endsub\n\n!startsub activity\n\nskinparam activity {\n\t$primary_scheme()\n\tBarColor $SUCCESS\n\tStartColor $INFO\n\tEndColor $INFO\n\t''\n\tDiamondBackgroundColor $WHITE-$SECONDARY_LIGHT\n  \tDiamondBorderColor $SECONDARY_DARK\n\tDiamondFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub participant\n\nskinparam participant {\n\t$primary_scheme()\n\tParticipantBorderThickness 2\n}\n!endsub\n\n!startsub actor\n\nskinparam actor {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub arrow\n\nskinparam arrow {\n\tThickness 3\n\tColor $PRIMARY\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub sequence\n\nskinparam sequence {\n\tBorderColor $PRIMARY\n\t' For some reason sequence title font color does not pick up from global\n\tTitleFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n\tStartColor $PRIMARY\n\tEndColor $PRIMARY\n\t''\n\tBoxBackgroundColor $LIGHT\n\tBoxBorderColor $GRAY\n\tBoxFontColor $DARK\n\t''\n\tDelayFontColor $DARK\n\t''\n\tLifeLineBorderColor $SECONDARY_DARK\n\tLifeLineBorderThickness 2\n\tLifeLineBackgroundColor $SECONDARY_LIGHT\n\t''\n\tGroupBorderColor $GRAY\n\tGroupFontColor $DARK\n\tGroupHeaderFontColor $INFO\n\t''\n\tDividerBackgroundColor $WHITE-$LIGHT\n    DividerBorderColor $GRAY\n    DividerBorderThickness 2\n    DividerFontColor $DARK\n\t''\n\tReferenceBackgroundColor $BGCOLOR\n\tReferenceBorderColor $GRAY\n\tReferenceFontColor $DARK\n\tReferenceHeaderFontColor $INFO\n\t''\n\tStereotypeFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub partition\n\nskinparam partition {\n\tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n}\n!endsub\n\n!startsub collections\n\nskinparam collections {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub control\n\nskinparam control {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub entity\n\nskinparam entity {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub boundary\n\nskinparam boundary {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub agent\n\nskinparam agent {\n\tBackgroundColor #orange\n\tBorderColor #999999\n\tFontColor #333333\n}\n!endsub\n\n!startsub note\n\nskinparam note {\n\tBorderThickness 1\n\tBackgroundColor $INFO_LIGHT-$INFO\n\tBorderColor $INFO\n\tFontColor $WHITE\n}\n!endsub\n\n!startsub artifact\n\nskinparam artifact {\n\tBackgroundColor $WHITE-$LIGHT\n\tBorderColor $SECONDARY_DARK\n\tFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub component\n\nskinparam component {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub interface\n\nskinparam interface {\n\tBackgroundColor  $DANGER_LIGHT\n\tBorderColor  $DANGER\n\tFontColor $DARK\n}\n!endsub\n\n!startsub storage\n\nskinparam storage {\n\tBackgroundColor $WARNING_LIGHT-$WARNING\n  \tBorderColor $WARNING\n\tFontColor $WARNING_TEXT\n}\n!endsub\n\n!startsub node\n\nskinparam node {\n\tBackgroundColor $SECONDARY_LIGHT-$SECONDARY\n\tBorderColor $SECONDARY\n\tFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub cloud\n\nskinparam cloud {\n\tBackgroundColor #F2FCFE-#eeeeee\n\tBorderColor #F2FCFE\n\tFontColor $PRIMARY\n}\n!endsub\n\n!startsub database\n\nskinparam database {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub class\n\nskinparam class {\n\t$primary_scheme()\n\tHeaderBackgroundColor $PRIMARY-$PRIMARY_DARK\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $LIGHT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub object\n\nskinparam object {\n\t$primary_scheme()\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub usecase\n\nskinparam usecase {\n\t$primary_scheme()\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub rectangle\n\nskinparam rectangle {\n\tFontColor $PRIMARY\n\tBorderColor $PRIMARY_LIGHT\n\tBackgroundColor $BGCOLOR\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub package\n\nskinparam package {\n\tFontColor $PRIMARY\n\tBorderColor $PRIMARY_LIGHT\n\tBackgroundColor $BGCOLOR\n\tBorderThickness 2\n}\n!endsub\n\n!startsub folder\n\nskinparam folder {\n\tBackgroundColor $WHITE-$SECONDARY_LIGHT\n  \tBorderColor $WARNING\n\tFontColor $WARNING\n\tBorderThickness 2\n}\n!endsub\n\n!startsub frame\n\nskinparam frame {\n\tBackgroundColor $WHITE-$SECONDARY_LIGHT\n  \tBorderColor $INFO\n\tFontColor $INFO\n\tBorderThickness 2\n}\n!endsub\n\n!startsub state\n\nskinparam state {\n\t$primary_scheme()\n\tBorderColor $PRIMARY_DARK\n\tStartColor $INFO\n\tEndColor $INFO\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub queue\n\nskinparam queue {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub card\n\nskinparam card {\n\tBackgroundColor $INFO_LIGHT-$INFO\n\tBorderColor $INFO\n\tFontColor $INFO_TEXT\n}\n!endsub\n\n!startsub file\n\nskinparam file {\n\tBackgroundColor $SECONDARY_LIGHT-$SECONDARY\n\tBorderColor $INFO\n\tFontColor $GRAY\n\n}\n!endsub\n\n!startsub stack\n\nskinparam stack {\n\t$primary_scheme()\n}\n!endsub\n";
g.PLANTUML_THEMES["cerulean-outline"]="---\nname: cerulean-outline\ndisplay_name: Cerulean Outline\ndescription: Cerulean theme based off of the bootstrap theme of the same name, with outline colors\nauthor: Brett Schwarz\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/bschwarz/puml-themes\ninspiration: https://bootswatch.com/cerulean/\n---\n\n!$THEME = \"cerulean-outline\"\n\n!if %not(%variable_exists(\"$BGCOLOR\"))\n!$BGCOLOR = \"transparent\"\n!endif\n\nskinparam backgroundColor $BGCOLOR\nskinparam useBetaStyle false\n\n''\n'' Colors taken from the css file of the BS theme\n''\n!$BLUE = \"#033C73\"\n!$INDIGO = \"#6610F2\"\n!$PURPLE = \"#6F42C1\"\n!$PINK = \"#E83E8C\"\n!$RED = \"#C71C22\"\n!$ORANGE = \"#FD7E14\"\n!$YELLOW = \"#DD5600\"\n!$GREEN = \"#73A839\"\n!$TEAL = \"#20C997\"\n!$CYAN = \"#2FA4E7\"\n!$WHITE = \"#FFF\"\n!$GRAY_DARK = \"#343A40\"\n!$GRAY = \"#868E96\"\n!$PRIMARY = \"#2FA4E7\"\n!$SECONDARY = \"#E9ECEF\"\n!$SUCCESS = \"#73A839\"\n!$INFO = \"#033C73\"\n!$WARNING = \"#DD5600\"\n!$DANGER = \"#C71C22\"\n!$LIGHT = \"#F8F9FA\"\n!$DARK = \"#343A40\"\n\n'' *_LIGHT = tint (lighter) of the main color of 80%\n''          where TINT is calculated by clr + (255-clr) * tint_factor\n'' *_DARK = shade (darker) of the main color of 80%\n''          and SHADE is calculated by clr * (1 - shade_factor)\n''\n!$FGCOLOR = $DARK\n!$PRIMARY_LIGHT = \"#59B6EC\"\n!$PRIMARY_DARK = \"#2683B9\"\n!$PRIMARY_TEXT = $PRIMARY\n!$SECONDARY_LIGHT = \"#EDF0F2\"\n!$SECONDARY_DARK = \"#BABDBF\"\n!$SECONDARY_TEXT = $SECONDARY_DARK\n!$INFO_LIGHT = \"#35638F\"\n!$INFO_TEXT = $INFO\n!$SUCCESS_LIGHT = \"#8FB961\"\n!$SUCCESS_TEXT = $SUCCESS\n!$WARNING_LIGHT = \"#E47833\"\n!$WARNING_TEXT = $WARNING\n!$DANGER_LIGHT = \"#D2494E\"\n!$DANGER_TEXT = $WHITE\n\n!procedure $success($msg)\n  <font color=$SUCCESS><b>$msg\n!endprocedure\n\n!procedure $failure($msg)\n  <font color=$DANGER><b>$msg\n!endprocedure\n\n!procedure $warning($msg)\n  <font color=$WARNING><b>$msg\n!endprocedure\n\n!procedure $primary_scheme()\n\tFontColor $PRIMARY_TEXT\n\tBorderColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n!endprocedure\n''\n'' Style settings\n''\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $PRIMARY_TEXT\n    HyperLinkColor $ORANGE\n    LineColor $PRIMARY_DARK\n    LineThickness 1\n    Margin 10\n    Padding 6\n    Shadowing 0.0\n  }\n  node {\n   Padding 15\n   roundcorner 20\n   BackgroundColor $BGCOLOR\n  }\n  caption {\n    LineThickness 0\n  }\n  footer {\n    LineThickness 0\n  }\n  groupHeader {\n    BackgroundColor $SECONDARY\n    FontColor $INFO\n    FontStyle bold\n  }\n  header {\n    LineThickness 0\n  }\n  referenceHeader {\n    BackgroundColor $BGCOLOR\n    FontColor $DARK\n    FontStyle bold\n  }\n  separator {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  title {\n\tFontSize 20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor  $BGCOLOR\n\tFontColor $PRIMARY\n\tBorderColor $SECONDARY\n  }\n  nwdiagDiagram {\n\tnetwork {\n\t\t$primary_scheme()    \n\t\tLineColor $PRIMARY\n\t\tLineThickness 1.0\n\t\tFontColor $PRIMARY_DARK\n\t}\n\tserver {\n\t\t$primary_scheme()\n\t}\n\tarrow {\n\t\tFontColor $PRIMARY_DARK\n\t\tLineColor $PRIMARY_DARK\n\t}\n\tgroup {\n\t\tBackGroundColor $LIGHT\n\t\tLineColor $LIGHT_DARK\n\t\tLineThickness 2.0\n\t\tMargin 5\n\t\tPadding 5\n\t}\n  }\n  participant {\n    Margin 5 40\n    Padding 15 20\n  }\n  \n  ganttDiagram {\n\ttask {\n\t\t$primary_scheme()\n\t\tLineColor $PRIMARY\n\t\tMargin 10 2 2 2\n\t\tPadding 6\n\t}\n\tnote {\n\t\tFontColor $INFO_TEXT\n\t\tLineColor $INFO_DARK\n\t\tBackGroundColor $BGCOLOR\n\t}\n\tseparator {\n\t\tLineColor $SECONDARY_DARK\n\t\tBackGroundColor $BGCOLOR\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tmilestone {\n\t\tFontColor $INFO\n\t\tFontSize 16\n\t\tFontStyle italic\n\t\tBackGroundColor $SECONDARY\n\t\tLineColor $SECONDARY_DARK\n\t}\n\ttimeline {\n\t\tBackgroundColor $SECONDARY\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tclosed {\n\t\tBackgroundColor $WARNING_DARK\n\t\tFontColor $WARNING_TEXT\n\t}\n  }\n</style>\n''\n'' Global Default Values\n''\nskinparam defaultFontName       \"Verdana\"\nskinparam defaultFontSize       12\nskinparam dpi                   100\nskinparam shadowing             false\nskinparam roundcorner           8\nskinparam BoxPadding            40\nskinparam ArrowColor            $GRAY\nskinparam stereotype {\n    CBackgroundColor $SECONDARY_LIGHT\n    CBorderColor $SECONDARY_DARK\n    ABackgroundColor $SUCCESS_LIGHT\n    ABorderColor $SUCCESS_DARK\n    IBackgroundColor $DANGER_LIGHT\n    IBorderColor $DANGER_DARK\n    EBackgroundColor $WARNING_LIGHT\n    EBorderColor $WARNING_DARK\n    NBackgroundColor $INFO_LIGHT\n    NBorderColor $INFO_DARK\n}\nskinparam title {\n\tFontColor\t                 $PRIMARY\n\tBorderColor\t                 $SECONDARY_DARK\n\tFontSize\t    \t         20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor              $BGCOLOR\n}\n\nskinparam legend {\n\tBackgroundColor $BGCOLOR\n\tBorderColor $SECONDARY_DARK\n\tFontColor $DARK\n}\n\n!startsub swimlane\nskinparam swimlane {\n\tBorderColor $INFO\n\tBorderThickness 2\n\tTitleBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tTitleFontColor $PRIMARY\n}\n!endsub\n\n!startsub activity\n\nskinparam activity {\n\t$primary_scheme()\n\tBarColor $SUCCESS\n\tStartColor $INFO\n\tEndColor $INFO\n\t''\n\tDiamondBackgroundColor $BGCOLOR\n  \tDiamondBorderColor $SECONDARY_DARK\n\tDiamondFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub participant\n\nskinparam participant {\n\t$primary_scheme()\n\tParticipantBorderThickness 2\n}\n!endsub\n\n!startsub actor\n\nskinparam actor {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub arrow\n\nskinparam arrow {\n\tThickness 3\n\tColor $PRIMARY\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub sequence\n\nskinparam sequence {\n\tBorderColor $PRIMARY\n\t' For some reason sequence title font color does not pick up from global\n\tTitleFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n\tStartColor $PRIMARY\n\tEndColor $PRIMARY\n\t''\n\tBoxBackgroundColor $BGCOLOR\n\tBoxBorderColor $GRAY\n\tBoxFontColor $DARK\n\t''\n\tDelayFontColor $DARK\n\t''\n\tLifeLineBorderColor $SECONDARY_DARK\n\tLifeLineBorderThickness 2\n\tLifeLineBackgroundColor $BGCOLOR\n\t''\n\tGroupBorderColor $GRAY\n\tGroupFontColor $DARK\n\tGroupHeaderFontColor $INFO_TEXT\n\t''\n\tDividerBackgroundColor $LIGHT\n    DividerBorderColor $GRAY\n    DividerBorderThickness 2\n    DividerFontColor $DARK\n\t''\n\tReferenceBackgroundColor $BGCOLOR\n\tReferenceBorderColor $GRAY\n\tReferenceFontColor $DARK\n\tReferenceHeaderFontColor $INFO_TEXT\n\t''\n\tStereotypeFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub partition\n\nskinparam partition {\n\tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n}\n!endsub\n\n!startsub collections\n\nskinparam collections {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub control\n\nskinparam control {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub entity\n\nskinparam entity {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub boundary\n\nskinparam boundary {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub agent\n\nskinparam agent {\n\tBackgroundColor $BGCOLOR\n\tBorderColor #999999\n\tFontColor #333333\n}\n!endsub\n\n!startsub note\n\nskinparam note {\n\tBorderThickness 1\n\tBackgroundColor $BGCOLOR\n\tBorderColor $INFO\n\tFontColor $INFO_TEXT\n}\n!endsub\n\n!startsub artifact\n\nskinparam artifact {\n\tBackgroundColor $BGCOLOR\n\tBorderColor $GRAY\n\tFontColor $GRAY\n}\n!endsub\n\n!startsub component\n\nskinparam component {\n\t$primary_scheme()\n\t' BackgroundColor $BGCOLOR\n\t' BorderColor  $SUCCESS\n\t' FontColor $SUCCESS_TEXT\n}\n!endsub\n\n!startsub interface\n\nskinparam interface {\n\tBackgroundColor  $BGCOLOR\n\tBorderColor  $DANGER\n\tFontColor $DARK\n}\n!endsub\n\n!startsub storage\n\nskinparam storage {\n\tBackgroundColor $BGCOLOR\n  \tBorderColor $WARNING\n\tFontColor $WARNING_TEXT\n}\n!endsub\n\n!startsub node\n\nskinparam node {\n\tBackgroundColor $BGCOLOR\n\tBorderColor $DARK\n\tFontColor $DARK\n}\n!endsub\n\n!startsub cloud\n\nskinparam cloud {\n\tBackgroundColor #F2FCFE-#eeeeee\n\tBorderColor #F2FCFE\n\tFontColor $DARK\n}\n!endsub\n\n!startsub database\n\nskinparam database {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub class\n\nskinparam class {\n\t$primary_scheme()\n\tFontColor $LIGHT\n\tHeaderBackgroundColor $PRIMARY-$PRIMARY_DARK\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $DARK\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub object\n\nskinparam object {\n\t$primary_scheme()\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $SECONDARY_DARK\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub usecase\n\nskinparam usecase {\n\t$primary_scheme()\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub rectangle\n\nskinparam rectangle {\n\t$primary_scheme()\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub package\n\nskinparam package {\n\tBackgroundColor $BGCOLOR\n  \tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBorderThickness 2\n}\n!endsub\n\n!startsub folder\n\nskinparam folder {\n\tBackgroundColor $BGCOLOR\n  \tBorderColor $WARNING\n\tFontColor $WARNING\n\tBorderThickness 2\n}\n!endsub\n\n!startsub frame\n\nskinparam frame {\n\tBackgroundColor $BGCOLOR\n  \tBorderColor $INFO\n\tFontColor $INFO_TEXT\n\tBorderThickness 2\n}\n!endsub\n\n!startsub state\n\nskinparam state {\n\t$primary_scheme()\n\tStartColor $INFO\n\tEndColor $INFO\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub queue\n\nskinparam queue {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub card\n\nskinparam card {\n\tBackgroundColor $BGCOLOR\n\tBorderColor $INFO\n\tFontColor $INFO_TEXT\n}\n!endsub\n\n!startsub file\n\nskinparam file {\n\tBackgroundColor $BGCOLOR\n\tBorderColor $GRAY\n\tFontColor $GRAY\n}\n!endsub\n\n!startsub stack\n\nskinparam stack {\n\t$primary_scheme()\n}\n!endsub\n\n!if (%variable_exists(\"LEGACY\"))\n!$LEGACY = \"true\"\n!endif\n\n!if (%getenv(\"LEGACY\") == \"true\")\n!$LEGACY = \"true\"\n!endif\n\n!if (%variable_exists(\"$LEGACY\"))\n\nskinparam useBetaStyle true\n\n!startsub mindmap\n\n<style>\nstyle mindmapDiagram {\n  'Padding 8\n  Margin 8\n  LineThickness 2.0\n  FontColor $PRIMARY_TEXT\n  LineColor $SECONDARY\n  BackGroundColor $PRIMARY_LIGHT-$PRIMARY\n}\nwbsDiagram {\n  'Padding 8\n  Margin 8\n  LineThickness 2.0\n  FontColor $PRIMARY_TEXT\n  LineColor $PRIMARY\n  BackGroundColor $PRIMARY_LIGHT-$PRIMARY\n}\n</style>\n!endsub\n!endif\n";
g.PLANTUML_THEMES["cloudscape-design"]="---\nname: cloudscape-design\ndisplay_name: Cloudscape design\ndescription: Theme based off of the colors used by Cloudscape design\nauthor: Brett Schwarz\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/bschwarz/puml-themes\ninspiration: https://cloudscape.design/foundation/visual-foundation/data-vis-colors/\n---\n\n'!$PUML_OUTLINE = \"true\"\n'!$PUML_BGCOLOR = \"#0f1b2a\"\n'!$PUML_MODE = \"dark\"\n!$PUML_THEME = \"cloudscape-design\"\n!$THEME      = \"cloudscape-design\"\n''\n'' User can specify the PUML_BGCOLOR via command line or set this variable before\n'' loading this theme file. PUML_BGCOLOR is the background color of the image that is \n'' generated by plantuml\n''\n!if %not(%variable_exists(\"$PUML_BGCOLOR\"))\n    !$PUML_BGCOLOR = \"transparent\"\n!endif\n''\n'' If no gradient is given, default to 20\n''\n!if %not(%variable_exists(\"$PUML_GRADIENT\"))\n    !$PUML_GRADIENT = 20\n!endif\n''\n'' User can specify the PUML_MODE via command line or set this variable before\n'' loading this theme file. PUML_MODE is either 'light' PUML_MODE or 'dark' PUML_MODE.\n''\n!if %not(%variable_exists(\"$PUML_MODE\"))\n    !$PUML_MODE = \"light\"\n!endif\n''\n'' User can specify the PUML_OUTLINE via command line or set this variable before\n'' loading this theme file. PUML_OUTLINE is either 'true' or 'false'.\n''\n!if %not(%variable_exists(\"$PUML_OUTLINE\"))\n    !$PUML_OUTLINE = \"false\"\n!endif\n''\nskinparam BackgroundColor $PUML_BGCOLOR\nskinparam useBetaStyle false\n!$ALPHA = \"80\"\n''\n'' Supplementary Colors\n''\n!$WHITE      = \"#FFF\"\n!$GRAY_LIGHT = \"#222\"\n!$GRAY       = \"#868e96\"\n!$PRIMARY    = \"#0972d3\"\n!$WARNING    = \"#ecdd00\"\n!$LIGHT      = \"#d1d5db\"\n!$DARK       = \"#000716\"\n!$SECONDARY_TEXT = \"#539fe5\"\n''\n'' define colors based on PUML_MODE\n''\n!if ($PUML_MODE == \"light\")\n    !$PRIMARY_TEXT    = $LIGHT\n    !$SECONDARY       = \"#eeeeee\"\n    !$SECONDARY_LIGHT = %lighten($SECONDARY, $PUML_GRADIENT)\n    !$SUCCESS         = \"#037f0c\"\n    !$INFO            = \"#0972d3\"\n    !$DANGER          = \"#d91515\"\n    !$SECONDARY_TEXT  = $DARK\n    !$FGCOLOR         = $DARK\n    !$DIAMOND_BD      = %darken($SECONDARY, $PUML_GRADIENT)\n    !$GRAY_LIGHT      = %lighten($GRAY, $PUML_GRADIENT)\n    !$GRAY_DARK       = %darken($GRAY, $PUML_GRADIENT)\n\t!$MAIN_BG         = $WHITE\n    ''\n    '' Assume if the background is transparent, that the \n    '' background will be dark for this theme\n    ''\n    !assume transparent light\n!else\n    !$TMP             = $LIGHT\n    !$LIGHT           = $DARK\n    !$DARK            = $TMP\n    !$PRIMARY         = \"#539fe5\"\n    !$PRIMARY_TEXT    = $WHITE\n    !$SECONDARY       = \"#2a2e33\"\n    !$SECONDARY_LIGHT = %lighten($SECONDARY, $PUML_GRADIENT)\n    !$SUCCESS         = \"#037f0c\"\n    !$INFO            = \"#0972d3\"\n    !$DANGER          = \"#ff5d64\"\n\t!$WARNING         = \"#fbf8cc\"\n    !$SECONDARY_TEXT  = $WHITE\n    !$FGCOLOR         = $WHITE\n    !$DIAMOND_BD      = %lighten($SECONDARY, $PUML_GRADIENT)\n    !$GRAY_LIGHT      = %darken($GRAY, $PUML_GRADIENT)\n    !$GRAY_DARK       = %lighten($GRAY, $PUML_GRADIENT)\n\t!$MAIN_BG         = \"#0f1b2a\"\n    ''\n    '' Assume if the background is transparent, that the \n    '' background will be dark for this theme\n    ''\n    !assume transparent dark\n!endif\n''\n'' *_DARK = tint (lighter) of the main color \n'' *_LIGHT = shade (darker) of the main color\n''\n!$PRIMARY_DARK    = %darken($PRIMARY, $PUML_GRADIENT)\n!$PRIMARY_LIGHT   = %lighten($PRIMARY, $PUML_GRADIENT)\n!$SECONDARY_DARK  = %darken($SECONDARY, $PUML_GRADIENT)\n!$SUCCESS_DARK    = %darken($SUCCESS, $PUML_GRADIENT)\n!$SUCCESS_LIGHT   = %lighten($SUCCESS, $PUML_GRADIENT)\n!$INFO_DARK       = %darken($INFO, $PUML_GRADIENT)\n!$INFO_LIGHT      = %lighten($INFO, $PUML_GRADIENT)\n!$DANGER_DARK     = %darken($DANGER, $PUML_GRADIENT)\n!$DANGER_LIGHT    = %lighten($DANGER, $PUML_GRADIENT)\n!$WARNING_DARK    = %darken($WARNING, $PUML_GRADIENT)\n!$WARNING_LIGHT   = %lighten($WARNING, $PUML_GRADIENT)\n!$DARK_DARK       = %darken($DARK, $PUML_GRADIENT)\n!$DARK_LIGHT      = %lighten($DARK, $PUML_GRADIENT)\n!$LIGHT_DARK      = %darken($LIGHT, $PUML_GRADIENT)\n!$LIGHT_LIGHT     = %lighten($LIGHT, $PUML_GRADIENT)\n''\n'' Set text colors\n''\n!$INFO_TEXT    = $WHITE\n!$SUCCESS_TEXT = $WHITE\n!$WARNING_TEXT = $WHITE\n!$DANGER_TEXT  = $WHITE\n!$HEADER_TEXT  = $WHITE\n''\n!if ($PUML_OUTLINE == \"true\")\n\t!$HEADER_TEXT  = $PRIMARY_TEXT\n\t!$PRIMARY_TEXT = $PRIMARY_LIGHT\n\t!$INFO_TEXT    = $INFO\n\t!$WARNING_TEXT = $WARNING_LIGHT\n\t!$DARK_BG      = $PUML_BGCOLOR\n\t!$INFO_BG      = $PUML_BGCOLOR\n\t!$DANGER_BG    = $PUML_BGCOLOR\n\t!$WARNING_BG   = $PUML_BGCOLOR\n\t!$SECONDARY_BG = $PUML_BGCOLOR\n!else\n\t!$DARK_BG      = $DARK\n\t!$INFO_BG      = $INFO\n\t!$DANGER_BG    = $DANGER\n\t!$WARNING_BG   = $WARNING\n\t!$SECONDARY_BG = $SECONDARY\n!endif\n!unquoted function $alpha($color, $alpha) !return $color + $alpha\n''\n'' Called to make the text in the color of SUCCESS\n''\n!procedure $success($msg)\n  <font color=$SUCCESS><b>$msg\n!endprocedure\n''\n'' Called to make the text in the color of DANGER\n''\n!procedure $failure($msg)\n  <font color=$DANGER><b>$msg\n!endprocedure\n''\n'' Called to make the text in the color of WARNING\n''\n!procedure $warning($msg)\n  <font color=$WARNING><b>$msg\n!endprocedure\n''\n'' Called to use the primary color scheme\n'' Different colors based on if PUML_OUTLINE\n'' is true or not\n''\n!procedure $primary_scheme()\n\t!if ($PUML_OUTLINE == \"true\")\n\t\tFontColor $PRIMARY\n\t\tBorderColor $PRIMARY\n\t\tBackgroundColor $PUML_BGCOLOR\n\t!else\n\t\tFontColor $PRIMARY_TEXT\n\t\tBorderColor $PRIMARY\n\t\tBackgroundColor $PRIMARY_LIGHT-$PRIMARY\n\t!endif\n!endprocedure\n''\n'' Called to use the secondary color scheme\n''\n!procedure $secondary_scheme()\n\t!if ($PUML_OUTLINE == \"true\")\n\t\tFontColor $SECONDARY_DARK\n\t\tBorderColor $SECONDARY_DARK\n\t\tBackgroundColor $PUML_BGCOLOR\n\t!else\n\t\tFontColor $SECONDARY_TEXT\n\t\tBorderColor $SECONDARY_DARK\n\t\tBackgroundColor $SECONDARY_LIGHT-$SECONDARY\n\t!endif\n!endprocedure\n''\n'' HTTP Methods\n''\n!_POST   = \"<color #007a3e>POST</color>\"\n!_PUT    = \"<color #ea7400>PUT</color>\"\n!_DELETE = \"<color #cf2a2a>DELETE</color>\"\n!_GET    = \"<color #009fdb>GET</color>\"\n!_PATCH  = \"<color #b5bd00>PATCH</color>\"\n!_HEAD   = \"<color #9012fe>HEAD</color>\"\n''\n'' Global Default Values\n''\nskinparam defaultFontName       \"Verdana\"\nskinparam defaultFontSize       12\nskinparam dpi                   100\nskinparam shadowing             false\nskinparam roundcorner           8\nskinparam BoxPadding            40\nskinparam ArrowColor            $DARK\nskinparam stereotype {\n    CBackgroundColor $SECONDARY_LIGHT\n    CBorderColor $SECONDARY_DARK\n    ABackgroundColor $SUCCESS_LIGHT\n    ABorderColor $SUCCESS_DARK\n    IBackgroundColor $DANGER_LIGHT\n    IBorderColor $DANGER_DARK\n    EBackgroundColor $WARNING_LIGHT\n    EBorderColor $WARNING_DARK\n    NBackgroundColor $INFO_LIGHT\n    NBorderColor $INFO_DARK\n}\nskinparam title {\n\tFontSize\t    \t         20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tFontColor $PRIMARY\n\tBorderColor $SECONDARY\n}\n\nskinparam legend {\n    $secondary_scheme()\n    BackgroundColor transparent\n}\n\n!startsub swimlane\nskinparam swimlane {\n\tBorderColor $INFO\n\tBorderThickness 2\n\tTitleBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tTitleFontColor $PRIMARY\n}\n!endsub\n\n!startsub activity\nskinparam activity {\n\t$primary_scheme()\n\tBarColor $SUCCESS\n\tStartColor $INFO\n\tEndColor $INFO\n\t''\n\tDiamondBackgroundColor $SECONDARY_BG\n  \tDiamondBorderColor $DIAMOND_BD\n  \tDiamondFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub participant\nskinparam participant {\n\t$primary_scheme()\n\tParticipantBorderThickness 2\n}\n!endsub\n\n!startsub actor\nskinparam actor {\n\t$primary_scheme()\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub arrow\nskinparam arrow {\n\tThickness 2\n\tColor $GRAY_LIGHT\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub sequence\nskinparam sequence {\n\tArrowThickness 2\n\tBorderColor $PRIMARY\n\t' For some reason sequence title font color does not pick up from global\n\tTitleFontColor $PRIMARY\n\tBackgroundColor $PUML_BGCOLOR\n\tStartColor $PRIMARY\n\tEndColor $PRIMARY\n\t''\n\tBoxBackgroundColor $alpha($PUML_BGCOLOR, $ALPHA)\n\tBoxBorderColor $GRAY_DARK\n\tBoxFontColor $GRAY_DARK\n\t''\n\tDelayFontColor $LIGHT\n\t''\n\tLifeLineBorderColor $PRIMARY\n\tLifeLineBorderThickness 0\n\tLifeLineBackgroundColor $SECONDARY\n\t''\n\tGroupBorderColor $DARK\n\tGroupBorderThickness 1\n\tGroupFontColor $DARK\n\tGroupHeaderFontColor $INFO\n\tGroupBackgroundColor $alpha($SECONDARY, $ALPHA)\n\tGroupBodyBackgroundColor $alpha($PUML_BGCOLOR, $ALPHA)\n\tGroupHeaderBackgroundColor $PUML_BGCOLOR\n\t''\n\tDividerBackgroundColor $SECONDARY\n\tDividerBorderColor $SECONDARY_LIGHT\n    \tDividerBorderThickness 2\n    \tDividerFontColor $DARK\n\t''\n\tReferenceAlignment left\n\tReferenceBackgroundColor $alpha($PUML_BGCOLOR, $ALPHA)\n\tReferenceBorderColor $SECONDARY\n\tReferenceBorderThickness 2\n\tReferenceFontColor $DARK\n\tReferenceHeaderFontColor $INFO\n\tReferenceHeaderBackgroundColor $alpha($SECONDARY, $ALPHA)\n\t''\n\tStereotypeFontColor $PRIMARY_TEXT\n\tStereotypeFontSize 12\n}\n!endsub\n\n!startsub partition\nskinparam partition {\n\tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBackgroundColor $PUML_BGCOLOR\n}\n!endsub\n\n!startsub collections\nskinparam collections {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub control\nskinparam control {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub entity\nskinparam entity {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub boundary\nskinparam boundary {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub agent\nskinparam agent {\n\tBackgroundColor $WARNING\n\tBorderColor $WARNING_LIGHT\n\tFontColor $GRAY\n}\n!endsub\n\n!startsub note\nskinparam note {\n\tBorderThickness 1\n\tBackgroundColor $INFO_BG\n\tBorderColor $INFO\n\tFontColor $INFO_TEXT\n}\n!endsub\n\n!startsub artifact\nskinparam artifact {\n\tBackgroundColor $DARK_BG\n\tBorderColor $DARK_DARK\n\tFontColor $LIGHT\n}\n!endsub\n\n!startsub component\nskinparam component {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub interface\nskinparam interface {\n\tBackgroundColor  $DANGER_DARK\n\tBorderColor  $DANGER\n\tFontColor $DARK\n}\n!endsub\n\n!startsub storage\nskinparam storage {\n\tBackgroundColor $WARNING_BG\n  \tBorderColor $WARNING_DARK\n\tFontColor $GRAY\n}\n!endsub\n\n!startsub node\nskinparam node {\n\tBackgroundColor  $PUML_BGCOLOR\n\tBorderColor $LIGHT\n\tFontColor $LIGHT\n}\n!endsub\n\n!startsub cloud\nskinparam cloud {\n\tBackgroundColor transparent\n\tBorderColor $DARK\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub database\nskinparam database {\n\t$primary_scheme()\n\tFontColor $FGCOLOR\n\tStereotypeFontColor $FGCOLOR\n}\n!endsub\n\n!startsub class\nskinparam class {\n\t$primary_scheme()\n\tFontColor $HEADER_TEXT\n\tHeaderBackgroundColor $PRIMARY_LIGHT-$PRIMARY\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $PRIMARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub object\nskinparam object {\n\t$primary_scheme()\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $PRIMARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub usecase\nskinparam usecase {\n\t$primary_scheme()\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub rectangle\nskinparam rectangle {\n\tBackgroundColor $PUML_BGCOLOR\n\tFontColor $SECONDARY_TEXT\n\tBorderColor $SECONDARY_TEXT\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub package\nskinparam package {\n\tBackgroundColor $PUML_BGCOLOR\n  \tBorderColor $SECONDARY_TEXT\n\tFontColor $SECONDARY_TEXT\n\tBorderThickness 2\n}\n!endsub\n\n!startsub folder\nskinparam folder {\n\tBackgroundColor $SECONDARY_BG\n  \tBorderColor $WARNING\n\tFontColor $WARNING\n\tBorderThickness 2\n}\n!endsub\n\n!startsub frame\nskinparam frame {\n\tBackgroundColor $SECONDARY_BG\n  \tBorderColor $INFO\n\tFontColor $INFO\n\tBorderThickness 2\n}\n!endsub\n\n!startsub state\nskinparam state {\n\t$primary_scheme()\n\tStartColor $INFO\n\tEndColor $INFO\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub queue\nskinparam queue {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub card\nskinparam card {\n\tBackgroundColor $INFO_BG\n\tBorderColor $INFO_DARK\n\tFontColor $INFO_TEXT\n}\n!endsub\n\n!startsub file\nskinparam file {\n\tBackgroundColor $SECONDARY_BG\n\tBorderColor $LIGHT\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub stack\nskinparam stack {\n\t$primary_scheme()\n}\n!endsub\n\n\n!startsub map\nskinparam map {\n\t$primary_scheme()\n}\n!endsub\n\n''\n'' When mixing skinparam and <style>, it is very important to put <style> after skinparam\n''\n'' Style settings\n''\n<style>\nparticipant {\n  Margin 5 40\n  Padding 15 20\n}\nwbsDiagram, mindmapDiagram {\n  root {\n    BackgroundColor $PUML_BGCOLOR\n    FontColor $PRIMARY_TEXT\n    HyperLinkColor $INFO_BG\n    LineColor $PRIMARY_DARK\n    LineThickness 1\n    Margin 10\n    Padding 6\n    Shadowing 0.0\n  }\n  node {\n    $primary_scheme()\n    Padding 15\n    RoundCorner 20\n  }\n  caption {\n    LineThickness 0\n  }\n  footer {\n    LineThickness 0\n  }\n  groupHeader {\n    BackgroundColor $SECONDARY_BG\n    FontColor $INFO_BG\n    FontStyle bold\n  }\n  header {\n    LineThickness 0\n  }\n  referenceHeader {\n    BackgroundColor $PUML_BGCOLOR\n    FontColor $DARK_BG\n    FontStyle bold\n  }\n  separator {\n    BackgroundColor $FGCOLOR\n    FontColor $PUML_BGCOLOR\n    FontStyle bold\n  }\n  title {\n\tFontSize 20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor  $SECONDARY_LIGHT-$SECONDARY_BG\n\tFontColor $PRIMARY_TEXT\n\tBorderColor $SECONDARY_BG\n  }\n}\nnwdiagDiagram {\n  network {\n    $primary_scheme()    \n    LineColor $PRIMARY_BG\n    LineThickness 1.0\n    FontColor $PRIMARY_DARK\n  }\n  server {\n    $primary_scheme()\n  }\n  arrow {\n    FontColor $PRIMARY_DARK\n    LineColor $PRIMARY_DARK\n  }\n  group {\n    BackGroundColor $LIGHT_BG\n    LineColor $LIGHT_DARK\n    LineThickness 2.0\n    Margin 5\n    Padding 5\n  }\n}\nganttDiagram {\n  task {\n    $primary_scheme()\n\tLineColor $PRIMARY_BG\n    Margin 10 2 2 2\n    Padding 6\n  }\n  note {\n\tFontColor $INFO_TEXT\n\tLineColor $INFO_DARK\n    BackGroundColor $INFO_BG\n  }\n  separator {\n\tLineColor $SECONDARY_BG\n    BackGroundColor $secondary_scheme()\n    FontColor $SECONDARY_TEXT\n  }\n  milestone {\n\tFontColor $INFO_BG\n\tFontSize 16\n\tFontStyle italic\n\tBackGroundColor $DIAMOND_BG\n\tLineColor $SECONDARY_DARK\n  }\n  timeline {\n    BackgroundColor $SECONDARY_BG\n    FontColor $SECONDARY_TEXT\n  }\n  closed {\n\tBackgroundColor $WARNING_DARK\n\tFontColor $WARNING_TEXT\n  }\n}\n</style>\n\n";
g.PLANTUML_THEMES["crt-amber"]="---\nname: crt-amber\ndisplay_name: Cathode-ray tube (CRT) amber\ndescription: An orange on black theme based on monochrome CRT monitors\nauthor: Matthew Leather\nrelease: \nlicense: \nversion: \nsource: \ninspiration: https://superuser.com/a/1206781\n---\n\n!$THEME = \"crt-amber\"\n\n!$DARK_AMBER  = \"#FFB000\"\n!$LIGHT_AMBER = \"#FFCC00\"\n\n!$BGCOLOR = \"#282828\"\n!$FGCOLOR = $DARK_AMBER\n\n!ifndef $FONT_NAME\n  !$FONT_NAME = \"Verdana\"\n!endif\n\n!ifndef $FONT_NAME_MONOSPACED\n  !$FONT_NAME_MONOSPACED = \"Courier\"\n!endif\n\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $FGCOLOR\n    FontName $FONT_NAME\n    HyperLinkColor $LIGHT_AMBER\n    LineColor $FGCOLOR\n    LineThickness 1\n    Margin 5\n  }\n  box {\n    LineStyle 12-18\n    LineThickness 3\n  }\n  document {\n    caption {\n      LineThickness 0\n    }\n    footer {\n      LineThickness 0\n    }\n    header {\n      LineThickness 0\n    }\n    title {\n      FontSize 22\n      LineThickness 0\n    }\n  }\n  groupHeader {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  node {\n    MaximumWidth 300\n  }\n  referenceHeader {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  separator {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  participant {\n    Margin 5 10\n    Padding 5 5\n  }\n</style>\n\nskinparam ArrowLollipopColor $FGCOLOR\nskinparam BackgroundColor $BGCOLOR\nskinparam DefaultFontName $FONT_NAME\nskinparam DefaultMonospacedFontName $FONT_NAME_MONOSPACED\nskinparam LifelineStrategy solid\nskinparam SequenceLifeLineBorderColor $FGCOLOR\nskinparam Shadowing false\nskinparam UseBetaStyle true\n\nskinparam Activity {\n  BackgroundColor $BGCOLOR\n  BarColor $FGCOLOR\n  BorderColor $FGCOLOR\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Boundary {\n  FontColor $FGCOLOR\n}\nskinparam Box {\n  Padding 5\n}\nskinparam CircledCharacter {\n  FontColor $BGCOLOR\n  FontName $FONT_NAME_MONOSPACED\n  Radius 9\n}\nskinparam Class {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam ClassAttribute {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam ClassStereotype {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Footer {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Header {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Hyperlink {\n  Color $LIGHT_AMBER\n}\nskinparam IconPackage {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam IconPrivate {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam IconProtected {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam IconPublic {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam Note {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Object {\n  BorderColor $FGCOLOR\n}\nskinparam Package {\n  BorderColor $FGCOLOR\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam State {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeA {\n  BackgroundColor $FGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeC {\n  BackgroundColor $FGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeE {\n  BackgroundColor $FGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeI {\n  BackgroundColor $FGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeN {\n  BackgroundColor $FGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam UseCaseStereoType {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\n";
g.PLANTUML_THEMES["crt-green"]="---\nname: crt-green\ndisplay_name: Cathode-ray tube (CRT) green\ndescription: A green on black theme based on monochrome CRT monitors\nauthor: Matthew Leather\nrelease: \nlicense: \nversion: \nsource: \ninspiration: https://superuser.com/a/1206781\n---\n\n!$THEME = \"crt-green\"\n\n!$BGCOLOR = \"#282828\"\n!$FGCOLOR = \"#33FF33\"\n\n!ifndef $FONT_NAME\n  !$FONT_NAME = \"Verdana\"\n!endif\n\n!ifndef $FONT_NAME_MONOSPACED\n  !$FONT_NAME_MONOSPACED = \"Courier\"\n!endif\n\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $FGCOLOR\n    FontName $FONT_NAME\n    HyperLinkColor $FGCOLOR\n    LineColor $FGCOLOR\n    LineThickness 1\n    Margin 5\n  }\n  box {\n    LineStyle 12-18\n    LineThickness 3\n  }\n  document {\n    caption {\n      LineThickness 0\n    }\n    footer {\n      LineThickness 0\n    }\n    header {\n      LineThickness 0\n    }\n    title {\n      FontSize 22\n      LineThickness 0\n    }\n  }\n  groupHeader {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  node {\n    MaximumWidth 300\n  }\n  referenceHeader {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  separator {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  participant {\n    Margin 5 10\n    Padding 5 5\n  }\n</style>\n\nskinparam ArrowLollipopColor $FGCOLOR\nskinparam BackgroundColor $BGCOLOR\nskinparam DefaultFontName $FONT_NAME\nskinparam DefaultMonospacedFontName $FONT_NAME_MONOSPACED\nskinparam LifelineStrategy solid\nskinparam SequenceLifeLineBorderColor $FGCOLOR\nskinparam Shadowing false\nskinparam UseBetaStyle true\n\nskinparam Activity {\n  BackgroundColor $BGCOLOR\n  BarColor $FGCOLOR\n  BorderColor $FGCOLOR\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Boundary {\n  FontColor $FGCOLOR\n}\nskinparam Box {\n  Padding 5\n}\nskinparam CircledCharacter {\n  FontColor $BGCOLOR\n  FontName $FONT_NAME_MONOSPACED\n  Radius 9\n}\nskinparam Class {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam ClassAttribute {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam ClassStereotype {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Footer {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Header {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Hyperlink {\n  Color $FGCOLOR\n}\nskinparam IconPackage {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam IconPrivate {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam IconProtected {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam IconPublic {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam Note {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Object {\n  BorderColor $FGCOLOR\n}\nskinparam Package {\n  BorderColor $FGCOLOR\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam State {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeA {\n  BackgroundColor $FGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeC {\n  BackgroundColor $FGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeE {\n  BackgroundColor $FGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeI {\n  BackgroundColor $FGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeN {\n  BackgroundColor $FGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam UseCaseStereoType {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\n";
g.PLANTUML_THEMES["cyborg"]="---\nname: cyborg\ndisplay_name: Cyborg\ndescription: Theme based off of the bootstrap theme of the same name\nauthor: Brett Schwarz\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/bschwarz/puml-themes\ninspiration: https://bootswatch.com/cyborg/\n---\n\n!$THEME = \"cyborg\"\n\n!if %not(%variable_exists(\"$BGCOLOR\"))\n!$BGCOLOR = \"transparent\"\n!endif\n\nskinparam backgroundColor $BGCOLOR\nskinparam useBetaStyle false\n\n''\n'' Colors taken from the css file of the BS theme\n''\n!$BLUE = \"#2A9FD6\"\n!$INDIGO = \"#6610f2\"\n!$PURPLE = \"#6f42c1\"\n!$PINK = \"#e83e8c\"\n!$RED = \"#CC0000\"\n!$ORANGE = \"#fd7e14\"\n!$YELLOW = \"#FF8800\"\n!$GREEN = \"#77B300\"\n!$TEAL = \"#20c997\"\n!$CYAN = \"#9933CC\"\n!$WHITE = \"#FFF\"\n!$GRAY_LIGHT = \"#222\"\n!$GRAY = \"#555\"\n!$PRIMARY = \"#2A9FD6\"\n!$SECONDARY = \"#555\"\n!$SUCCESS = \"#77B300\"\n!$INFO = \"#9933CC\"\n!$WARNING = \"#FF8800\"\n!$DANGER = \"#CC0000\"\n!$LIGHT = \"#222\"\n!$DARK = \"#ADAFAE\"\n\n'' *_DARK = tint (lighter) of the main color of 80%\n''          where TINT is calculated by clr + (255-clr) * tint_factor\n'' *_LIGHT = shade (darker) of the main color of 80%\n''          and SHADE is calculated by clr * (1 - shade_factor)\n''\n!$FGCOLOR = $WHITE\n!$PRIMARY_DARK = \"#55B2DE\"\n!$PRIMARY_LIGHT = \"#227FAB\"\n!$PRIMARY_TEXT = $WHITE\n!$SECONDARY_DARK = \"#777777\"\n!$SECONDARY_LIGHT = \"#444444\"\n!$SECONDARY_TEXT = $WHITE\n!$INFO_DARK = \"#AD5CD6\"\n!$INFO_LIGHT = \"#9F161B\"\n!$INFO_TEXT = $WHITE\n!$SUCCESS_DARK = \"#92C233\"\n!$SUCCESS_LIGHT = \"#5F8F00\"\n!$SUCCESS_TEXT = $WHITE\n!$WARNING_DARK = \"#FFA033\"\n!$WARNING_LIGHT = \"#CC6D00\"\n!$WARNING_TEXT = $WHITE\n!$DANGER_DARK = \"#D63333\"\n!$DANGER_LIGHT = \"#A30000\"\n!$DANGER_TEXT = $WHITE\n!$DARK_DARK = \"#BDBFBE\"\n!$DARK_LIGHT = \"#8A8C8B\"\n!$LIGHT_DARK = \"#4E4E4E\"\n!$LIGHT_LIGHT = \"#1B1B1B\"\n\n!procedure $success($msg)\n  <font color=$SUCCESS><b>$msg\n!endprocedure\n\n!procedure $failure($msg)\n  <font color=$DANGER><b>$msg\n!endprocedure\n\n!procedure $warning($msg)\n  <font color=$WARNING><b>$msg\n!endprocedure\n\n!procedure $primary_scheme()\n\tFontColor $PRIMARY_TEXT\n\tBorderColor $PRIMARY_DARK\n\tBackgroundColor $PRIMARY\n!endprocedure\n''\n'' Style settings\n''\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $PRIMARY_TEXT\n    HyperLinkColor $ORANGE\n    LineColor $PRIMARY_DARK\n    LineThickness 1\n    Margin 10\n    Padding 6\n    Shadowing 0.0\n  }\n  node {\n   Padding 15\n   roundcorner 20\n   BackgroundColor $PRIMARY-$PRIMARY_DARK\n  }\n  caption {\n    LineThickness 0\n  }\n  footer {\n    LineThickness 0\n  }\n  groupHeader {\n    BackgroundColor $SECONDARY\n    FontColor $INFO\n    FontStyle bold\n  }\n  header {\n    LineThickness 0\n  }\n  referenceHeader {\n    BackgroundColor $BGCOLOR\n    FontColor $DARK\n    FontStyle bold\n  }\n  separator {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  title {\n\tFontSize 20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tFontColor $PRIMARY\n\tBorderColor $SECONDARY\n  }\n  nwdiagDiagram {\n\tnetwork {\n\t\t$primary_scheme()    \n\t\tLineColor $PRIMARY\n\t\tLineThickness 1.0\n\t\tFontColor $PRIMARY_LIGHT\n\t}\n\tserver {\n\t\t$primary_scheme()\n\t}\n\tarrow {\n\t\tFontColor $PRIMARY_LIGHT\n\t\tLineColor $PRIMARY_LIGHT\n\t}\n\tgroup {\n\t\tBackGroundColor $LIGHT\n\t\tLineColor $LIGHT_DARK\n\t\tLineThickness 2.0\n\t\tMargin 5\n\t\tPadding 5\n\t}\n  }\n  participant {\n    Margin 5 40\n    Padding 15 20\n  }\n  ganttDiagram {\n\ttask {\n\t\t$primary_scheme()\n\t\tLineColor $PRIMARY\n\t\tMargin 10 2 2 2\n\t\tPadding 6\n\t}\n\tnote {\n\t\tFontColor $INFO_TEXT\n\t\tLineColor $INFO_DARK\n\t\tBackGroundColor $INFO\n\t}\n\tseparator {\n\t\tLineColor $SECONDARY\n\t\tBackGroundColor $SECONDARY-$SECONDARY_DARK\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tmilestone {\n\t\tFontColor $INFO\n\t\tFontSize 16\n\t\tFontStyle italic\n\t\tBackGroundColor $SECONDARY\n\t\tLineColor $SECONDARY_DARK\n\t}\n\ttimeline {\n\t\tBackgroundColor $SECONDARY\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tclosed {\n\t\tBackgroundColor $WARNING_DARK\n\t\tFontColor $WARNING_TEXT\n\t}\n  }\n</style>\n''\n'' Global Default Values\n''\nskinparam defaultFontName       \"Verdana\"\nskinparam defaultFontSize       12\nskinparam dpi                   100\nskinparam shadowing             false\nskinparam roundcorner           8\nskinparam BoxPadding            40\nskinparam ArrowColor            $DARK\nskinparam stereotype {\n    CBackgroundColor $SECONDARY_DARK\n    CBorderColor $SECONDARY_LIGHT\n    ABackgroundColor $SUCCESS_LIGHT\n    ABorderColor $SUCCESS_DARK\n    IBackgroundColor $DANGER_LIGHT\n    IBorderColor $DANGER_DARK\n    EBackgroundColor $WARNING_LIGHT\n    EBorderColor $WARNING_DARK\n    NBackgroundColor $INFO_LIGHT\n    NBorderColor $INFO_DARK\n}\nskinparam title {\n\tFontColor\t                 $PRIMARY\n\tBorderColor\t                 $SECONDARY_DARK\n\tFontSize\t    \t         20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor              $SECONDARY_LIGHT-$SECONDARY\n}\n\n\nskinparam legend {\n\tBackgroundColor $SECONDARY\n\tBorderColor $SECONDARY_DARK\n\tFontColor $DARK\n}\n\n!startsub swimlane\nskinparam swimlane {\n\tBorderColor $INFO\n\tBorderThickness 2\n\tTitleBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tTitleFontColor $PRIMARY\n}\n!endsub\n\n!startsub activity\n\nskinparam activity {\n\t$primary_scheme()\n\tBarColor $SUCCESS\n\tStartColor $INFO\n\tEndColor $INFO\n\t''\n\tDiamondBackgroundColor $SECONDARY_LIGHT\n  \tDiamondBorderColor $SECONDARY_DARK\n  \tDiamondFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub participant\n\nskinparam participant {\n\t$primary_scheme()\n\tParticipantBorderThickness 2\n}\n!endsub\n\n!startsub actor\n\nskinparam actor {\n\t$primary_scheme()\n\tFontColor $PRIMARY\n}\n!endsub\n\n!startsub arrow\n\nskinparam arrow {\n\tThickness 3\n\tColor $PRIMARY\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub sequence\n\nskinparam sequence {\n\tBorderColor $PRIMARY\n\t' For some reason sequence title font color does not pick up from global\n\tTitleFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n\tStartColor $PRIMARY\n\tEndColor $PRIMARY\n\t''\n\tBoxBackgroundColor $BGCOLOR\n\tBoxBorderColor $DARK\n\tBoxFontColor $DARK\n\t''\n\tDelayFontColor $DARK\n\t''\n\tLifeLineBorderColor $SECONDARY\n\tLifeLineBorderThickness 2\n\tLifeLineBackgroundColor $SECONDARY_DARK\n\t''\n\tGroupBorderColor $SECONDARY\n\tGroupFontColor $DARK\n\tGroupHeaderFontColor $INFO\n\tGroupBackgroundColor $SECONDARY\n\tGroupHeaderBackgroundColor $BGCOLOR\n\t''\n\tDividerBackgroundColor $DARK\n    DividerBorderColor $DARK\n    DividerBorderThickness 2\n    DividerFontColor $LIGHT\n\t''\n\tReferenceBackgroundColor $BGCOLOR\n\tReferenceBorderColor $SECONDARY\n\tReferenceFontColor $SECONDARY_TEXT\n\tReferenceHeaderBackgroundColor $SECONDARY\n\t''\n\tStereotypeFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub partition\n\nskinparam partition {\n\tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n}\n!endsub\n\n!startsub collections\n\nskinparam collections {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub control\n\nskinparam control {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub entity\n\nskinparam entity {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub boundary\n\nskinparam boundary {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub agent\n\nskinparam agent {\n\tBackgroundColor $WARNING\n\tBorderColor $WARNING_LIGHT\n\tFontColor $DARK\n}\n!endsub\n\n!startsub note\n\nskinparam note {\n\tBorderThickness 1\n\tBackgroundColor $INFO\n\tBorderColor $INFO_DARK\n\tFontColor $WHITE\n}\n!endsub\n\n!startsub artifact\n\nskinparam artifact {\n\tBackgroundColor $DARK\n\tBorderColor $DARK_DARK\n\tFontColor $LIGHT\n}\n!endsub\n\n!startsub component\n\nskinparam component {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub interface\n\nskinparam interface {\n\tBackgroundColor  $DANGER_DARK\n\tBorderColor  $DANGER\n\tFontColor $DARK\n}\n!endsub\n\n!startsub storage\n\nskinparam storage {\n\tBackgroundColor $WARNING\n  \tBorderColor $WARNING_DARK\n\tFontColor $WARNING_TEXT\n}\n!endsub\n\n!startsub node\n\nskinparam node {\n\tBackgroundColor  $SECONDARY\n\tBorderColor $DARK\n\tFontColor $DARK\n}\n!endsub\n\n!startsub cloud\n\nskinparam cloud {\n\tBackgroundColor $LIGHT-black\n\tBorderColor $LIGHT\n\tFontColor $DARK\n}\n!endsub\n\n!startsub database\n\nskinparam database {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub actor\n\nskinparam actor {\n\tFontColor $DARK\n}\n!endsub\n\n!startsub class\n\nskinparam class {\n\t$primary_scheme()\n\tHeaderBackgroundColor $PRIMARY_LIGHT\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $LIGHT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub object\n\nskinparam object {\n\t$primary_scheme()\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub usecase\n\nskinparam usecase {\n\t$primary_scheme()\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub rectangle\n\nskinparam rectangle {\n\t$primary_scheme()\n\tBackgroundColor $SECONDARY_LIGHT\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub package\n\nskinparam package {\n\tBackgroundColor $SECONDARY\n  \tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBorderThickness 2\n}\n!endsub\n\n!startsub folder\n\nskinparam folder {\n\tBackgroundColor $SECONDARY_LIGHT\n  \tBorderColor $WARNING\n\tFontColor $WARNING\n\tBorderThickness 2\n}\n!endsub\n\n!startsub frame\n\nskinparam frame {\n\tBackgroundColor $SECONDARY_LIGHT\n  \tBorderColor $INFO\n\tFontColor $INFO\n\tBorderThickness 2\n}\n!endsub\n\n!startsub state\n\nskinparam state {\n\t$primary_scheme()\n\tStartColor $INFO\n\tEndColor $INFO\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub queue\n\nskinparam queue {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub card\n\nskinparam card {\n\tBackgroundColor $INFO\n\tBorderColor $INFO_DARK\n\tFontColor $INFO_TEXT\n}\n!endsub\n\n!startsub file\n\nskinparam file {\n\tBackgroundColor $SECONDARY_DARK\n\tBorderColor $DARK\n\tFontColor $DARK\n}\n!endsub\n\n!startsub stack\n\nskinparam stack {\n\t$primary_scheme()\n}\n!endsub\n";
g.PLANTUML_THEMES["cyborg-outline"]="---\nname: cyborg-outline\ndisplay_name: Cyborg Outline\ndescription: Theme based off of the bootstrap theme of the same name, with outline colors\nauthor: Brett Schwarz\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/bschwarz/puml-themes\ninspiration: https://bootswatch.com/cyborg/\n---\n\n!$THEME = \"cyborg-outline\"\n\n!if %not(%variable_exists(\"$BGCOLOR\"))\n!$BGCOLOR = \"transparent\"\n!endif\n\nskinparam backgroundColor $BGCOLOR\nskinparam useBetaStyle false\n\n''\n'' Colors taken from the css file of the BS theme\n''\n!$BLUE = \"#2A9FD6\"\n!$INDIGO = \"#6610f2\"\n!$PURPLE = \"#6f42c1\"\n!$PINK = \"#e83e8c\"\n!$RED = \"#CC0000\"\n!$ORANGE = \"#fd7e14\"\n!$YELLOW = \"#FF8800\"\n!$GREEN = \"#77B300\"\n!$TEAL = \"#20c997\"\n!$CYAN = \"#9933CC\"\n!$WHITE = \"#FFF\"\n!$GRAY_LIGHT = \"#222\"\n!$GRAY = \"#555\"\n!$PRIMARY = \"#2A9FD6\"\n!$SECONDARY = \"#555\"\n!$SUCCESS = \"#77B300\"\n!$INFO = \"#9933CC\"\n!$WARNING = \"#FF8800\"\n!$DANGER = \"#CC0000\"\n!$LIGHT = \"#222\"\n!$DARK = \"#ADAFAE\"\n\n'' *_DARK = tint (lighter) of the main color of 80%\n''          where TINT is calculated by clr + (255-clr) * tint_factor\n'' *_LIGHT = shade (darker) of the main color of 80%\n''          and SHADE is calculated by clr * (1 - shade_factor)\n''\n!$FGCOLOR = $WHITE\n!$PRIMARY_DARK = \"#55B2DE\"\n!$PRIMARY_LIGHT = \"#227FAB\"\n!$PRIMARY_TEXT = $PRIMARY\n!$SECONDARY_DARK = \"#777777\"\n!$SECONDARY_LIGHT = \"#444444\"\n!$SECONDARY_TEXT = $SECONDARY_DARK\n!$INFO_DARK = \"#AD5CD6\"\n!$INFO_LIGHT = \"#7a29a3\"\n!$INFO_TEXT = $INFO\n!$SUCCESS_DARK = \"#92C233\"\n!$SUCCESS_LIGHT = \"#5F8F00\"\n!$SUCCESS_TEXT = $SUCCESS\n!$WARNING_DARK = \"#FFA033\"\n!$WARNING_LIGHT = \"#cc6d00\"\n!$WARNING_TEXT = $WARNING\n!$DANGER_DARK = \"#D63333\"\n!$DANGER_LIGHT = \"#a30000\"\n!$DANGER_TEXT = $WHITE\n!$DARK_DARK = \"#BDBFBE\"\n!$DARK_LIGHT = \"#8A8C8B\"\n!$LIGHT_DARK = \"#4E4E4E\"\n!$LIGHT_LIGHT = \"#1B1B1B\"\n\n!procedure $success($msg)\n  <font color=$SUCCESS><b>$msg\n!endprocedure\n\n!procedure $failure($msg)\n  <font color=$DANGER><b>$msg\n!endprocedure\n\n!procedure $warning($msg)\n  <font color=$WARNING><b>$msg\n!endprocedure\n\n!procedure $primary_scheme()\n\tFontColor $PRIMARY_TEXT\n\tBorderColor $PRIMARY_DARK\n\tBackgroundColor $BGCOLOR\n!endprocedure\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $PRIMARY_TEXT\n    HyperLinkColor $ORANGE\n    LineColor $PRIMARY_DARK\n    LineThickness 1\n    Margin 10\n    Padding 6\n    Shadowing 0.0\n  }\n  node {\n   Padding 15\n   roundcorner 20\n   BackgroundColor $BGCOLOR\n  }\n  caption {\n    LineThickness 0\n  }\n  footer {\n    LineThickness 0\n  }\n  groupHeader {\n    BackgroundColor $SECONDARY\n    FontColor $INFO\n    FontStyle bold\n  }\n  header {\n    LineThickness 0\n  }\n  referenceHeader {\n    BackgroundColor $BGCOLOR\n    FontColor $DARK\n    FontStyle bold\n  }\n  separator {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  title {\n\tFontSize 20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor  $BGCOLOR\n\tFontColor $PRIMARY\n\tBorderColor $SECONDARY\n  }\n  nwdiagDiagram {\n\tnetwork {\n\t\t$primary_scheme()    \n\t\tLineColor $PRIMARY\n\t\tLineThickness 1.0\n\t\tFontColor $PRIMARY_LIGHT\n\t}\n\tserver {\n\t\t$primary_scheme()\n\t}\n\tarrow {\n\t\tFontColor $PRIMARY_LIGHT\n\t\tLineColor $PRIMARY_LIGHT\n\t}\n\tgroup {\n\t\tBackGroundColor $LIGHT\n\t\tLineColor $LIGHT_DARK\n\t\tLineThickness 2.0\n\t\tMargin 5\n\t\tPadding 5\n\t}\n  }\n  participant {\n    Margin 5 40\n    Padding 15 20\n  }\n  ganttDiagram {\n\ttask {\n\t\t$primary_scheme()\n\t\tLineColor $PRIMARY\n\t\tMargin 10 2 2 2\n\t\tPadding 6\n\t}\n\tnote {\n\t\tFontColor $INFO_TEXT\n\t\tLineColor $INFO_DARK\n\t\tBackGroundColor $BGCOLOR\n\t}\n\tseparator {\n\t\tLineColor $SECONDARY_DARK\n\t\tBackGroundColor $BGCOLOR\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tmilestone {\n\t\tFontColor $INFO\n\t\tFontSize 16\n\t\tFontStyle italic\n\t\tBackGroundColor $SECONDARY\n\t\tLineColor $SECONDARY_DARK\n\t}\n\ttimeline {\n\t\tBackgroundColor $SECONDARY\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tclosed {\n\t\tBackgroundColor $WARNING_DARK\n\t\tFontColor $WARNING_TEXT\n\t}\n  }\n</style>\n''\n'' Global Default Values\n''\nskinparam defaultFontName       \"Verdana\"\nskinparam defaultFontSize       12\nskinparam dpi                   100\nskinparam shadowing             false\nskinparam roundcorner           8\nskinparam BoxPadding            40\nskinparam ArrowColor            $DARK\nskinparam stereotype {\n    CBackgroundColor $SECONDARY_DARK\n    CBorderColor $SECONDARY_LIGHT\n    ABackgroundColor $SUCCESS_LIGHT\n    ABorderColor $SUCCESS_DARK\n    IBackgroundColor $DANGER_LIGHT\n    IBorderColor $DANGER_DARK\n    EBackgroundColor $WARNING_LIGHT\n    EBorderColor $WARNING_DARK\n    NBackgroundColor $INFO_LIGHT\n    NBorderColor $INFO_DARK\n}\nskinparam title {\n\tFontColor\t                 $PRIMARY\n\tBorderColor\t                 $SECONDARY_DARK\n\tFontSize\t    \t         20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor              $BGCOLOR\n}\n\nskinparam legend {\n\tBackgroundColor $BGCOLOR\n\tBorderColor $SECONDARY_DARK\n\tFontColor $DARK\n}\n\n!startsub swimlane\nskinparam swimlane {\n\tBorderColor $INFO\n\tBorderThickness 2\n\tTitleBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tTitleFontColor $PRIMARY\n}\n!endsub\n\n!startsub activity\n\nskinparam activity {\n\t$primary_scheme()\n\tBarColor $SUCCESS\n\tStartColor $INFO\n\tEndColor $INFO\n\t''\n\tDiamondBackgroundColor $BGCOLOR\n  \tDiamondBorderColor $SECONDARY_DARK\n  \tDiamondFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub participant\n\nskinparam participant {\n\t$primary_scheme()\n\tParticipantBorderThickness 2\n}\n!endsub\n\n!startsub actor\n\nskinparam actor {\n\t$primary_scheme()\n\tFontColor $PRIMARY\n}\n!endsub\n\n!startsub arrow\n\nskinparam arrow {\n\tThickness 3\n\tColor $PRIMARY\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub sequence\n\nskinparam sequence {\n\tBorderColor $PRIMARY\n\t' For some reason sequence title font color does not pick up from global\n\tTitleFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n\tStartColor $PRIMARY\n\tEndColor $PRIMARY\n\t''\n\tBoxBackgroundColor $BGCOLOR\n\tBoxBorderColor $DARK\n\tBoxFontColor $DARK\n\t''\n\tDelayFontColor $DARK\n\t''\n\tLifeLineBorderColor $SECONDARY\n\tLifeLineBorderThickness 2\n\tLifeLineBackgroundColor $BGCOLOR\n\t''\n\tGroupBorderColor $DARK\n\tGroupFontColor $DARK\n\tGroupHeaderFontColor $INFO_TEXT\n\tGroupBackgroundColor $BGCOLOR\n\tGroupHeaderBackgroundColor $BGCOLOR\n\t''\n\tDividerBackgroundColor $BGCOLOR\n    DividerBorderColor $DARK\n    DividerBorderThickness 2\n    DividerFontColor $DARK\n\t''\n\tReferenceBackgroundColor $BGCOLOR\n\tReferenceBorderColor $DARK\n\tReferenceFontColor $DARK\n\tReferenceHeaderFontColor $INFO_TEXT\n\tReferenceHeaderBackgroundColor $BGCOLOR\n\t''\n\tStereotypeFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub partition\n\nskinparam partition {\n\tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n}\n!endsub\n\n!startsub collections\n\nskinparam collections {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub control\n\nskinparam control {\n\t$primary_scheme()\n\tFontColor $PRIMARY\n}\n!endsub\n\n!startsub entity\n\nskinparam entity {\n\t$primary_scheme()\n\tFontColor $PRIMARY\n}\n!endsub\n\n!startsub boundary\n\nskinparam boundary {\n\t$primary_scheme()\n\tFontColor $PRIMARY\n}\n!endsub\n\n!startsub agent\n\nskinparam agent {\n\tBackgroundColor $BGCOLOR\n\tBorderColor $WARNING_LIGHT\n\tFontColor $DARK\n}\n!endsub\n\n!startsub note\n\nskinparam note {\n\tBorderThickness 1\n\tBackgroundColor $BGCOLOR\n\tBorderColor $INFO_DARK\n\tFontColor $INFO_DARK\n}\n!endsub\n\n!startsub artifact\n\nskinparam artifact {\n\tBackgroundColor $BGCOLOR\n\tBorderColor $DARK_DARK\n\tFontColor $DARK_DARK\n}\n!endsub\n\n!startsub component\n\nskinparam component {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub interface\n\nskinparam interface {\n\tBackgroundColor  $BGCOLOR\n\tBorderColor  $DANGER\n\tFontColor $DARK\n}\n!endsub\n\n!startsub storage\n\nskinparam storage {\n\tBackgroundColor $BGCOLOR\n  \tBorderColor $WARNING_DARK\n\tFontColor $WARNING_TEXT\n}\n!endsub\n\n!startsub node\n\nskinparam node {\n\tBackgroundColor  $BGCOLOR\n\tBorderColor $DARK\n\tFontColor $DARK\n}\n!endsub\n\n!startsub cloud\n\nskinparam cloud {\n\tBackgroundColor $BGCOLOR\n\tBorderColor #F2FCFE\n\tFontColor $DARK\n}\n!endsub\n\n!startsub database\n\nskinparam database {\n\t$primary_scheme()\n\tFontColor $PRIMARY\n}\n!endsub\n\n\n!startsub class\n\nskinparam class {\n\t$primary_scheme()\n        FontColor $LIGHT\n\tHeaderBackgroundColor $PRIMARY_LIGHT\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $DARK\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub object\n\nskinparam object {\n\t$primary_scheme()\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $SECONDARY_DARK\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub usecase\n\nskinparam usecase {\n\t$primary_scheme()\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub rectangle\n\nskinparam rectangle {\n\t$primary_scheme()\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub package\n\nskinparam package {\n\tBackgroundColor $BGCOLOR\n  \tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBorderThickness 2\n}\n!endsub\n\n!startsub folder\n\nskinparam folder {\n\tBackgroundColor $BGCOLOR\n  \tBorderColor $WARNING\n\tFontColor $WARNING\n\tBorderThickness 2\n}\n!endsub\n\n!startsub frame\n\nskinparam frame {\n\tBackgroundColor $BGCOLOR\n  \tBorderColor $INFO\n\tFontColor $INFO_TEXT\n\tBorderThickness 2\n}\n!endsub\n\n!startsub state\n\nskinparam state {\n\t$primary_scheme()\n\tStartColor $INFO\n\tEndColor $INFO\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub queue\n\nskinparam queue {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub card\n\nskinparam card {\n\tBackgroundColor $BGCOLOR\n\tBorderColor $INFO\n\tFontColor $INFO_TEXT\n}\n!endsub\n\n!startsub file\n\nskinparam file {\n\tBackgroundColor $BGCOLOR\n\tBorderColor $GRAY\n\tFontColor $GRAY\n}\n!endsub\n\n!startsub stack\n\nskinparam stack {\n\t$primary_scheme()\n}\n!endsub\n";
g.PLANTUML_THEMES["hacker"]="---\nname: hacker\ndisplay_name: Hacker\ndescription: Theme based off of the Jekyll theme of the same name\nauthor: Brett Schwarz\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/bschwarz/puml-themes\ninspiration: https://github.com/pages-themes/hacker\n---\n\n!$THEME = \"hacker\"\n\n!if %not(%variable_exists(\"$BGCOLOR\"))\n!$BGCOLOR = \"transparent\"\n!endif\n\nskinparam BackgroundColor $BGCOLOR\nskinparam useBetaStyle false\n\n''\n'' Colors taken from the _default_colors.scss file for jekyll hacker theme\n''\n!$PRIMARY = \"#b5e853\"\n!$PRIMARY_LIGHT = \"#d3f198\"\n!$PRIMARY_DARK = \"#6d8b32\"\n!$PRIMARY_TEXT = \"#151515\"\n!$SECONDARY = \"#6a9fb5\"\n!$SECONDARY_LIGHT = \"#88b2c4\"\n!$SECONDARY_DARK = \"#557f91\"\n!$SECONDARY_TEXT = \"#fefefe\"\n!$SUCCESS = \"#90a959\"\n!$SUCCESS_LIGHT = \"#a6ba7a\"\n!$INFO = \"#aa759f\"\n!$INFO_LIGHT = \"#bb91b2\"\n!$INFO_DARK = \"#885E7F\"\n!$WARNING = \"#f4bf75\"\n!$WARNING_LIGHT = \"#f6cc91\"\n!$WARNING_TEXT = \"#151515\"\n!$DANGER = \"#ac4142\"\n!$DANGER_LIGHT = \"#bd6768\"\n!$LIGHT = \"#151515\"\n!$DARK = \"#eaeaea\"\n\n!procedure $success($msg)\n  <font color=$SUCCESS><b>$msg\n!endprocedure\n\n!procedure $failure($msg)\n  <font color=$DANGER><b>$msg\n!endprocedure\n\n!procedure $warning($msg)\n  <font color=$WARNING><b>$msg\n!endprocedure\n\n!procedure $primary_scheme()\n\tFontColor $PRIMARY_TEXT\n\tBorderColor $PRIMARY_LIGHT\n\tBackgroundColor $PRIMARY_LIGHT-$PRIMARY\n!endprocedure\n\n''\n'' Style settings\n''\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $PRIMARY_TEXT\n    HyperLinkColor $ORANGE\n    LineColor $PRIMARY_DARK\n    LineThickness 1\n    Margin 10\n    Padding 6\n    Shadowing 0.0\n  }\n  node {\n   Padding 15\n   roundcorner 20\n   BackgroundColor $PRIMARY-$PRIMARY_DARK\n  }\n  caption {\n    LineThickness 0\n  }\n  footer {\n    LineThickness 0\n  }\n  groupHeader {\n    BackgroundColor $SECONDARY\n    FontColor $INFO\n    FontStyle bold\n  }\n  header {\n    LineThickness 0\n  }\n  referenceHeader {\n    BackgroundColor $BGCOLOR\n    FontColor $DARK\n    FontStyle bold\n  }\n  separator {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  title {\n\tFontSize 20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tFontColor $PRIMARY\n\tBorderColor $SECONDARY\n  }\n  nwdiagDiagram {\n\tnetwork {\n\t\t$primary_scheme()    \n\t\tLineColor $PRIMARY\n\t\tLineThickness 1.0\n\t\tFontColor $PRIMARY_LIGHT\n\t}\n\tserver {\n\t\t$primary_scheme()\n\t}\n\tarrow {\n\t\tFontColor $PRIMARY_LIGHT\n\t\tLineColor $PRIMARY_LIGHT\n\t}\n\tgroup {\n\t\tBackGroundColor $LIGHT\n\t\tLineColor $LIGHT_DARK\n\t\tLineThickness 2.0\n\t\tMargin 5\n\t\tPadding 5\n\t}\n  }\n  participant {\n    Margin 5 40\n    Padding 15 20\n  }\n  ganttDiagram {\n\ttask {\n\t\t$primary_scheme()\n\t\tLineColor $PRIMARY\n\t\tMargin 10 2 2 2\n\t\tPadding 6\n\t}\n\tnote {\n\t\tFontColor $INFO_TEXT\n\t\tLineColor $INFO_DARK\n\t\tBackGroundColor $INFO\n\t}\n\tseparator {\n\t\tLineColor $SECONDARY\n\t\tBackGroundColor $SECONDARY-$SECONDARY_DARK\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tmilestone {\n\t\tFontColor $INFO\n\t\tFontSize 16\n\t\tFontStyle italic\n\t\tBackGroundColor $SECONDARY\n\t\tLineColor $SECONDARY_DARK\n\t}\n\ttimeline {\n\t\tBackgroundColor $SECONDARY\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tclosed {\n\t\tBackgroundColor $WARNING_DARK\n\t\tFontColor $WARNING_TEXT\n\t}\n  }\n</style>\n''\n'' Global Default Values\n''\nskinparam defaultFontName       \"Verdana\"\nskinparam defaultFontSize       12\nskinparam dpi                   100\nskinparam shadowing             false\nskinparam roundcorner           40\nskinparam BoxPadding            40\nskinparam ArrowColor            $DARK\nskinparam stereotype {\n    CBackgroundColor $SECONDARY_DARK\n    CBorderColor $SECONDARY_LIGHT\n    ABackgroundColor $SUCCESS_LIGHT\n    ABorderColor $SUCCESS_DARK\n    IBackgroundColor $DANGER_LIGHT\n    IBorderColor $DANGER_DARK\n    EBackgroundColor $WARNING_LIGHT\n    EBorderColor $WARNING_DARK\n    NBackgroundColor $INFO_LIGHT\n    NBorderColor $INFO_DARK\n}\nskinparam title {\n\tFontColor\t                 $PRIMARY\n\tBorderColor\t                 $PRIMARY\n\tFontSize\t    \t         20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor              $LIGHT-black\n}\n\n\nskinparam legend {\n\tBackgroundColor $SECONDARY\n\tBorderColor $SECONDARY_DARK\n\tFontColor $DARK\n}\n\n!startsub swimlane\nskinparam swimlane {\n\tBorderColor $INFO\n\tBorderThickness 2\n\tTitleBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tTitleFontColor $PRIMARY\n}\n!endsub\n\n!startsub activity\n\nskinparam activity {\n\t$primary_scheme()\n\tBarColor $SUCCESS\n\tStartColor $INFO\n\tEndColor $INFO\n\t''\n\tDiamondBackgroundColor $SECONDARY_LIGHT-$SECONDARY\n  \tDiamondBorderColor $SECONDARY_LIGHT\n  \tDiamondFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub participant\n\nskinparam participant {\n\t$primary_scheme()\n\tBorderThickness 2\n}\n!endsub\n\n!startsub actor\n\nskinparam actor {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub arrow\n\nskinparam arrow {\n\tThickness 3\n\tColor $PRIMARY\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub sequence\n\nskinparam sequence {\n\tBorderColor $PRIMARY\n\t' For some reason sequence title font color does not pick up from global\n\tTitleFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n\tStartColor $PRIMARY\n\tEndColor $PRIMARY\n\t''\n\tBoxBackgroundColor $BGCOLOR\n\tBoxBorderColor $DARK\n\tBoxFontColor $DARK\n\t''\n\tDelayFontColor $DARK\n\t''\n\tLifeLineBorderColor $SECONDARY\n\tLifeLineBorderThickness 2\n\tLifeLineBackgroundColor $SECONDARY_DARK\n\t''\n\tGroupBackgroundColor $LIGHT\n\tGroupBorderColor $DARK\n\tGroupFontColor $DARK\n\tGroupHeaderFontColor $INFO\n\tGroupHeaderBackgroundColor $BGCOLOR\n\t''\n\tDividerBackgroundColor $DARK\n    DividerBorderColor $DARK\n    DividerBorderThickness 2\n    DividerFontColor $LIGHT\n\t''\n\tReferenceBackgroundColor $BGCOLOR\n\tReferenceBorderColor $DARK\n\tReferenceFontColor $DARK\n\tReferenceHeaderBackgroundColor $LIGHT\n\t''\n\tStereotypeFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub partition\n\nskinparam partition {\n\tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBackgroundColor $LIGHT-black\n}\n!endsub\n\n!startsub collections\n\nskinparam collections {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub control\n\nskinparam control {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub entity\n\nskinparam entity {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub boundary\n\nskinparam boundary {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub agent\n\nskinparam agent {\n\tBackgroundColor $WARNING_LIGHT-$WARNING\n\tBorderColor $WARNING_LIGHT\n\tFontColor $DARK\n}\n!endsub\n\n!startsub note\n\nskinparam note {\n\tBorderThickness 1\n\tBackgroundColor $INFO_LIGHT-$INFO_DARK\n\tBorderColor $INFO_DARK\n\tFontColor $WHITE\n}\n!endsub\n\n!startsub artifact\n\nskinparam artifact {\n\tBackgroundColor $DARK\n\tBorderColor white\n\tFontColor $LIGHT\n}\n!endsub\n\n!startsub component\n\nskinparam component {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub interface\n\nskinparam interface {\n\tBackgroundColor  $DANGER_LIGHT-$DANGER\n\tBorderColor  $DANGER_LIGHT\n\tFontColor $DARK\n}\n!endsub\n\n!startsub storage\n\nskinparam storage {\n\tBackgroundColor $WARNING_LIGHT-$WARNING\n  \tBorderColor $WARNING_LIGHT\n\tFontColor $WARNING_TEXT\n}\n!endsub\n\n!startsub node\n\nskinparam node {\n\tBackgroundColor  $LIGHT-black\n\tBorderColor $PRIMARY_LIGHT\n\tFontColor $DARK\n}\n!endsub\n\n!startsub cloud\n\nskinparam cloud {\n\tBackgroundColor $BGCOLOR\n\tBorderColor $DARK\n\tFontColor $DARK\n}\n!endsub\n\n!startsub database\n\nskinparam database {\n\tBackgroundColor  $LIGHT-black\n\tBorderColor $PRIMARY_LIGHT\n\tFontColor $DARK\n}\n!endsub\n\n!startsub class\n\nskinparam class {\n\t$primary_scheme()\n\tHeaderBackgroundColor $PRIMARY_LIGHT-$PRIMARY\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $LIGHT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub object\n\nskinparam object {\n\t$primary_scheme()\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $LIGHT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub usecase\n\nskinparam usecase {\n\t$primary_scheme()\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub rectangle\n\nskinparam rectangle {\n\tBackgroundColor $BGCOLOR\n\tBorderColor $PRIMARY\n\tBorderThickness 2\n\tFontColor $PRIMARY_DARK\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub package\n\nskinparam package {\n\tBackgroundColor $LIGHT\n  \tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBorderThickness 2\n}\n!endsub\n\n!startsub folder\n\nskinparam folder {\n\tBackgroundColor $LIGHT-black\n  \tBorderColor $WARNING\n\tFontColor $WARNING\n\tBorderThickness 2\n}\n!endsub\n\n!startsub frame\n\nskinparam frame {\n\tBackgroundColor $LIGHT-black\n  \tBorderColor $INFO\n\tFontColor $INFO\n\tBorderThickness 2\n}\n!endsub\n\n!startsub state\n\nskinparam state {\n\t$primary_scheme()\n\tStartColor $INFO\n\tEndColor $INFO\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub queue\n\nskinparam queue {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub card\n\nskinparam card {\n\tBackgroundColor $INFO_LIGHT-$INFO\n\tBorderColor $INFO_LIGHT\n\tFontColor $INFO_TEXT\n}\n!endsub\n\n!startsub file\n\nskinparam file {\n\tBackgroundColor $SECONDARY_LIGHT-$SECONDARY\n\tBorderColor $SECONDARY_LIGHT\n\tFontColor $DARK\n}\n!endsub\n\n!startsub stack\n\nskinparam stack {\n\t$primary_scheme()\n}\n!endsub\n\n<style>\nmindmapDiagram, wbsDiagram {\n    element {\n\t    $primary_scheme()\n\t}\n\t:depth(0) {\n        fontSize 16\n        fontStyle bold\n        fontColor $SECONDARY\n    }\n    :depth(1) {\n        fontSize 14\n        padding 5\n        fontStyle bold\n    }\n    :depth(2) {\n        fontSize 12\n        padding 4\n    }\n    :depth(3) {\n        fontSize 11\n        padding 3\n        fontColor $INFO\n    }\n\n}\n</style>\n\n\n";
g.PLANTUML_THEMES["lightgray"]="---\nname: lightgray\ndisplay_name: Lightgray\ndescription: Lightgray theme - mostly grays\nauthor: Brett Schwarz\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/bschwarz/puml-themes\ninspiration: \n---\n\n!$THEME = \"lightgray\"\n\n!if %not(%variable_exists(\"$BGCOLOR\"))\n!$BGCOLOR = \"transparent\"\n!endif\n\nskinparam backgroundColor $BGCOLOR\nskinparam useBetaStyle false\n\n!$WHITE = \"#FFF\"\n!$GRAY_DARK = \"#4d4d4d\"\n!$GRAY = \"#737373\"\n!$LIGHT = \"#fcfcfc\"\n!$DARK = \"#303030\"\n\n'' *_LIGHT = tint (lighter) of the main color of 80%\n''          where TINT is calculated by clr + (255-clr) * tint_factor\n'' *_DARK = shade (darker) of the main color of 80%\n''          and SHADE is calculated by clr * (1 - shade_factor)\n''\n!$FGCOLOR = $DARK\n!$PRIMARY = \"#e2e2e2\"\n!$PRIMARY_LIGHT = \"#f3f3f3\"\n!$PRIMARY_DARK = \"#888888\"\n!$PRIMARY_TEXT = \"#336699\"\n!$SECONDARY = \"#d2d2d2\"\n!$SECONDARY_LIGHT = \"#dbdbdb\"\n!$SECONDARY_DARK = \"#a8a8a8\"\n!$SECONDARY_TEXT = \"white\"\n!$INFO = \"#336699\"\n!$INFO_LIGHT = \"#5c85ad\"\n!$INFO_DARK = \"#29527a\"\n!$INFO_TEXT = $WHITE\n!$SUCCESS = \"#339933\"\n!$SUCCESS_LIGHT = \"#5cad5c\"\n!$SUCCESS_DARK = \"#297a29\"\n!$SUCCESS_TEXT = $WHITE\n!$WARNING = \"#ffae42\"\n!$WARNING_LIGHT = \"#ffbe68\"\n!$WARNING_DARK = \"#cc8b35\"\n!$WARNING_TEXT = $WHITE\n!$DANGER = \"#ff3333\"\n!$DANGER_LIGHT = \"#ff5c5c\"\n!$DANGER_DARK = \"#cc2929\"\n!$DANGER_TEXT = $WHITE\n\n!procedure $success($msg)\n  <font color=$SUCCESS><b>$msg\n!endprocedure\n\n!procedure $failure($msg)\n  <font color=$DANGER><b>$msg\n!endprocedure\n\n!procedure $warning($msg)\n  <font color=$WARNING><b>$msg\n!endprocedure\n\n!procedure $primary_scheme()\n\tFontColor $PRIMARY_TEXT\n\tBorderColor $PRIMARY_LIGHT\n\tBackgroundColor $PRIMARY_LIGHT-$PRIMARY\n!endprocedure\n''\n'' Style settings\n''\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $PRIMARY_TEXT\n    HyperLinkColor $ORANGE\n    LineColor $PRIMARY_DARK\n    LineThickness 1\n    Margin 10\n    Padding 6\n    Shadowing 0.0\n  }\n  node {\n   Padding 15\n   roundcorner 20\n   BackgroundColor $PRIMARY-$PRIMARY_DARK\n  }\n  caption {\n    LineThickness 0\n  }\n  footer {\n    LineThickness 0\n  }\n  groupHeader {\n    BackgroundColor $SECONDARY\n    FontColor $INFO\n    FontStyle bold\n  }\n  header {\n    LineThickness 0\n  }\n  referenceHeader {\n    BackgroundColor $BGCOLOR\n    FontColor $DARK\n    FontStyle bold\n  }\n  separator {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  title {\n\tFontSize 20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tFontColor $PRIMARY\n\tBorderColor $SECONDARY\n  }\n  nwdiagDiagram {\n\tnetwork {\n\t\t$primary_scheme()    \n\t\tLineColor $PRIMARY\n\t\tLineThickness 1.0\n\t\tFontColor $PRIMARY_DARK\n\t}\n\tserver {\n\t\t$primary_scheme()\n\t}\n\tarrow {\n\t\tFontColor $PRIMARY_DARK\n\t\tLineColor $PRIMARY_DARK\n\t}\n\tgroup {\n\t\tBackGroundColor $LIGHT\n\t\tLineColor $LIGHT_DARK\n\t\tLineThickness 2.0\n\t\tMargin 5\n\t\tPadding 5\n\t}\n  }\n  participant {\n    Margin 5 30\n    Padding 15 20\n  }\n  ganttDiagram {\n\ttask {\n\t\t$primary_scheme()\n\t\tLineColor $PRIMARY\n\t\tMargin 10 2 2 2\n\t\tPadding 6\n\t}\n\tnote {\n\t\tFontColor $INFO_TEXT\n\t\tLineColor $INFO_DARK\n\t\tBackGroundColor $INFO\n\t}\n\tseparator {\n\t\tLineColor $SECONDARY\n\t\tBackGroundColor $SECONDARY-$SECONDARY_DARK\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tmilestone {\n\t\tFontColor $INFO\n\t\tFontSize 16\n\t\tFontStyle italic\n\t\tBackGroundColor $SECONDARY\n\t\tLineColor $SECONDARY_DARK\n\t}\n\ttimeline {\n\t\tBackgroundColor $SECONDARY\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tclosed {\n\t\tBackgroundColor $WARNING_DARK\n\t\tFontColor $WARNING_TEXT\n\t}\n  }\n</style>\n''\n'' Global Default Values\n''\nskinparam defaultFontName        \"Verdana\"\nskinparam defaultFontSize        12\nskinparam dpi                    100\nskinparam shadowing              false\nskinparam roundcorner            15\nskinparam BoxPadding             30\nskinparam ArrowColor             $GRAY\nskinparam stereotype {\n    CBackgroundColor $SECONDARY_LIGHT\n    CBorderColor $SECONDARY_DARK\n    ABackgroundColor $SUCCESS_LIGHT\n    ABorderColor $SUCCESS_DARK\n    IBackgroundColor $DANGER_LIGHT\n    IBorderColor $DANGER_DARK\n    EBackgroundColor $WARNING_LIGHT\n    EBorderColor $WARNING_DARK\n    NBackgroundColor $INFO_LIGHT\n    NBorderColor $INFO_DARK\n}\nskinparam title {\n\tFontColor\t                 $SECONDARY_TEXT\n\tBorderColor\t                 $SECONDARY\n\tFontSize\t    \t         20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor              $SECONDARY_LIGHT-$SECONDARY\n}\n\n\nskinparam legend {\n\tBackgroundColor $PRIMARY\n\tBorderColor $PRIMARY_DARK\n\tFontColor $PRIMARY_TEXT\n}\n\n!startsub swimlane\nskinparam swimlane {\n\tBorderColor $INFO\n\tBorderThickness 2\n\tTitleBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tTitleFontColor $PRIMARY\n}\n!endsub\n\n!startsub activity\n\nskinparam activity {\n\t$primary_scheme()\n\tBarColor $SUCCESS\n\tStartColor $INFO\n\tEndColor $INFO\n\t''\n\tDiamondBackgroundColor $SECONDARY-$SECONDARY_DARK\n  \tDiamondBorderColor $SECONDARY_DARK\n\tDiamondFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub participant\n\nskinparam participant {\n\t$primary_scheme()\n\tParticipantBorderThickness 2\n}\n!endsub\n\n!startsub actor\n\nskinparam actor {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub arrow\n\nskinparam arrow {\n\tThickness 3\n\tColor $PRIMARY\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub sequence\n\nskinparam sequence {\n\tBorderColor $PRIMARY\n\t' For some reason sequence title font color does not pick up from global\n\tTitleFontColor $SECONDARY_TEXT\n\tBackgroundColor $BGCOLOR\n\tStartColor $PRIMARY\n\tEndColor $PRIMARY\n\t''\n\tBoxBackgroundColor $LIGHT\n\tBoxBorderColor $GRAY\n\tBoxFontColor $DARK\n\t''\n\tDelayFontColor $DARK\n\t''\n\tLifeLineBorderColor $SECONDARY_DARK\n\tLifeLineBorderThickness 2\n\tLifeLineBackgroundColor $SECONDARY_LIGHT\n\t''\n\tGroupBorderColor $GRAY\n\tGroupFontColor $DARK\n\tGroupHeaderFontColor $INFO\n\t''\n\tDividerBackgroundColor $WHITE-$LIGHT\n    DividerBorderColor $GRAY\n    DividerBorderThickness 2\n    DividerFontColor $DARK\n\t''\n\tReferenceBackgroundColor $BGCOLOR\n\tReferenceBorderColor $GRAY\n\tReferenceFontColor $DARK\n\tReferenceHeaderFontColor $INFO\n\t''\n\tStereotypeFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub partition\n\nskinparam partition {\n\tBorderColor $PRIMARY\n\tFontColor $PRIMARY_DARK\n\tBackgroundColor $BGCOLOR\n}\n!endsub\n\n!startsub collections\n\nskinparam collections {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub control\n\nskinparam control {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub entity\n\nskinparam entity {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub boundary\n\nskinparam boundary {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub agent\n\nskinparam agent {\n\tBackgroundColor #orange\n\tBorderColor #999999\n\tFontColor #333333\n}\n!endsub\n\n!startsub note\n\nskinparam note {\n\tBorderThickness 1\n\tBackgroundColor $INFO_LIGHT-$INFO\n\tBorderColor $INFO\n\tFontColor $WHITE\n}\n!endsub\n\n!startsub artifact\n\nskinparam artifact {\n\tBackgroundColor white-$LIGHT\n\tBorderColor $SECONDARY_DARK\n\tFontColor $SECONDARY_DARK\n}\n!endsub\n\n!startsub component\n\nskinparam component {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub interface\n\nskinparam interface {\n\tBackgroundColor  $DANGER_LIGHT\n\tBorderColor  $DANGER\n\tFontColor $DARK\n}\n!endsub\n\n!startsub storage\n\nskinparam storage {\n\tBackgroundColor $WARNING_LIGHT-$WARNING\n  \tBorderColor $WARNING\n\tFontColor $WARNING_TEXT\n}\n!endsub\n\n!startsub node\n\nskinparam node {\n\tBackgroundColor $BGCOLOR\n\tBorderColor $PRIMARY_LIGHT\n\tFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub cloud\n\nskinparam cloud {\n\tBackgroundColor #F2FCFE-#eeeeee\n\tBorderColor $F2FCFE\n\tFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub database\n\nskinparam database {\n\t$primary_scheme()\n\tBackgroundColor  $BGCOLOR\n}\n!endsub\n\n!startsub class\n\nskinparam class {\n\t$primary_scheme()\n\tHeaderBackgroundColor $PRIMARY_LIGHT-$PRIMARY_DARK\n\tStereotypeFontColor $DARK\n\tStereotypeFontSize 9\n\tBorderThickness 1\n\tAttributeFontColor $DARK\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub object\n\nskinparam object {\n\t$primary_scheme()\n\tStereotypeFontColor $LIGHT\n\tBorderThickness 1\n\tAttributeFontColor $DARK\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub usecase\n\nskinparam usecase {\n\t$primary_scheme()\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub rectangle\n\nskinparam rectangle {\n\t$primary_scheme()\n\tBackgroundColor $BGCOLOR\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub package\n\nskinparam package {\n\t$primary_scheme()\n\tBackgroundColor $BGCOLOR\n\tBorderThickness 2\n}\n!endsub\n\n!startsub folder\n\nskinparam folder {\n\tBackgroundColor $PRIMARY_LIGHT\n  \tBorderColor $WARNING\n\tFontColor $WARNING\n\tBorderThickness 2\n}\n!endsub\n\n!startsub frame\n\nskinparam frame {\n\tBackgroundColor $PRIMARY_LIGHT\n  \tBorderColor $INFO\n\tFontColor $INFO\n\tBorderThickness 2\n}\n!endsub\n\n!startsub state\n\nskinparam state {\n\t$primary_scheme()\n\tBorderColor $PRIMARY_DARK\n\tStartColor $INFO\n\tEndColor $INFO\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub queue\n\nskinparam queue {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub card\n\nskinparam card {\n\tBackgroundColor $INFO_LIGHT-$INFO\n\tBorderColor $INFO\n\tFontColor $INFO_TEXT\n}\n!endsub\n\n!startsub file\n\nskinparam file {\n\tBackgroundColor $SECONDARY_LIGHT-$SECONDARY\n\tBorderColor $SECONDARY_DARK\n\tFontColor $SECONDARY_TEXT\n\n}\n!endsub\n\n!startsub stack\n\nskinparam stack {\n\t$primary_scheme()\n}\n!endsub\n";
g.PLANTUML_THEMES["mars"]="---\nname: mars\ndisplay_name: Mars\ndescription: The mars theme from future-architect/puml-themes\nauthor: [future-architect](https://github.com/future-architect)\nrelease: \nlicense: Apache License, Version 2.0\nversion: \nsource: https://github.com/future-architect/puml-themes/tree/master/themes\ninspiration: \n---\n\nskinparam BackgroundColor F9F9F9\nskinparam shadowing false\nskinparam RoundCorner 7\nskinparam ArrowColor 191919\nskinparam FontColor 191919\nskinparam SequenceLifeLineBorderColor 393939\nskinparam SequenceGroupHeaderFontColor 191919\nskinparam SequenceGroupFontColor 393939\nskinparam SequenceGroupBorderColor 393939\nskinparam SequenceGroupBorderThickness 1\n\nskinparam sequenceDivider {\n    BorderColor 191919\n    BorderThickness 1\n    FontColor 191919\n}\n\nskinparam participant {\n    BackgroundColor E55756\n    BorderColor 191919\n    FontColor F9F9F9\n    BorderThickness 1.5\n}\n\nskinparam database {\n    BackgroundColor A4DBD8\n    BorderColor 191919\n    FontColor 191919\n}\n\nskinparam entity {\n    BackgroundColor EFBABC\n    BorderColor 191919\n    FontColor 191919\n}\n\nskinparam note {\n    BackgroundColor e5e5e5\n    BorderColor 191919\n    FontColor 191919\n    BorderThickness 1.5\n}\n\nskinparam actor {\n    BackgroundColor 191919\n    BorderColor 191919\n    FontColor 191919\n}\n\nskinparam boundary {\n    BackgroundColor EFBABC\n    BorderColor 191919\n    FontColor 191919\n}\n\nskinparam control {\n    BackgroundColor EFBABC\n    BorderColor 191919\n    FontColor 191919\n}\n\nskinparam collections {\n    BackgroundColor E55756\n    BorderColor 191919\n    FontColor 191919\n    BorderThickness 1.5\n}\n\nskinparam queue {\n    BackgroundColor E55756\n    BorderColor 191919\n    FontColor FFF\n    BorderThickness 1.5\n}\n";
g.PLANTUML_THEMES["materia"]="---\nname: materia\ndisplay_name: Materia\ndescription: Theme based off of the bootstrap theme of the same name\nauthor: Brett Schwarz\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/bschwarz/puml-themes\ninspiration: https://bootswatch.com/materia/\n---\n\n!$THEME = \"materia\"\n\n!if %not(%variable_exists(\"$BGCOLOR\"))\n!$BGCOLOR = \"transparent\"\n!endif\n\nskinparam backgroundColor $BGCOLOR\nskinparam useBetaStyle false\n\n''\n'' Colors taken from the css file of the BS theme\n''\n!$BLUE = \"#2196F3\"\n!$INDIGO = \"#6610f2\"\n!$PURPLE = \"#6f42c1\"\n!$PINK = \"#e83e8c\"\n!$RED = \"#e51c23\"\n!$ORANGE = \"#fd7e14\"\n!$YELLOW = \"#ff9800\"\n!$GREEN = \"#4CAF50\"\n!$TEAL = \"#20c997\"\n!$CYAN = \"#9C27B0\"\n!$WHITE = \"#FFF\"\n!$GRAY_DARK = \"#222\"\n!$GRAY = \"#666\"\n!$PRIMARY = \"#2196F3\"\n!$SECONDARY = \"#fff\"\n!$SUCCESS = \"#4CAF50\"\n!$INFO = \"#9C27B0\"\n!$WARNING = \"#ff9800\"\n!$DANGER = \"#e51c23\"\n!$LIGHT = \"#fff\"\n!$DARK = \"#222\"\n\n'' *_LIGHT = tint (lighter) of the main color of 80%\n'' *_DARK = shade (darker) of the main color of 80%\n''\n!$FGCOLOR = $DARK\n!$PRIMARY_LIGHT = \"#4dabf5\"\n!$PRIMARY_DARK = \"#1a78c2\"\n!$PRIMARY_TEXT = $WHITE\n!$SECONDARY_LIGHT = \"#fff\"\n!$SECONDARY_DARK = \"#cccccc\"\n!$SECONDARY_TEXT = $DARK\n!$INFO_LIGHT = \"#b052c0\"\n!$INFO_DARK = \"#7D1F8D\"\n!$INFO_TEXT = $WHITE\n!$SUCCESS_LIGHT = \"#70bf73\"\n!$SUCCESS_DARK = \"#3D8C40\"\n!$SUCCESS_TEXT = $WHITE\n!$WARNING_LIGHT = \"#ffad33\"\n!$WARNING_DARK = \"#CC7A00\"\n!$WARNING_TEXT = $WHITE\n!$DANGER_DARK = \"#b7161c\"\n!$DANGER_LIGHT = \"#B7161C\"\n!$DANGER_TEXT = $WHITE\n\n!procedure $success($msg)\n  <font color=$SUCCESS><b>$msg\n!endprocedure\n\n!procedure $failure($msg)\n  <font color=$DANGER><b>$msg\n!endprocedure\n\n!procedure $warning($msg)\n  <font color=$WARNING><b>$msg\n!endprocedure\n\n!procedure $primary_scheme()\n\tFontColor $PRIMARY_TEXT\n\tBorderColor $PRIMARY\n\tBackgroundColor $PRIMARY_LIGHT-$PRIMARY\n!endprocedure\n''\n'' Style settings\n''\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $PRIMARY_TEXT\n    HyperLinkColor $ORANGE\n    LineColor $PRIMARY_DARK\n    LineThickness 1\n    Margin 10\n    Padding 6\n    Shadowing 0.0\n  }\n  node {\n   Padding 15\n   roundcorner 20\n   BackgroundColor $PRIMARY-$PRIMARY_DARK\n  }\n  caption {\n    LineThickness 0\n  }\n  footer {\n    LineThickness 0\n  }\n  groupHeader {\n    BackgroundColor $SECONDARY\n    FontColor $INFO\n    FontStyle bold\n  }\n  header {\n    LineThickness 0\n  }\n  referenceHeader {\n    BackgroundColor $BGCOLOR\n    FontColor $DARK\n    FontStyle bold\n  }\n  separator {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  title {\n\tFontSize 20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tFontColor $PRIMARY\n\tBorderColor $SECONDARY\n  }\n  nwdiagDiagram {\n\tnetwork {\n\t\t$primary_scheme()    \n\t\tLineColor $PRIMARY\n\t\tLineThickness 1.0\n\t\tFontColor $PRIMARY_DARK\n\t}\n\tserver {\n\t\t$primary_scheme()\n\t}\n\tarrow {\n\t\tFontColor $PRIMARY_DARK\n\t\tLineColor $PRIMARY_DARK\n\t}\n\tgroup {\n\t\tBackGroundColor $LIGHT\n\t\tLineColor $LIGHT_DARK\n\t\tLineThickness 2.0\n\t\tMargin 5\n\t\tPadding 5\n\t}\n  }\n  participant {\n    Margin 5 40\n    Padding 15 20\n  }\n  ganttDiagram {\n\ttask {\n\t\t$primary_scheme()\n\t\tLineColor $PRIMARY\n\t\tMargin 10 2 2 2\n\t\tPadding 6\n\t}\n\tnote {\n\t\tFontColor $INFO_TEXT\n\t\tLineColor $INFO_DARK\n\t\tBackGroundColor $INFO\n\t}\n\tseparator {\n\t\tLineColor $SECONDARY\n\t\tBackGroundColor $SECONDARY-$SECONDARY_DARK\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tmilestone {\n\t\tFontColor $INFO\n\t\tFontSize 16\n\t\tFontStyle italic\n\t\tBackGroundColor $SECONDARY\n\t\tLineColor $SECONDARY_DARK\n\t}\n\ttimeline {\n\t\tBackgroundColor $SECONDARY\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tclosed {\n\t\tBackgroundColor $WARNING_DARK\n\t\tFontColor $WARNING_TEXT\n\t}\n  }\n</style>\n''\n'' Global Default Values\n''\nskinparam defaultFontName       \"Verdana\"\nskinparam defaultFontSize       12\nskinparam dpi                   100\nskinparam shadowing             true\nskinparam roundcorner           8\nskinparam BoxPadding            40\nskinparam ArrowColor            $GRAY\nskinparam stereotype {\n    CBackgroundColor $SECONDARY_LIGHT\n    CBorderColor $SECONDARY_DARK\n    ABackgroundColor $SUCCESS_LIGHT\n    ABorderColor $SUCCESS_DARK\n    IBackgroundColor $DANGER_LIGHT\n    IBorderColor $DANGER_DARK\n    EBackgroundColor $WARNING_LIGHT\n    EBorderColor $WARNING_DARK\n    NBackgroundColor $INFO_LIGHT\n    NBorderColor $INFO_DARK\n}\nskinparam title {\n\tFontColor\t                 $PRIMARY\n\tBorderColor\t                 $SECONDARY_DARK\n\tFontSize\t    \t         20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor              $SECONDARY_LIGHT-$SECONDARY\n}\n\nskinparam legend {\n\tBackgroundColor $SECONDARY\n\tBorderColor $SECONDARY_DARK\n\tFontColor $DARK\n}\n\n!startsub swimlane\nskinparam swimlane {\n\tBorderColor $INFO\n\tBorderThickness 2\n\tTitleBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tTitleFontColor $PRIMARY\n}\n!endsub\n\n!startsub activity\n\nskinparam activity {\n\t$primary_scheme()\n\tBarColor $SUCCESS\n\tStartColor $INFO\n\tEndColor $INFO\n\t''\n\tDiamondBackgroundColor $WHITE-$SECONDARY_LIGHT\n  \tDiamondBorderColor $SECONDARY_DARK\n\tDiamondFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub participant\n\nskinparam participant {\n\t$primary_scheme()\n\tParticipantBorderThickness 2\n}\n!endsub\n\n!startsub actor\n\nskinparam actor {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub arrow\n\nskinparam arrow {\n\tThickness 3\n\tColor $PRIMARY\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub sequence\n\nskinparam sequence {\n\tBorderColor $PRIMARY\n\t' For some reason sequence title font color does not pick up from global\n\tTitleFontColor $PRIMARY\n\tBackgroundColor transparent\n\tStartColor $PRIMARY\n\tEndColor $PRIMARY\n\t''\n\tBoxBackgroundColor $LIGHT\n\tBoxBorderColor $GRAY\n\tBoxFontColor $DARK\n\t''\n\tDelayFontColor $DARK\n\t''\n\tLifeLineBorderColor $SECONDARY_DARK\n\tLifeLineBorderThickness 2\n\tLifeLineBackgroundColor $SECONDARY_LIGHT\n\t''\n\tGroupBorderColor $GRAY\n\tGroupFontColor $DARK\n\tGroupHeaderFontColor $INFO\n\t''\n\tDividerBackgroundColor $WHITE-$LIGHT\n    DividerBorderColor $GRAY\n    DividerBorderThickness 2\n    DividerFontColor $DARK\n\t''\n\tReferenceBackgroundColor $BGCOLOR\n\tReferenceBorderColor $GRAY\n\tReferenceFontColor $DARK\n\tReferenceHeaderFontColor $INFO\n\t''\n\tStereotypeFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub partition\n\nskinparam partition {\n\tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBackgroundColor transparent\n}\n!endsub\n\n!startsub collections\n\nskinparam collections {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub control\n\nskinparam control {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub entity\n\nskinparam entity {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub boundary\n\nskinparam boundary {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub agent\n\nskinparam agent {\n\tBackgroundColor #orange\n\tBorderColor #999999\n\tFontColor #333333\n}\n!endsub\n\n!startsub note\n\nskinparam note {\n\tBorderThickness 1\n\tBackgroundColor $INFO_LIGHT-$INFO\n\tBorderColor $INFO\n\tFontColor $WHITE\n}\n!endsub\n\n!startsub artifact\n\nskinparam artifact {\n\tBackgroundColor $WHITE-$LIGHT\n\tBorderColor $GRAY\n\tFontColor $GRAY\n}\n!endsub\n\n!startsub component\n\nskinparam component {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub interface\n\nskinparam interface {\n\tBackgroundColor  $DANGER_LIGHT\n\tBorderColor  $DANGER\n\tFontColor $DARK\n}\n!endsub\n\n!startsub storage\n\nskinparam storage {\n\tBackgroundColor $WARNING_LIGHT-$WARNING\n  \tBorderColor $WARNING\n\tFontColor $WARNING_TEXT\n}\n!endsub\n\n!startsub node\n\nskinparam node {\n\tBackgroundColor $SECONDARY_LIGHT-$SECONDARY\n\tBorderColor $DARK\n\tFontColor $DARK\n}\n!endsub\n\n!startsub cloud\n\nskinparam cloud {\n\tBackgroundColor #F2FCFE-#eeeeee\n\tBorderColor #F2FCFE\n\tFontColor $DARK\n}\n!endsub\n\n!startsub database\n\nskinparam database {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub class\n\nskinparam class {\n\t$primary_scheme()\n\tHeaderBackgroundColor $PRIMARY-$PRIMARY_DARK\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $LIGHT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub object\n\nskinparam object {\n\t$primary_scheme()\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub usecase\n\nskinparam usecase {\n\t$primary_scheme()\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub rectangle\n\nskinparam rectangle {\n\tFontColor $PRIMARY\n\tBackgroundColor $SECONDARY_LIGHT-$SECONDARY\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub package\n\nskinparam package {\n\t$primary_scheme()\n\tBackgroundColor $SECONDARY_LIGHT-$SECONDARY\n\tBorderThickness 2\n}\n!endsub\n\n!startsub folder\n\nskinparam folder {\n\tBackgroundColor $WHITE-$SECONDARY_LIGHT\n  \tBorderColor $WARNING\n\tFontColor $WARNING\n\tBorderThickness 2\n}\n!endsub\n\n!startsub frame\n\nskinparam frame {\n\tBackgroundColor $WHITE-$SECONDARY_LIGHT\n  \tBorderColor $INFO\n\tFontColor $INFO\n\tBorderThickness 2\n}\n!endsub\n\n!startsub state\n\nskinparam state {\n\t$primary_scheme()\n\tBorderColor $PRIMARY_DARK\n\tStartColor $INFO\n\tEndColor $INFO\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub queue\n\nskinparam queue {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub card\n\nskinparam card {\n\tBackgroundColor $INFO_LIGHT-$INFO\n\tBorderColor $INFO\n\tFontColor $INFO_TEXT\n}\n!endsub\n\n!startsub file\n\nskinparam file {\n\tBackgroundColor $SECONDARY_LIGHT-$SECONDARY\n\tBorderColor $GRAY\n\tFontColor $GRAY\n\n}\n!endsub\n\n!startsub stack\n\nskinparam stack {\n\t$primary_scheme()\n}\n!endsub\n";
g.PLANTUML_THEMES["materia-outline"]="---\nname: materia-outline\ndisplay_name: Materia Outline\ndescription: Theme based off of the bootstrap theme of the same name, with outline colors\nauthor: Brett Schwarz\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/bschwarz/puml-themes\ninspiration: https://bootswatch.com/materia/\n---\n\n!$THEME = \"materia-outline\"\n\n!if %not(%variable_exists(\"$BGCOLOR\"))\n!$BGCOLOR = \"transparent\"\n!endif\n\nskinparam backgroundColor $BGCOLOR\nskinparam useBetaStyle false\n\n''\n'' Colors taken from the css file of the BS theme\n''\n!$BLUE = \"#2196F3\"\n!$INDIGO = \"#6610f2\"\n!$PURPLE = \"#6f42c1\"\n!$PINK = \"#e83e8c\"\n!$RED = \"#e51c23\"\n!$ORANGE = \"#fd7e14\"\n!$YELLOW = \"#ff9800\"\n!$GREEN = \"#4CAF50\"\n!$TEAL = \"#20c997\"\n!$CYAN = \"#9C27B0\"\n!$WHITE = \"#FFF\"\n!$GRAY_DARK = \"#222\"\n!$GRAY = \"#666\"\n!$PRIMARY = \"#2196F3\"\n!$SECONDARY = \"#fff\"\n!$SUCCESS = \"#4CAF50\"\n!$INFO = \"#9C27B0\"\n!$WARNING = \"#ff9800\"\n!$DANGER = \"#e51c23\"\n!$LIGHT = \"#fff\"\n!$DARK = \"#222\"\n\n'' *_LIGHT = tint (lighter) of the main color of 80%\n''          where TINT is calculated by clr + (255-clr) * tint_factor\n'' *_DARK = shade (darker) of the main color of 80%\n''          and SHADE is calculated by clr * (1 - shade_factor)\n''\n!$FGCOLOR = $DARK\n!$PRIMARY_LIGHT = \"#4dabf5\"\n!$PRIMARY_DARK = \"#1a78c2\"\n!$PRIMARY_TEXT = $PRIMARY\n!$SECONDARY_LIGHT = \"#fff\"\n!$SECONDARY_DARK = \"#cccccc\"\n!$SECONDARY_TEXT = $SECONDARY_DARK\n!$INFO_LIGHT = \"#b052c0\"\n!$INFO_DARK = \"#7D1F8D\"\n!$INFO_TEXT = $INFO\n!$SUCCESS_LIGHT = \"#70bf73\"\n!$SUCCESS_DARK = \"#3D8C40\"\n!$SUCCESS_TEXT = $SUCCESS\n!$WARNING_LIGHT = \"#ffad33\"\n!$WARNING_DARK = \"#CC7A00\"\n!$WARNING_TEXT = $WARNING\n!$DANGER_LIGHT = \"#B7161C\"\n!$DANGER_TEXT = $DANGER\n\n!procedure $success($msg)\n  <font color=$SUCCESS><b>$msg\n!endprocedure\n\n!procedure $failure($msg)\n  <font color=$DANGER><b>$msg\n!endprocedure\n\n!procedure $warning($msg)\n  <font color=$WARNING><b>$msg\n!endprocedure\n\n!procedure $primary_scheme()\n\tFontColor $PRIMARY_TEXT\n\tBorderColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n!endprocedure\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $PRIMARY_TEXT\n    HyperLinkColor $ORANGE\n    LineColor $PRIMARY_DARK\n    LineThickness 1\n    Margin 10\n    Padding 6\n    Shadowing 0.0\n  }\n  node {\n   Padding 15\n   roundcorner 20\n   BackgroundColor $BGCOLOR\n  }\n  caption {\n    LineThickness 0\n  }\n  footer {\n    LineThickness 0\n  }\n  groupHeader {\n    BackgroundColor $SECONDARY\n    FontColor $INFO\n    FontStyle bold\n  }\n  header {\n    LineThickness 0\n  }\n  referenceHeader {\n    BackgroundColor $BGCOLOR\n    FontColor $DARK\n    FontStyle bold\n  }\n  separator {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  title {\n\tFontSize 20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor  $BGCOLOR\n\tFontColor $PRIMARY\n\tBorderColor $SECONDARY\n  }\n  nwdiagDiagram {\n\tnetwork {\n\t\t$primary_scheme()    \n\t\tLineColor $PRIMARY\n\t\tLineThickness 1.0\n\t\tFontColor $PRIMARY_DARK\n\t}\n\tserver {\n\t\t$primary_scheme()\n\t}\n\tarrow {\n\t\tFontColor $PRIMARY_DARK\n\t\tLineColor $PRIMARY_DARK\n\t}\n\tgroup {\n\t\tBackGroundColor $LIGHT\n\t\tLineColor $LIGHT_DARK\n\t\tLineThickness 2.0\n\t\tMargin 5\n\t\tPadding 5\n\t}\n  }\n  participant {\n    Margin 5 40\n    Padding 15 20\n  }\n  ganttDiagram {\n\ttask {\n\t\t$primary_scheme()\n\t\tLineColor $PRIMARY\n\t\tMargin 10 2 2 2\n\t\tPadding 6\n\t}\n\tnote {\n\t\tFontColor $INFO_TEXT\n\t\tLineColor $INFO_DARK\n\t\tBackGroundColor $BGCOLOR\n\t}\n\tseparator {\n\t\tLineColor $SECONDARY_DARK\n\t\tBackGroundColor $BGCOLOR\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tmilestone {\n\t\tFontColor $INFO\n\t\tFontSize 16\n\t\tFontStyle italic\n\t\tBackGroundColor $SECONDARY\n\t\tLineColor $SECONDARY_DARK\n\t}\n\ttimeline {\n\t\tBackgroundColor $SECONDARY\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tclosed {\n\t\tBackgroundColor $WARNING_DARK\n\t\tFontColor $WARNING_TEXT\n\t}\n  }\n</style>\n''\n'' Global Default Values\n''\nskinparam defaultFontName       \"Verdana\"\nskinparam defaultFontSize       12\nskinparam dpi                   100\nskinparam shadowing             true\nskinparam roundcorner           8\nskinparam BoxPadding            40\nskinparam TitleFontColor\t    $DARK\nskinparam TitleFontSize\t    \t20\nskinparam TitleBorderThickness \t0\nskinparam ArrowColor            $GRAY\nskinparam stereotype {\n    CBackgroundColor $SECONDARY_LIGHT\n    CBorderColor $SECONDARY_DARK\n    ABackgroundColor $SUCCESS_LIGHT\n    ABorderColor $SUCCESS_DARK\n    IBackgroundColor $DANGER_LIGHT\n    IBorderColor $DANGER_DARK\n    EBackgroundColor $WARNING_LIGHT\n    EBorderColor $WARNING_DARK\n    NBackgroundColor $INFO_LIGHT\n    NBorderColor $INFO_DARK\n}\nskinparam title {\n\tFontColor\t                 $PRIMARY\n\tBorderColor\t                 $SECONDARY_DARK\n\tFontSize\t    \t         20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor              $BGCOLOR\n}\n\nskinparam legend {\n\tBackgroundColor $BGCOLOR\n\tBorderColor $SECONDARY_DARK\n\tFontColor $DARK\n}\n\n!startsub swimlane\nskinparam swimlane {\n\tBorderColor $INFO\n\tBorderThickness 2\n\tTitleBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tTitleFontColor $PRIMARY\n}\n!endsub\n\n!startsub activity\n\nskinparam activity {\n\t$primary_scheme()\n\t' FontColor $PRIMARY_TEXT\n\t' BorderColor $PRIMARY\n\t' BackgroundColor $BGCOLOR\n\tBarColor $SUCCESS\n\tStartColor $INFO\n\tEndColor $INFO\n\t''\n\tDiamondBackgroundColor $BGCOLOR\n  \tDiamondBorderColor $SECONDARY_DARK\n\tDiamondFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub participant\n\nskinparam participant {\n\t$primary_scheme()\n\tParticipantBorderThickness 2\n}\n!endsub\n\n!startsub actor\n\nskinparam actor {\n\t$primary_scheme()\n\t' FontColor $DARK\n}\n!endsub\n\n!startsub arrow\n\nskinparam arrow {\n\tThickness 3\n\tColor $PRIMARY\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub sequence\n\nskinparam sequence {\n\tBorderColor $PRIMARY\n\t' For some reason sequence title font color does not pick up from global\n\tTitleFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n\tStartColor $PRIMARY\n\tEndColor $PRIMARY\n\t''\n\tBoxBackgroundColor $BGCOLOR\n\tBoxBorderColor $GRAY\n\tBoxFontColor $DARK\n\t''\n\tDelayFontColor $DARK\n\t''\n\tLifeLineBorderColor $SECONDARY_DARK\n\tLifeLineBorderThickness 2\n\tLifeLineBackgroundColor $BGCOLOR\n\t''\n\tGroupBorderColor $GRAY\n\tGroupFontColor $DARK\n\tGroupHeaderFontColor $INFO\n\t''\n\tDividerBackgroundColor $BGCOLOR\n    DividerBorderColor $GRAY\n    DividerBorderThickness 2\n    DividerFontColor $DARK\n\t''\n\tReferenceBackgroundColor $BGCOLOR\n\tReferenceBorderColor $GRAY\n\tReferenceFontColor $DARK\n\tReferenceHeaderFontColor $INFO\n\t''\n\tStereotypeFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub partition\n\nskinparam partition {\n\tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n}\n!endsub\n\n!startsub collections\n\nskinparam collections {\n\t$primary_scheme()\n\t' BackgroundColor $BGCOLOR\n\t' BorderColor $PRIMARY\n}\n!endsub\n\n!startsub control\n\nskinparam control {\n\t$primary_scheme()\n\t' BackgroundColor  $BGCOLOR\n\t' BorderColor $PRIMARY_DARK\n\t' FontColor $DARK\n}\n!endsub\n\n!startsub entity\n\nskinparam entity {\n\t$primary_scheme()\n\t' BackgroundColor  $BGCOLOR\n\t' BorderColor $PRIMARY_DARK\n\t' FontColor $DARK\n}\n!endsub\n\n!startsub boundary\n\nskinparam boundary {\n\t$primary_scheme()\n\t' BackgroundColor  $BGCOLOR\n\t' BorderColor $PRIMARY_DARK\n\t' FontColor $DARK\n}\n!endsub\n\n!startsub agent\n\nskinparam agent {\n\tBackgroundColor $BGCOLOR\n\tBorderColor #999999\n\tFontColor #333333\n}\n!endsub\n\n!startsub note\n\nskinparam note {\n\tBorderThickness 1\n\tBackgroundColor $BGCOLOR\n\tBorderColor $INFO\n\tFontColor $INFO\n}\n!endsub\n\n!startsub artifact\n\nskinparam artifact {\n\tBackgroundColor $BGCOLOR\n\tBorderColor $GRAY\n\tFontColor $GRAY\n}\n!endsub\n\n!startsub component\n\nskinparam component {\n\t$primary_scheme()\n\t' BackgroundColor  $BGCOLOR\n\t' BorderColor  $SUCCESS\n\t' FontColor $SUCCESS_TEXT\n}\n!endsub\n\n!startsub interface\n\nskinparam interface {\n\tBackgroundColor  $BGCOLOR\n\tBorderColor  $DANGER\n\tFontColor $DARK\n}\n!endsub\n\n!startsub storage\n\nskinparam storage {\n\tBackgroundColor $BGCOLOR\n  \tBorderColor $WARNING\n\tFontColor $WARNING_TEXT\n}\n!endsub\n\n!startsub node\n\nskinparam node {\n\tBackgroundColor $BGCOLOR\n\tBorderColor $DARK\n\tFontColor $DARK\n}\n!endsub\n\n!startsub cloud\n\nskinparam cloud {\n\tBackgroundColor #F2FCFE-#eeeeee\n\tBorderColor #F2FCFE\n\tFontColor $DARK\n}\n!endsub\n\n!startsub database\n\nskinparam database {\n\t$primary_scheme()\n\t' BackgroundColor  $BGCOLOR\n\t' BorderColor $PRIMARY_DARK\n\t' FontColor $DARK\n}\n!endsub\n\n!startsub class\n\nskinparam class {\n\t$primary_scheme()\n\tFontColor $LIGHT\n\tHeaderBackgroundColor $PRIMARY-$PRIMARY_DARK\n\t' FontColor $PRIMARY_TEXT\n\t' BackgroundColor $BGCOLOR\n\t' BorderColor $PRIMARY_DARK\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $DARK\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub object\n\nskinparam object {\n\t$primary_scheme()\n\t' FontColor $SUCCESS\n\t' BackgroundColor $BGCOLOR\n\t' BorderColor $SECONDARY_DARK\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $SECONDARY_DARK\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub usecase\n\nskinparam usecase {\n\t$primary_scheme()\n\t' BackgroundColor $BGCOLOR\n\t' BorderColor $SECONDARY_DARK\n\tBorderThickness 2\n\t' FontColor $SECONDARY_TEXT\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub rectangle\n\nskinparam rectangle {\n\t$primary_scheme()\n\t' BackgroundColor $BGCOLOR\n\t' BorderColor $PRIMARY_DARK\n\tBorderThickness 2\n\t' FontColor $PRIMARY\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub package\n\nskinparam package {\n\tBackgroundColor $BGCOLOR\n  \tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBorderThickness 2\n}\n!endsub\n\n!startsub folder\n\nskinparam folder {\n\tBackgroundColor $BGCOLOR\n  \tBorderColor $WARNING\n\tFontColor $WARNING\n\tBorderThickness 2\n}\n!endsub\n\n!startsub frame\n\nskinparam frame {\n\tBackgroundColor $BGCOLOR\n  \tBorderColor $INFO\n\tFontColor $INFO\n\tBorderThickness 2\n}\n!endsub\n\n!startsub state\n\nskinparam state {\n\t$primary_scheme()\n\tStartColor $INFO\n\tEndColor $INFO\n\t' BackgroundColor $BGCOLOR\n\t' BorderColor $SECONDARY_DARK\n\t' FontColor $INFO\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub queue\n\nskinparam queue {\n\t$primary_scheme()\n\t' BackgroundColor $BGCOLOR\n  \t' BorderColor $WARNING_DARK\n\t' FontColor $WARNING_TEXT\n}\n!endsub\n\n!startsub card\n\nskinparam card {\n\tBackgroundColor $BGCOLOR\n\tBorderColor $INFO\n\tFontColor $INFO_TEXT\n}\n!endsub\n\n!startsub file\n\nskinparam file {\n\tBackgroundColor $BGCOLOR\n\tBorderColor $GRAY\n\tFontColor $GRAY\n\n}\n!endsub\n\n!startsub stack\n\nskinparam stack {\n\t$primary_scheme()\n\t' BackgroundColor $BGCOLOR\n\t' BorderColor $PRIMARY\n\t' FontColor $PRIMARY_TEXT\n}\n!endsub\n";
g.PLANTUML_THEMES["metal"]="---\nname: metal\ndisplay_name: Metal\ndescription: Mostly metal grays theme\nauthor: Brett Schwarz\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/bschwarz/puml-themes\ninspiration: \n---\n\n!$THEME = \"metal\"\n\n!if %not(%variable_exists(\"$BGCOLOR\"))\n!$BGCOLOR = \"transparent\"\n!endif\n\nskinparam backgroundColor $BGCOLOR\nskinparam useBetaStyle false\n\n!$WHITE = \"#fdfdfd\"\n!$GRAY_DARK = \"#4d4d4d\"\n!$GRAY = \"#737373\"\n!$LIGHT = \"#f2f2f2\"\n!$DARK = \"#4d4d4d\"\n\n!$SILVER = \"#c0c0c0\"\n!$COPPER = \"#B87333c\"\n!$STEELBLUE = \"#4682b4\"\n!$LIGHTSTEELBLUE = \"#B0C4DE\" \n!$LIGHTSTEELBLUE_DARK = \"#8d9db2\" \n!$LIGHTSTEELBLUE_LIGHT = \"#c0d0e5\" \n!$ALUMINUM = \"#c9ced0\"\n!$ALUMINUM_DARK = \"#a1a5a6\"\n!$ALUMINUM_LIGHT = \"#d4d8d9\"\n!$BRONZE = \"#CD7F32\" \n!$BRONZE_DARK = \"#a46628\" \n!$BRONZE_LIGHT = \"#d7995b\" \n!$GOLD = \"#FFD700\"\n!$PLATINUM = \"#E5E4E2\"\n!$RUST = \"#B7410E\"\n\n\n\n'' *_LIGHT = tint (lighter) of the main color of 80%\n''          where TINT is calculated by clr + (255-clr) * tint_factor\n'' *_DARK = shade (darker) of the main color of 80%\n''          and SHADE is calculated by clr * (1 - shade_factor)\n''\n!$FGCOLOR = $DARK\n!$PRIMARY = $PLATINUM\n!$PRIMARY_LIGHT = \"#eae9e8\"\n!$PRIMARY_DARK = \"#b7b6b5\"\n!$PRIMARY_TEXT = $STEELBLUE\n!$SECONDARY = $SILVER\n!$SECONDARY_LIGHT = \"#cdcdcd\"\n!$SECONDARY_DARK = \"#9a9a9a\"\n!$SECONDARY_TEXT = $WHITE\n!$INFO = $STEELBLUE\n!$INFO_LIGHT = \"#5c85ad\"\n!$INFO_DARK = \"#29527a\"\n!$INFO_TEXT = $WHITE\n!$SUCCESS = \"#339933\"\n!$SUCCESS_LIGHT = \"#5cad5c\"\n!$SUCCESS_DARK = \"#297a29\"\n!$SUCCESS_TEXT = $WHITE\n!$WARNING = $GOLD\n!$WARNING_LIGHT = \"#ffdf33\"\n!$WARNING_DARK = \"#ccac00\"\n!$WARNING_TEXT = $WHITE\n!$DANGER = $RUST\n!$DANGER_LIGHT = \"#c5673e\"\n!$DANGER_DARK = \"#92340b\"\n!$DANGER_TEXT = $WHITE\n\n!procedure $success($msg)\n  <font color=$SUCCESS><b>$msg\n!endprocedure\n\n!procedure $failure($msg)\n  <font color=$DANGER><b>$msg\n!endprocedure\n\n!procedure $warning($msg)\n  <font color=$WARNING><b>$msg\n!endprocedure\n\n!procedure $primary_scheme()\n\tFontColor $PRIMARY_TEXT\n\tBorderColor $PRIMARY_DARK\n\tBackgroundColor $PRIMARY-$PRIMARY_DARK\n!endprocedure\n''\n'' Style settings\n''\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $PRIMARY_TEXT\n    HyperLinkColor $ORANGE\n    LineColor $PRIMARY_DARK\n    LineThickness 1\n    Margin 10\n    Padding 6\n    Shadowing 0.0\n  }\n  node {\n   Padding 15\n   roundcorner 20\n   BackgroundColor $PRIMARY-$PRIMARY_DARK\n  }\n  caption {\n    LineThickness 0\n  }\n  footer {\n    LineThickness 0\n  }\n  groupHeader {\n    BackgroundColor $SECONDARY\n    FontColor $INFO\n    FontStyle bold\n  }\n  header {\n    LineThickness 0\n  }\n  referenceHeader {\n    BackgroundColor $BGCOLOR\n    FontColor $DARK\n    FontStyle bold\n  }\n  separator {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  title {\n\tFontSize 20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tFontColor $PRIMARY\n\tBorderColor $SECONDARY\n  }\n  nwdiagDiagram {\n\tnetwork {\n\t\t$primary_scheme()    \n\t\tLineColor $PRIMARY\n\t\tLineThickness 1.0\n\t\tFontColor $PRIMARY_DARK\n\t}\n\tserver {\n\t\t$primary_scheme()\n\t}\n\tarrow {\n\t\tFontColor $PRIMARY_DARK\n\t\tLineColor $PRIMARY_DARK\n\t}\n\tgroup {\n\t\tBackGroundColor $LIGHT\n\t\tLineColor $LIGHT_DARK\n\t\tLineThickness 2.0\n\t\tMargin 5\n\t\tPadding 5\n\t}\n  }\n  participant {\n    Margin 5 30\n    Padding 15 20\n  }\n  ganttDiagram {\n\ttask {\n\t\t$primary_scheme()\n\t\tLineColor $PRIMARY\n\t\tMargin 10 2 2 2\n\t\tPadding 6\n\t}\n\tnote {\n\t\tFontColor $INFO_TEXT\n\t\tLineColor $INFO_DARK\n\t\tBackGroundColor $INFO\n\t}\n\tseparator {\n\t\tLineColor $SECONDARY\n\t\tBackGroundColor $SECONDARY-$SECONDARY_DARK\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tmilestone {\n\t\tFontColor $INFO\n\t\tFontSize 16\n\t\tFontStyle italic\n\t\tBackGroundColor $SECONDARY\n\t\tLineColor $SECONDARY_DARK\n\t}\n\ttimeline {\n\t\tBackgroundColor $SECONDARY\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tclosed {\n\t\tBackgroundColor $WARNING_DARK\n\t\tFontColor $WARNING_TEXT\n\t}\n  }\n</style>\n''\n'' Global Default Values\n''\nskinparam defaultFontName        \"Verdana\"\nskinparam defaultFontSize        12\nskinparam dpi                    100\nskinparam shadowing              false\nskinparam roundcorner            15\nskinparam BoxPadding             30\nskinparam ArrowColor             $GRAY\nskinparam stereotype {\n    CBackgroundColor $SECONDARY_LIGHT\n    CBorderColor $SECONDARY_DARK\n    ABackgroundColor $SUCCESS_LIGHT\n    ABorderColor $SUCCESS_DARK\n    IBackgroundColor $DANGER_LIGHT\n    IBorderColor $DANGER_DARK\n    EBackgroundColor $WARNING_LIGHT\n    EBorderColor $WARNING_DARK\n    NBackgroundColor $INFO_LIGHT\n    NBorderColor $INFO_DARK\n}\nskinparam title {\n\tFontColor\t                 $WHITE\n\tBorderColor\t                 $SECONDARY_DARK\n\tFontSize\t    \t         20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor              $SECONDARY_LIGHT-$SECONDARY_DARK\n}\n\n\nskinparam legend {\n\tBackgroundColor $PRIMARY_LIGHT-$PRIMARY\n\tBorderColor $SECONDARY_DARK\n\tFontColor $PRIMARY_TEXT\n}\n\n!startsub swimlane\nskinparam swimlane {\n\tBorderColor $INFO\n\tBorderThickness 2\n\tTitleBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tTitleFontColor $PRIMARY\n}\n!endsub\n\n!startsub activity\n\nskinparam activity {\n\t$primary_scheme()\n\tBarColor $BRONZE\n\tStartColor $INFO\n\tEndColor $INFO\n\t''\n\tDiamondBackgroundColor $SECONDARY-$SECONDARY_DARK\n  \tDiamondBorderColor $SECONDARY_DARK\n\tDiamondFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub participant\n\nskinparam participant {\n\t$primary_scheme()\n\tParticipantBorderThickness 2\n}\n!endsub\n\n!startsub actor\n\nskinparam actor {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub arrow\n\nskinparam arrow {\n\tThickness 3\n\tColor $PRIMARY\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub sequence\n\nskinparam sequence {\n\tBorderColor $PRIMARY\n\t' For some reason sequence title font color does not pick up from global\n\tTitleFontColor $WHITE\n\tBackgroundColor $BGCOLOR\n\tStartColor $PRIMARY\n\tEndColor $PRIMARY\n\t''\n\tBoxBackgroundColor $LIGHT\n\tBoxBorderColor $GRAY\n\tBoxFontColor $DARK\n\t''\n\tDelayFontColor $DARK\n\t''\n\tLifeLineBorderColor $SECONDARY_DARK\n\tLifeLineBorderThickness 3\n\tLifeLineBackgroundColor $SECONDARY_LIGHT-$SECONDARY_DARK\n\t''\n\tGroupBorderColor $GRAY\n\tGroupFontColor $DARK\n\tGroupHeaderFontColor $INFO\n\t''\n\tDividerBackgroundColor $WHITE-$LIGHT\n    DividerBorderColor $GRAY\n    DividerBorderThickness 2\n    DividerFontColor $DARK\n\t''\n\tReferenceBackgroundColor $BGCOLOR\n\tReferenceBorderColor $GRAY\n\tReferenceFontColor $DARK\n\tReferenceHeaderFontColor $INFO\n\t''\n\tStereotypeFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub partition\n\nskinparam partition {\n\tBorderColor $PRIMARY\n\tFontColor $PRIMARY_DARK\n\tBackgroundColor $BGCOLOR\n}\n!endsub\n\n!startsub collections\n\nskinparam collections {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub control\n\nskinparam control {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub entity\n\nskinparam entity {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub boundary\n\nskinparam boundary {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub agent\n\nskinparam agent {\n\tBackgroundColor #orange\n\tBorderColor #999999\n\tFontColor #333333\n}\n!endsub\n\n!startsub note\n\nskinparam note {\n\tBorderThickness 1\n\tBackgroundColor $LIGHTSTEELBLUE_LIGHT-$LIGHTSTEELBLUE_DARK\n\tBorderColor $LIGHTSTEELBLUE_DARK\n\tFontColor $WHITE\n}\n!endsub\n\n!startsub artifact\n\nskinparam artifact {\n\tBackgroundColor $SECONDARY_LIGHT-$SECONDARY_DARK\n\tBorderColor $SECONDARY_DARK\n\tFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub component\n\nskinparam component {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub interface\n\nskinparam interface {\n\tBackgroundColor  $DANGER_LIGHT\n\tBorderColor  $DANGER\n\tFontColor $DARK\n}\n!endsub\n\n!startsub storage\n\nskinparam storage {\n\tBackgroundColor $WARNING_LIGHT-$WARNING_DARK\n  \tBorderColor $WARNING_DARK\n\tFontColor $WARNING_TEXT\n}\n!endsub\n\n!startsub node\n\nskinparam node {\n\tBackgroundColor $PRIMARY_LIGHT-$PRIMARY\n\tBorderColor $PRIMARY\n\tFontColor $DARK\n}\n!endsub\n\n!startsub cloud\n\nskinparam cloud {\n\tBackgroundColor #F2FCFE-#eeeeee\n\tBorderColor #F2FCFE\n\tFontColor $DARK\n}\n!endsub\n\n!startsub database\n\nskinparam database {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n!endsub\n\n!startsub class\n\nskinparam class {\n\t$primary_scheme()\n\tHeaderBackgroundColor $PRIMARY_LIGHT-$PRIMARY_DARK\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $DARK\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub object\n\nskinparam object {\n\t$primary_scheme()\n\tStereotypeFontColor $LIGHT\n\tBorderThickness 1\n\tAttributeFontColor $WHITE\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub usecase\n\nskinparam usecase {\n\t$primary_scheme()\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub rectangle\n\nskinparam rectangle {\n\t$primary_scheme()\n\tBackgroundColor $WHITE-$LIGHT\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub package\n\nskinparam package {\n\t$primary_scheme()\n\tBackgroundColor $PRIMARY_LIGHT-$PRIMARY\n\tBorderThickness 2\n}\n!endsub\n\n!startsub folder\n\nskinparam folder {\n\tBackgroundColor $PRIMARY_LIGHT-$PRIMARY\n  \tBorderColor $RUST\n\tFontColor $RUST\n\tBorderThickness 2\n}\n!endsub\n\n!startsub frame\n\nskinparam frame {\n\tBackgroundColor $PRIMARY_LIGHT-$PRIMARY\n  \tBorderColor $INFO\n\tFontColor $INFO\n\tBorderThickness 2\n}\n!endsub\n\n!startsub state\n\nskinparam state {\n\t$primary_scheme()\n\tStartColor $INFO\n\tEndColor $INFO\n\tAttributeFontColor $SECONDARY\n    AttributeFontSize 11\n}\n!endsub\n\n!startsub queue\n\nskinparam queue {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub card\n\nskinparam card {\n\tBackgroundColor $INFO_LIGHT-$INFO_DARK\n\tBorderColor $INFO\n\tFontColor $INFO_TEXT\n}\n!endsub\n\n!startsub file\n\nskinparam file {\n\tBackgroundColor $SECONDARY_LIGHT-$SECONDARY_DARK\n\tBorderColor $GRAY\n\tFontColor $LIGHT\n\n}\n!endsub\n\n!startsub stack\n\nskinparam stack {\n\t$primary_scheme()\n}\n!endsub\n";
g.PLANTUML_THEMES["mimeograph"]="---\nname: mimeograph\ndisplay_name: Mimeograph\ndescription: A purple on grey theme based on the Mimeograph reproduction process\nauthor: Matthew Leather\nrelease: \nlicense: \nversion: \nsource: \ninspiration: https://en.wikipedia.org/wiki/Mimeograph\n---\n\n!$THEME = \"mimeograph\"\n\n!$BGCOLOR = \"#D9D3D0\"\n!$FGCOLOR = \"#9275B6\"\n\n!ifndef $FONT_NAME\n  !$FONT_NAME = \"Verdana\"\n!endif\n\n!ifndef $FONT_NAME_MONOSPACED\n  !$FONT_NAME_MONOSPACED = \"Courier\"\n!endif\n\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $FGCOLOR\n    FontName $FONT_NAME\n    HyperLinkColor $FGCOLOR\n    LineColor $FGCOLOR\n    LineThickness 1\n    Margin 5\n  }\n  document {\n    caption {\n      LineThickness 0\n    }\n    footer {\n      LineThickness 0\n    }\n    header {\n      LineThickness 0\n    }\n    title {\n      FontSize 22\n      LineThickness 0\n    }\n  }\n  node {\n    MaximumWidth 300\n  }\n  participant {\n    Margin 5 10\n    Padding 5 5\n  }\n</style>\n\nskinparam ArrowLollipopColor $FGCOLOR\nskinparam BackgroundColor $BGCOLOR\nskinparam DefaultFontName $FONT_NAME\nskinparam DefaultMonospacedFontName $FONT_NAME_MONOSPACED\nskinparam LifelineStrategy nosolid\nskinparam SequenceLifeLineBorderColor $FGCOLOR\nskinparam Shadowing false\nskinparam UseBetaStyle true\n\nskinparam Activity {\n  BackgroundColor $BGCOLOR\n  BarColor $FGCOLOR\n  BorderColor $FGCOLOR\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Boundary {\n  FontColor $FGCOLOR\n}\nskinparam Box {\n  Padding 5\n}\nskinparam CircledCharacter {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME_MONOSPACED\n  Radius 9\n}\nskinparam Class {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam ClassAttribute {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam ClassStereotype {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Footer {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Header {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Hyperlink {\n  Color $FGCOLOR\n}\nskinparam IconPackage {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam IconPrivate {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam IconProtected {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam IconPublic {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam Note {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Object {\n  BorderColor $FGCOLOR\n}\nskinparam Package {\n  BorderColor $FGCOLOR\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam State {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeA {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeC {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeE {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeI {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeN {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam UseCaseStereoType {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\n";
g.PLANTUML_THEMES["minty"]="---\nname: minty\ndisplay_name: Minty\ndescription: Theme based off of the bootstrap theme of the same name\nauthor: Brett Schwarz\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/bschwarz/puml-themes\ninspiration: https://bootswatch.com/minty/\n---\n\n!$THEME = \"minty\"\n\n!if %not(%variable_exists(\"$BGCOLOR\"))\n!$BGCOLOR = \"transparent\"\n!endif\n\nskinparam backgroundColor $BGCOLOR\nskinparam useBetaStyle false\n\n''\n'' Colors taken from the css file of the BS theme\n''\n!$BLUE = \"#007bff\"\n!$INDIGO = \"#6610f2\"\n!$PURPLE = \"#6f42c1\"\n!$PINK = \"#e83e8c\"\n!$RED = \"#ff7851\"\n!$ORANGE = \"#fd7e14\"\n!$YELLOW = \"#ffce67\"\n!$GREEN = \"#56cc9d\"\n!$TEAL = \"#20c997\"\n!$CYAN = \"#6cc3d5\"\n!$WHITE = \"#fff\"\n!$GRAY = \"#888\"\n!$GRAYDARK = \"#343a40\"\n!$PRIMARY = \"#78c2ad\"\n!$SECONDARY = \"#f3969a\"\n!$SUCCESS = \"#56cc9d\"\n!$INFO = \"#6cc3d5\"\n!$WARNING = \"#ffce67\"\n!$DANGER = \"#ff7851\"\n!$LIGHT = \"#f8f9fa\"\n!$DARK = \"#343a40\"\n\n'' *_DARK = tint (lighter) of the main color of 80%\n''          where TINT is calculated by clr + (255-clr) * tint_factor\n'' *_LIGHT = shade (darker) of the main color of 80%\n''          and SHADE is calculated by clr * (1 - shade_factor)\n''\n!$FGCOLOR = $WHITE\n!$PRIMARY_DARK = \"#6caf9c\"\n!$PRIMARY_LIGHT = \"#86c8b5\"\n!$PRIMARY_TEXT = $WHITE\n!$SECONDARY_DARK = \"#db878b\"\n!$SECONDARY_LIGHT = \"#f4a1a4\"\n!$SECONDARY_TEXT = $WHITE\n!$INFO_DARK = \"#61b0c0\"\n!$INFO_LIGHT = \"#7bc9d9\"\n!$INFO_TEXT = $WHITE\n!$SUCCESS_DARK = \"#4db88d\"\n!$SUCCESS_LIGHT = \"#67d1a7\"\n!$SUCCESS_TEXT = $WHITE\n!$WARNING_DARK = \"#e6b95d\"\n!$WARNING_LIGHT = \"#ffd376\"\n!$WARNING_TEXT = $WHITE\n!$DANGER_DARK = \"#e66c49\"\n!$DANGER_LIGHT = \"#ff8662\"\n!$DANGER_TEXT = $WHITE\n!$DARK_DARK = \"#2f343a\"\n!$DARK_LIGHT = \"#484e53\"\n!$LIGHT_DARK = \"#dfe0e1\"\n!$LIGHT_LIGHT = \"#f9fafb\"\n\n!procedure $success($msg)\n  <font color=$SUCCESS><b>$msg\n!endprocedure\n\n!procedure $failure($msg)\n  <font color=$DANGER><b>$msg\n!endprocedure\n\n!procedure $warning($msg)\n  <font color=$WARNING><b>$msg\n!endprocedure\n\n!procedure $primary_scheme()\n\tFontColor $PRIMARY_TEXT\n\tBorderColor $PRIMARY\n\tBackgroundColor $PRIMARY_LIGHT\n!endprocedure\n''\n'' Style settings\n''\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $PRIMARY_TEXT\n    HyperLinkColor $ORANGE\n    LineColor $PRIMARY_DARK\n    LineThickness 1\n    Margin 10\n    Padding 6\n    Shadowing 0.0\n  }\n  node {\n   Padding 15\n   roundcorner 20\n   BackgroundColor $PRIMARY-$PRIMARY_DARK\n  }\n  caption {\n    LineThickness 0\n  }\n  footer {\n    LineThickness 0\n  }\n  groupHeader {\n    BackgroundColor $SECONDARY\n    FontColor $INFO\n    FontStyle bold\n  }\n  header {\n    LineThickness 0\n  }\n  referenceHeader {\n    BackgroundColor $BGCOLOR\n    FontColor $DARK\n    FontStyle bold\n  }\n  separator {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  title {\n\tFontSize 20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tFontColor $PRIMARY\n\tBorderColor $SECONDARY\n  }\n  nwdiagDiagram {\n\tnetwork {\n\t\t$primary_scheme()    \n\t\tLineColor $PRIMARY\n\t\tLineThickness 1.0\n\t\tFontColor $PRIMARY_DARK\n\t}\n\tserver {\n\t\t$primary_scheme()\n\t}\n\tarrow {\n\t\tFontColor $PRIMARY_DARK\n\t\tLineColor $PRIMARY_DARK\n\t}\n\tgroup {\n\t\tBackGroundColor $LIGHT\n\t\tLineColor $LIGHT_DARK\n\t\tLineThickness 2.0\n\t\tMargin 5\n\t\tPadding 5\n\t}\n  }\n  participant {\n    Margin 5 40\n    Padding 15 20\n  }\n  ganttDiagram {\n\ttask {\n\t\t$primary_scheme()\n\t\tLineColor $PRIMARY\n\t\tMargin 10 2 2 2\n\t\tPadding 6\n\t}\n\tnote {\n\t\tFontColor $INFO_TEXT\n\t\tLineColor $INFO_DARK\n\t\tBackGroundColor $INFO\n\t}\n\tseparator {\n\t\tLineColor $SECONDARY\n\t\tBackGroundColor $SECONDARY-$SECONDARY_DARK\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tmilestone {\n\t\tFontColor $INFO\n\t\tFontSize 16\n\t\tFontStyle italic\n\t\tBackGroundColor $SECONDARY\n\t\tLineColor $SECONDARY_DARK\n\t}\n\ttimeline {\n\t\tBackgroundColor $SECONDARY\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tclosed {\n\t\tBackgroundColor $WARNING_DARK\n\t\tFontColor $WARNING_TEXT\n\t}\n  }\n</style>\n''\n'' Global Default Values\n''\nskinparam defaultFontName       \"Verdana\"\nskinparam defaultFontSize       12\nskinparam dpi                   100\nskinparam shadowing             false\nskinparam roundcorner           8\nskinparam BoxPadding            40\nskinparam ArrowColor            $DARK\nskinparam stereotype {\n    CBackgroundColor $SECONDARY_LIGHT\n    CBorderColor $SECONDARY_DARK\n    ABackgroundColor $SUCCESS_LIGHT\n    ABorderColor $SUCCESS_DARK\n    IBackgroundColor $DANGER_LIGHT\n    IBorderColor $DANGER_DARK\n    EBackgroundColor $WARNING_LIGHT\n    EBorderColor $WARNING_DARK\n    NBackgroundColor $INFO_LIGHT\n    NBorderColor $INFO_DARK\n}\nskinparam title {\n\tFontColor\t                 $PRIMARY_DARK\n\tBorderColor\t                 $SECONDARY_DARK\n\tFontSize\t    \t         20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor              $SECONDARY_LIGHT-$SECONDARY\n}\n\nskinparam legend {\n\tBackgroundColor $SECONDARY\n\tBorderColor $SECONDARY_DARK\n\tFontColor $LIGHT\n}\n\n!startsub swimlane\nskinparam swimlane {\n\tBorderColor $INFO\n\tBorderThickness 2\n\tTitleBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tTitleFontColor $PRIMARY\n}\n!endsub\n\n!startsub activity\n\nskinparam activity {\n\t$primary_scheme()\n\tBarColor $SUCCESS\n\tStartColor $INFO\n\tEndColor $INFO\n\t''\n\tDiamondBackgroundColor $SECONDARY_LIGHT\n  \tDiamondBorderColor $SECONDARY_DARK\n  \tDiamondFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub participant\n\nskinparam participant {\n\t$primary_scheme()\n\tParticipantBorderThickness 2\n}\n!endsub\n\n!startsub actor\n\nskinparam actor {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub arrow\n\nskinparam arrow {\n\tThickness 3\n\tColor $PRIMARY\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub sequence\n\nskinparam sequence {\n\tBorderColor $PRIMARY\n\t' For some reason sequence title font color does not pick up from global\n\tTitleFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n\tStartColor $PRIMARY\n\tEndColor $PRIMARY\n\t''\n\tBoxBackgroundColor $BGCOLOR\n\tBoxBorderColor $DARK\n\tBoxFontColor $DARK\n\t''\n\tDelayFontColor $DARK\n\t''\n\tLifeLineBorderColor $SECONDARY\n\tLifeLineBorderThickness 2\n\tLifeLineBackgroundColor $SECONDARY_DARK\n\t''\n\tGroupBorderColor $DARK\n\tGroupFontColor $DARK\n\tGroupHeaderFontColor $INFO\n\tGroupBackgroundColor $SECONDARY\n\tGroupHeaderBackgroundColor $BGCOLOR\n\t''\n\tDividerBackgroundColor $DARK\n    DividerBorderColor $DARK\n    DividerBorderThickness 2\n    DividerFontColor $LIGHT\n\t''\n\tReferenceBackgroundColor $BGCOLOR\n\tReferenceBorderColor $DARK\n\tReferenceFontColor $DARK\n\tReferenceHeaderFontColor $INFO\n\tReferenceHeaderBackgroundColor $SECONDARY\n\t''\n\tStereotypeFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub partition\n\nskinparam partition {\n\tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n}\n!endsub\n\n!startsub collections\n\nskinparam collections {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub control\n\nskinparam control {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub entity\n\nskinparam entity {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub boundary\n\nskinparam boundary {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub agent\n\nskinparam agent {\n\tBackgroundColor $WARNING\n\tBorderColor $WARNING_LIGHT\n\tFontColor $DARK\n}\n!endsub\n\n!startsub note\n\nskinparam note {\n\tBorderThickness 1\n\tBackgroundColor $INFO\n\tBorderColor $INFO_DARK\n\tFontColor $WHITE\n}\n!endsub\n\n!startsub artifact\n\nskinparam artifact {\n\tBackgroundColor $DARK\n\tBorderColor $DARK_DARK\n\tFontColor $LIGHT\n}\n!endsub\n\n!startsub component\n\nskinparam component {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub interface\n\nskinparam interface {\n\tBackgroundColor  $DANGER_DARK\n\tBorderColor  $DANGER\n\tFontColor $DARK\n}\n!endsub\n\n!startsub storage\n\nskinparam storage {\n\tBackgroundColor $WARNING\n  \tBorderColor $WARNING_DARK\n\tFontColor $WARNING_TEXT\n}\n!endsub\n\n!startsub node\n\nskinparam node {\n\tBackgroundColor  $SECONDARY\n\tBorderColor $LIGHT\n\tFontColor $LIGHT\n}\n!endsub\n\n!startsub cloud\n\nskinparam cloud {\n\tBackgroundColor #F2FCFE-#eeeeee\n\tBorderColor #F2FCFE\n\tFontColor $DARK\n}\n!endsub\n\n!startsub database\n\nskinparam database {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub class\n\nskinparam class {\n\t$primary_scheme()\n\tHeaderBackgroundColor $PRIMARY_LIGHT\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $DARK\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub object\n\nskinparam object {\n\t$primary_scheme()\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub usecase\n\nskinparam usecase {\n\t$primary_scheme()\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub rectangle\n\nskinparam rectangle {\n\t$primary_scheme()\n\tBackgroundColor $SECONDARY_LIGHT\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub package\n\nskinparam package {\n\tBackgroundColor $SECONDARY\n  \tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBorderThickness 2\n}\n!endsub\n\n!startsub folder\n\nskinparam folder {\n\tBackgroundColor $SECONDARY_LIGHT\n  \tBorderColor $WARNING\n\tFontColor $WARNING\n\tBorderThickness 2\n}\n!endsub\n\n!startsub frame\n\nskinparam frame {\n\tBackgroundColor $SECONDARY_LIGHT\n  \tBorderColor $INFO\n\tFontColor $INFO\n\tBorderThickness 2\n}\n!endsub\n\n!startsub state\n\nskinparam state {\n\t$primary_scheme()\n\tStartColor $INFO\n\tEndColor $INFO\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub queue\n\nskinparam queue {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub card\n\nskinparam card {\n\tBackgroundColor $INFO\n\tBorderColor $INFO_DARK\n\tFontColor $INFO_TEXT\n}\n!endsub\n\n!startsub file\n\nskinparam file {\n\tBackgroundColor $SECONDARY_DARK\n\tBorderColor $LIGHT\n\tFontColor $LIGHT\n}\n!endsub\n\n!startsub stack\n\nskinparam stack {\n\t$primary_scheme()\n}\n!endsub\n";
g.PLANTUML_THEMES["mono"]="---\nname: mono\ndisplay_name: Mono\ndescription: A mostly monochrome theme with monospaced font, that adds more structure and tidiness with better shapes control, brought by monospaced font\nauthor: Denis Bondarenko feat Matthew Leather\nrelease: \nlicense: \nversion: \nsource: \ninspiration: \n---\n\n!$THEME = \"mono\"\n\n' Theme colors\n\n!if %not(%variable_exists(\"$CLR_BG\"))\n  !$CLR_BG = \"white\"\n!endif\n\n' For icons bg in legend. usage: <THM_BG>\n!ifndef THM_BG\n  !define THM_BG #$CLR_BG\n!endif\n\n' Highlighted background\n!if %not(%variable_exists(\"$CLR_BG_EMPH\"))\n  !$CLR_BG_EMPH = \"#eee\"\n!endif\n\n' Main foreground color\n!if %not(%variable_exists(\"$CLR_FG\"))\n  !$CLR_FG = \"black\"\n!endif\n\n' Less hued, 3 levels\n\n!if %not(%variable_exists(\"$CLR_FG_DIMMED\"))\n  !$CLR_FG_DIMMED = \"#666\"\n!endif\n\n!if %not(%variable_exists(\"$CLR_FG_DIMMED_2\"))\n  !$CLR_FG_DIMMED_2 = \"#999\"\n!endif\n\n!if %not(%variable_exists(\"$CLR_FG_DIMMED_3\"))\n  !$CLR_FG_DIMMED_3 = \"#ccc\"\n!endif\n\n' Hyperlinks color\n!if %not(%variable_exists(\"$CLR_HYPERLINK\"))\n  !$CLR_HYPERLINK = \"#333\"\n!endif\n\n' Theme fonts\n\n' Basic font\n!ifndef $FNT\n\n' Multiple fallback fonts defined\n  !$FNT_MONO = \"Courier\"\n  !$FNT_MONO = \"Courier New\"\n  !$FNT = \"DejaVu Sans Mono\"\n  !$FNT = \"monospace\"\n  !$FNT = \"Rec Mono Linear\"\n\n' The preferred theme font\n  !$FNT = \"Hack\"\n\n!endif\n\n' Monospaced font\n!ifndef $FNT_MONO\n\n' A different font can be used\n' !$FNT_MONO = \"Rec Mono Semicasual\"\n  !$FNT_MONO = $FNT\n!endif\n\n' Theme body\n\n<style>\n  root {\n    BackgroundColor $CLR_BG\n    FontColor $CLR_FG\n    FontName $FNT\n    HyperLinkColor $CLR_HYPERLINK\n    LineColor $CLR_FG\n    LineThickness 1\n    Margin 5\n  }\n  document {\n    caption {\n      LineThickness 0\n    }\n    footer {\n      LineThickness 0\n    }\n    header {\n      LineThickness 0\n    }\n    title {\n      FontSize 22\n      LineThickness 0\n    }\n  }\n  node {\n'    MaximumWidth 300\n  }\n  ganttDiagram {\n    closed {\n      BackGroundColor $CLR_BG_EMPH\n    }\n    task {\n      BackGroundColor $CLR_FG_DIMMED_2\n      LineColor $CLR_FG\n      unstarted {\n        BackGroundColor $CLR_FG_DIMMED_3\n        LineColor $CLR_FG\n      }\n    }\n    note {\n      LineThickness .5\n    }\n    timeline {\n      LineThickness .5\n      LineColor $CLR_FG_DIMMED_3\n    }\n    separator {\n    }\n  }\n</style>\n\n' skinparam is flattened to support YAML, JSON diagram types\nskinparam {\n\n  shadowing false\n  useBetaStyle true\n  arrowLollipopColor $CLR_FG\n  backgroundColor $CLR_BG\n  lifelineStrategy nosolid\n\n  defaultFontName $FNT\n  defaultMonospacedFontName $FNT_MONO\n\n  hyperlinkColor $CLR_HYPERLINK\n\n  headerFontColor $CLR_FG_DIMMED_2\n  headerFontName $FNT\n\n  footerFontColor $CLR_FG_DIMMED_2\n  footerFontName $FNT\n\n  legendBorderThickness 0\n  legendBorderColor transparent\n\n  noteFontColor $CLR_FG\n  noteFontName $FNT\n\n  packageBorderColor $CLR_FG\n  packageFontColor $CLR_FG\n  packageFontName $FNT\n\n  nodeStereotypeFontColor $CLR_FG_DIMMED\n  nodeStereotypeFontName $FNT\n  nodeStereotypeFontSize 10\n\n  componentStereotypeFontColor $CLR_FG_DIMMED\n  componentStereotypeFontName $FNT\n  componentStereotypeFontSize 10\n\n  participantPadding 10\n\n  actorStereotypeFontColor $CLR_FG_DIMMED\n  actorStereotypeFontName $FNT\n  actorStereotypeFontSize 10\n\n  useCaseStereoTypeFontColor $CLR_FG\n  useCaseStereoTypeFontName $FNT\n\n  classBackgroundColor $CLR_BG\n  classBorderColor $CLR_FG\n  classFontColor $CLR_FG\n  classFontName $FNT\n  classAttributeFontColor $CLR_FG\n  classAttributeFontName $FNT\n  classStereotypeFontColor $CLR_FG_DIMMED\n  classStereotypeFontName $FNT\n  classStereotypeFontSize 10\n\n  objectBorderColor $CLR_FG\n\n  activityBackgroundColor $CLR_BG\n  activityBarColor $CLR_FG\n  activityBorderColor $CLR_FG\n  activityFontColor $CLR_FG\n  activityFontName $FNT\n\n  sequenceLifeLineBorderColor $CLR_FG\n\n  stateBackgroundColor $CLR_BG\n  stateBorderColor $CLR_FG\n\n  boundaryFontColor $CLR_FG\n\n  boxPadding 5\n\n  circledCharacterFontColor $CLR_FG\n  circledCharacterFontName $FNT_MONO\n  circledCharacterFontSize 10\n  circledCharacterRadius 8\n\n  stereotypeFontColor $CLR_FG_DIMMED\n  stereotypeFontName $FNT\n  stereotypeFontSize 10\n  stereotypeABackgroundColor $CLR_BG\n  stereotypeABorderColor $CLR_FG\n  stereotypeCBackgroundColor $CLR_BG\n  stereotypeCBorderColor $CLR_FG\n  stereotypeEBackgroundColor $CLR_BG\n  stereotypeEBorderColor $CLR_FG\n  stereotypeIBackgroundColor $CLR_BG\n  stereotypeIBorderColor $CLR_FG\n  stereotypeNBackgroundColor $CLR_BG\n  stereotypeNBorderColor $CLR_FG\n\n  iconPackageColor $CLR_FG\n  iconPackageBackgroundColor $CLR_BG\n  iconPrivateColor $CLR_FG\n  iconPrivateBackgroundColor $CLR_BG\n  iconProtectedColor $CLR_FG\n  iconProtectedBackgroundColor $CLR_BG\n  iconPublicColor $CLR_FG\n  iconPublicBackgroundColor $CLR_BG\n\n}\n";
g.PLANTUML_THEMES["plain"]="---\nname: plain \ndisplay_name: Plain\ndescription: A simple black on white theme (with blue hyperlinks)\nauthor: Matthew Leather\nrelease: \nlicense: \nversion: \nsource: \ninspiration: \n---\n\n!$THEME = \"plain\"\n\n!if %not(%variable_exists(\"$BGCOLOR\"))\n  !$BGCOLOR = \"white\"\n!endif\n\n!if %not(%variable_exists(\"$FGCOLOR\"))\n  !$FGCOLOR = \"black\"\n!endif\n\n!if %not(%variable_exists(\"$HYPERLINK_COLOR\"))\n  !$HYPERLINK_COLOR = \"blue\"\n!endif\n\n!ifndef $FONT_NAME\n  !$FONT_NAME = \"Verdana\"\n!endif\n\n!ifndef $FONT_NAME_MONOSPACED\n  !$FONT_NAME_MONOSPACED = \"Courier\"\n!endif\n\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $FGCOLOR\n    FontName $FONT_NAME\n    HyperLinkColor $HYPERLINK_COLOR\n    LineColor $FGCOLOR\n    LineThickness 1\n    Margin 5\n  }\n  document {\n    caption {\n      LineThickness 0\n    }\n    footer {\n      LineThickness 0\n    }\n    header {\n      LineThickness 0\n    }\n    title {\n      FontSize 22\n      LineThickness 0\n    }\n  }\n  node {\n    MaximumWidth 300\n  }\n  participant {\n    Margin 5 10\n    Padding 5 5\n  }\n</style>\n\nskinparam ArrowLollipopColor $FGCOLOR\nskinparam BackgroundColor $BGCOLOR\nskinparam DefaultFontName $FONT_NAME\nskinparam DefaultMonospacedFontName $FONT_NAME_MONOSPACED\nskinparam LifelineStrategy nosolid\nskinparam SequenceLifeLineBorderColor $FGCOLOR\nskinparam Shadowing false\nskinparam UseBetaStyle true\n\nskinparam Activity {\n  BackgroundColor $BGCOLOR\n  BarColor $FGCOLOR\n  BorderColor $FGCOLOR\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Boundary {\n  FontColor $FGCOLOR\n}\nskinparam Box {\n  Padding 5\n}\nskinparam CircledCharacter {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME_MONOSPACED\n  Radius 9\n}\nskinparam Class {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam ClassAttribute {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam ClassStereotype {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Footer {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Header {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Hyperlink {\n  Color $HYPERLINK_COLOR\n}\nskinparam IconPackage {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam IconPrivate {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam IconProtected {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam IconPublic {\n  Color $FGCOLOR\n  BackgroundColor $BGCOLOR\n}\nskinparam Note {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam Object {\n  BorderColor $FGCOLOR\n}\nskinparam Package {\n  BorderColor $FGCOLOR\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\nskinparam State {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeA {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeC {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeE {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeI {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam StereotypeN {\n  BackgroundColor $BGCOLOR\n  BorderColor $FGCOLOR\n}\nskinparam UseCaseStereoType {\n  FontColor $FGCOLOR\n  FontName $FONT_NAME\n}\n";
g.PLANTUML_THEMES["reddress-darkblue"]="---\nname: reddress-darkblue\ndisplay_name: Reddress Darkblue \ndescription: A dark blue style from \"Red Dress\"\nauthor: [Drakemor](https://github.com/Drakemor)\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/Drakemor/RedDress-PlantUML\ninspiration: \n---\n\n!if (%not(%variable_exists(\"$FONTNAME\")))\n!$FONTNAME = \"Verdana\"\n!endif\n\n!if (%not(%variable_exists(\"$FONTSIZE\")))\n!$FONTSIZE = 11\n!endif\n\nskinparam backgroundColor 777\n!$ACCENT = \"1a66c2\"\n!$ACCENTDARK = \"002642\"\nskinparam stereotypeCBackgroundColor $ACCENT\n!$PRIMARYFONTCOLOR = \"fff\"\n!$SECONDARY = \"aaa\"\n!$ARROWCOLOR = \"fff\"\n!$ARROWFONTCOLOR = \"bbb\"\n!$BORDERCOLOR = \"1b1b1b\"\n!$BOXBG = \"2e2e2e\"\n!$LIGHTBORDERCOLOR = \"767676\"\n!$LIGHTBG = \"575757\"\nskinparam backgroundColor 777\n\n!procedure font_style()\n  fontColor $PRIMARYFONTCOLOR\n  fontName $FONTNAME\n  fontSize $FONTSIZE\n  stereotypeFontColor $SECONDARY\n  stereotypeFontSize $FONTSIZE\n!endprocedure\n\n!procedure basic_style()\n  backgroundColor $BOXBG\n  borderColor $BORDERCOLOR\n!endprocedure\n\n!procedure light_style()\n  backgroundColor $LIGHTBG\n  borderColor $LIGHTBORDERCOLOR\n!endprocedure\n\n!procedure accent_style()\n  backgroundColor $ACCENT\n  borderColor $ACCENTDARK\n!endprocedure\n\n!procedure arrow_style()\n  arrowColor $ARROWCOLOR\n  arrowFontName $FONTNAME\n  arrowFontColor $ARROWFONTCOLOR\n  arrowFontSize $FONTSIZE\n!endprocedure\n\n' Class diagrams\n\nskinparam circledCharacter {\n  radius 8\n  fontSize $FONTSIZE\n  fontName $FONTNAME\n}\n\nskinparam class {\n  basic_style()\n  font_style()\n  arrow_style()\n\n  attributeFontColor $SECONDARY\n  attributeFontSize $FONTSIZE\n  attributeIconSize $FONTSIZE\n}\n\n' Sequence diagrams\n\nskinparam actor {\n  accent_style()\n  font_style()\n}\n\nskinparam participant {\n  basic_style()\n  font_style()\n}\n\nskinparam collections {\n  basic_style()\n  font_style()\n}\n\nskinparam SequenceBox{\n  light_style()\n  font_style()\n}\n\n' Component diagrams\n\nskinparam interface {\n  accent_style()\n  font_style()\n}\n\nskinparam component {\n  basic_style()\n  font_style()\n}\n\nskinparam node {\n  basic_style()\n  font_style()\n}\n\nskinparam database {\n  basic_style()\n  font_style()\n}\n\nskinparam queue {\n  basic_style()\n  font_style()\n}\n\n' Use Case diagrams\n\nskinparam usecase {\n  basic_style()\n  font_style()\n  arrow_style()\n}\n\nskinparam activity {\n  basic_style()\n  font_style()\n  arrow_style()\n}\n\nskinparam sequence {\n  font_style()\n  arrow_style()\n\n  lifeLineBorderColor $ACCENT\n  lifeLineBackgroundColor $LIGHTBG\n}\n\nskinparam boundary {\n  accent_style()\n  font_style()\n}\n\nskinparam control {\n  accent_style()\n  font_style()\n}\n\nskinparam entity {\n  accent_style()\n  font_style()\n}\n\n' State diagrams\n\nskinparam state {\n  basic_style()\n  font_style()\n  arrow_style()\n  startColor $ACCENT\n  endColor $ACCENTDARK\n}\n\n' Object diagrams\n\nskinparam object {\n  basic_style()\n  font_style()\n  arrow_style()\n}\n\n' Common\n\nskinparam note {\n  accent_style()\n  font_style()\n}\n\nskinparam cloud {\n  basic_style()\n  font_style()\n  arrow_style()\n}\n\nskinparam rectangle {\n  basic_style()\n  font_style()\n}\n\nskinparam storage {\n  basic_style()\n  font_style()\n}";
