g.PLANTUML_THEMES["reddress-lightblue"]="---\nname: reddress-lightblue\ndisplay_name: Reddress Lightblue\ndescription: A light blue style from \"Red Dress\"\nauthor: [Drakemor](https://github.com/Drakemor)\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/Drakemor/RedDress-PlantUML\ninspiration: \n---\n\n!if (%not(%variable_exists(\"$FONTNAME\")))\n!$FONTNAME = \"Verdana\"\n!endif\n\n!if (%not(%variable_exists(\"$FONTSIZE\")))\n!$FONTSIZE = 11\n!endif\n\n!$ACCENT = \"2a86e2\"\n!$ACCENTDARK = \"1a66c2\"\nskinparam stereotypeCBackgroundColor $ACCENTDARK\n!$PRIMARYFONTCOLOR = \"000\"\n!$SECONDARY = \"333\"\n!$ARROWCOLOR = \"000\"\n!$ARROWFONTCOLOR = \"333\"\n!$BORDERCOLOR = \"aaa\"\n!$BOXBG = \"ccc\"\n!$LIGHTBORDERCOLOR = \"cccccc\"\n!$LIGHTBG = \"e0e0e0\"\nskinparam backgroundColor fff\n\n!procedure font_style()\n  fontColor $PRIMARYFONTCOLOR\n  fontName $FONTNAME\n  fontSize $FONTSIZE\n  stereotypeFontColor $SECONDARY\n  stereotypeFontSize $FONTSIZE\n!endprocedure\n\n!procedure basic_style()\n  backgroundColor $BOXBG\n  borderColor $BORDERCOLOR\n!endprocedure\n\n!procedure light_style()\n  backgroundColor $LIGHTBG\n  borderColor $LIGHTBORDERCOLOR\n!endprocedure\n\n!procedure accent_style()\n  backgroundColor $ACCENT\n  borderColor $ACCENTDARK\n!endprocedure\n\n!procedure arrow_style()\n  arrowColor $ARROWCOLOR\n  arrowFontName $FONTNAME\n  arrowFontColor $ARROWFONTCOLOR\n  arrowFontSize $FONTSIZE\n!endprocedure\n\n' Class diagrams\n\nskinparam circledCharacter {\n  radius 8\n  fontSize $FONTSIZE\n  fontName $FONTNAME\n}\n\nskinparam class {\n  basic_style()\n  font_style()\n  arrow_style()\n\n  attributeFontColor $SECONDARY\n  attributeFontSize $FONTSIZE\n  attributeIconSize $FONTSIZE\n}\n\n' Sequence diagrams\n\nskinparam actor {\n  accent_style()\n  font_style()\n}\n\nskinparam participant {\n  basic_style()\n  font_style()\n}\n\nskinparam collections {\n  basic_style()\n  font_style()\n}\n\nskinparam SequenceBox{\n  light_style()\n  font_style()\n}\n\n' Component diagrams\n\nskinparam interface {\n  accent_style()\n  font_style()\n}\n\nskinparam component {\n  basic_style()\n  font_style()\n}\n\nskinparam node {\n  basic_style()\n  font_style()\n}\n\nskinparam database {\n  basic_style()\n  font_style()\n}\n\nskinparam queue {\n  basic_style()\n  font_style()\n}\n\n' Use Case diagrams\n\nskinparam usecase {\n  basic_style()\n  font_style()\n  arrow_style()\n}\n\nskinparam activity {\n  basic_style()\n  font_style()\n  arrow_style()\n}\n\nskinparam sequence {\n  font_style()\n  arrow_style()\n\n  lifeLineBorderColor $ACCENT\n  lifeLineBackgroundColor $LIGHTBG\n}\n\nskinparam boundary {\n  accent_style()\n  font_style()\n}\n\nskinparam control {\n  accent_style()\n  font_style()\n}\n\nskinparam entity {\n  accent_style()\n  font_style()\n}\n\n' State diagrams\n\nskinparam state {\n  basic_style()\n  font_style()\n  arrow_style()\n  startColor $ACCENT\n  endColor $ACCENTDARK\n}\n\n' Object diagrams\n\nskinparam object {\n  basic_style()\n  font_style()\n  arrow_style()\n}\n\n' Common\n\nskinparam note {\n  accent_style()\n  font_style()\n}\n\nskinparam cloud {\n  basic_style()\n  font_style()\n  arrow_style()\n}\n\nskinparam rectangle {\n  basic_style()\n  font_style()\n}\n\nskinparam storage {\n  basic_style()\n  font_style()\n}\n";
g.PLANTUML_THEMES["reddress-lightgreen"]="---\nname: reddress-lightgreen\ndisplay_name: Reddress Lightgreen\ndescription: A light green style from \"Red Dress\"\nauthor: [Drakemor](https://github.com/Drakemor)\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/Drakemor/RedDress-PlantUML\ninspiration: \n---\n\n!if (%not(%variable_exists(\"$FONTNAME\")))\n!$FONTNAME = \"Verdana\"\n!endif\n\n!if (%not(%variable_exists(\"$FONTSIZE\")))\n!$FONTSIZE = 11\n!endif\n\n!$ACCENT = \"55BB33\"\n!$ACCENTDARK = \"338822\"\nskinparam stereotypeCBackgroundColor $ACCENTDARK\n!$PRIMARYFONTCOLOR = \"000\"\n!$SECONDARY = \"333\"\n!$ARROWCOLOR = \"000\"\n!$ARROWFONTCOLOR = \"333\"\n!$BORDERCOLOR = \"aaa\"\n!$BOXBG = \"ccc\"\n!$LIGHTBORDERCOLOR = \"cccccc\"\n!$LIGHTBG = \"e0e0e0\"\nskinparam backgroundColor fff\n\n!procedure font_style()\n  fontColor $PRIMARYFONTCOLOR\n  fontName $FONTNAME\n  fontSize $FONTSIZE\n  stereotypeFontColor $SECONDARY\n  stereotypeFontSize $FONTSIZE\n!endprocedure\n\n!procedure basic_style()\n  backgroundColor $BOXBG\n  borderColor $BORDERCOLOR\n!endprocedure\n\n!procedure light_style()\n  backgroundColor $LIGHTBG\n  borderColor $LIGHTBORDERCOLOR\n!endprocedure\n\n!procedure accent_style()\n  backgroundColor $ACCENT\n  borderColor $ACCENTDARK\n!endprocedure\n\n!procedure arrow_style()\n  arrowColor $ARROWCOLOR\n  arrowFontName $FONTNAME\n  arrowFontColor $ARROWFONTCOLOR\n  arrowFontSize $FONTSIZE\n!endprocedure\n\n' Class diagrams\n\nskinparam circledCharacter {\n  radius 8\n  fontSize $FONTSIZE\n  fontName $FONTNAME\n}\n\nskinparam class {\n  basic_style()\n  font_style()\n  arrow_style()\n\n  attributeFontColor $SECONDARY\n  attributeFontSize $FONTSIZE\n  attributeIconSize $FONTSIZE\n}\n\n' Sequence diagrams\n\nskinparam actor {\n  accent_style()\n  font_style()\n}\n\nskinparam participant {\n  basic_style()\n  font_style()\n}\n\nskinparam collections {\n  basic_style()\n  font_style()\n}\n\nskinparam SequenceBox{\n  light_style()\n  font_style()\n}\n\n' Component diagrams\n\nskinparam interface {\n  accent_style()\n  font_style()\n}\n\nskinparam component {\n  basic_style()\n  font_style()\n}\n\nskinparam node {\n  basic_style()\n  font_style()\n}\n\nskinparam database {\n  basic_style()\n  font_style()\n}\n\nskinparam queue {\n  basic_style()\n  font_style()\n}\n\n' Use Case diagrams\n\nskinparam usecase {\n  basic_style()\n  font_style()\n  arrow_style()\n}\n\nskinparam activity {\n  basic_style()\n  font_style()\n  arrow_style()\n}\n\nskinparam sequence {\n  font_style()\n  arrow_style()\n\n  lifeLineBorderColor $ACCENT\n  lifeLineBackgroundColor $LIGHTBG\n}\n\nskinparam boundary {\n  accent_style()\n  font_style()\n}\n\nskinparam control {\n  accent_style()\n  font_style()\n}\n\nskinparam entity {\n  accent_style()\n  font_style()\n}\n\n' State diagrams\n\nskinparam state {\n  basic_style()\n  font_style()\n  arrow_style()\n  startColor $ACCENT\n  endColor $ACCENTDARK\n}\n\n' Object diagrams\n\nskinparam object {\n  basic_style()\n  font_style()\n  arrow_style()\n}\n\n' Common\n\nskinparam note {\n  accent_style()\n  font_style()\n}\n\nskinparam cloud {\n  basic_style()\n  font_style()\n  arrow_style()\n}\n\nskinparam rectangle {\n  basic_style()\n  font_style()\n}\n\nskinparam storage {\n  basic_style()\n  font_style()\n}\n";
g.PLANTUML_THEMES["reddress-lightorange"]="---\nname: reddress-lightorange\ndisplay_name: Reddress Lightorange\ndescription: A light orange style from \"Red Dress\"\nauthor: [Drakemor](https://github.com/Drakemor)\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/Drakemor/RedDress-PlantUML\ninspiration: \n---\n\n!if (%not(%variable_exists(\"$FONTNAME\")))\n!$FONTNAME = \"Verdana\"\n!endif\n\n!if (%not(%variable_exists(\"$FONTSIZE\")))\n!$FONTSIZE = 11\n!endif\n\n!$ACCENT = \"FF8800\"\n!$ACCENTDARK = \"BB6600\"\nskinparam stereotypeCBackgroundColor $ACCENT\n!$PRIMARYFONTCOLOR = \"000\"\n!$SECONDARY = \"333\"\n!$ARROWCOLOR = \"000\"\n!$ARROWFONTCOLOR = \"333\"\n!$BORDERCOLOR = \"aaa\"\n!$BOXBG = \"ccc\"\n!$LIGHTBORDERCOLOR = \"cccccc\"\n!$LIGHTBG = \"e0e0e0\"\nskinparam backgroundColor fff\n\n!procedure font_style()\n  fontColor $PRIMARYFONTCOLOR\n  fontName $FONTNAME\n  fontSize $FONTSIZE\n  stereotypeFontColor $SECONDARY\n  stereotypeFontSize $FONTSIZE\n!endprocedure\n\n!procedure basic_style()\n  backgroundColor $BOXBG\n  borderColor $BORDERCOLOR\n!endprocedure\n\n!procedure light_style()\n  backgroundColor $LIGHTBG\n  borderColor $LIGHTBORDERCOLOR\n!endprocedure\n\n!procedure accent_style()\n  backgroundColor $ACCENT\n  borderColor $ACCENTDARK\n!endprocedure\n\n!procedure arrow_style()\n  arrowColor $ARROWCOLOR\n  arrowFontName $FONTNAME\n  arrowFontColor $ARROWFONTCOLOR\n  arrowFontSize $FONTSIZE\n!endprocedure\n\n' Class diagrams\n\nskinparam circledCharacter {\n  radius 8\n  fontSize $FONTSIZE\n  fontName $FONTNAME\n}\n\nskinparam class {\n  basic_style()\n  font_style()\n  arrow_style()\n\n  attributeFontColor $SECONDARY\n  attributeFontSize $FONTSIZE\n  attributeIconSize $FONTSIZE\n}\n\n' Sequence diagrams\n\nskinparam actor {\n  accent_style()\n  font_style()\n}\n\nskinparam participant {\n  basic_style()\n  font_style()\n}\n\nskinparam collections {\n  basic_style()\n  font_style()\n}\n\nskinparam SequenceBox{\n  light_style()\n  font_style()\n}\n\n' Component diagrams\n\nskinparam interface {\n  accent_style()\n  font_style()\n}\n\nskinparam component {\n  basic_style()\n  font_style()\n}\n\nskinparam node {\n  basic_style()\n  font_style()\n}\n\nskinparam database {\n  basic_style()\n  font_style()\n}\n\nskinparam queue {\n  basic_style()\n  font_style()\n}\n\n' Use Case diagrams\n\nskinparam usecase {\n  basic_style()\n  font_style()\n  arrow_style()\n}\n\nskinparam activity {\n  basic_style()\n  font_style()\n  arrow_style()\n}\n\nskinparam sequence {\n  font_style()\n  arrow_style()\n\n  lifeLineBorderColor $ACCENT\n  lifeLineBackgroundColor $LIGHTBG\n}\n\nskinparam boundary {\n  accent_style()\n  font_style()\n}\n\nskinparam control {\n  accent_style()\n  font_style()\n}\n\nskinparam entity {\n  accent_style()\n  font_style()\n}\n\n' State diagrams\n\nskinparam state {\n  basic_style()\n  font_style()\n  arrow_style()\n  startColor $ACCENT\n  endColor $ACCENTDARK\n}\n\n' Object diagrams\n\nskinparam object {\n  basic_style()\n  font_style()\n  arrow_style()\n}\n\n' Common\n\nskinparam note {\n  accent_style()\n  font_style()\n}\n\nskinparam cloud {\n  basic_style()\n  font_style()\n  arrow_style()\n}\n\nskinparam rectangle {\n  basic_style()\n  font_style()\n}\n\nskinparam storage {\n  basic_style()\n  font_style()\n}\n";
g.PLANTUML_THEMES["reddress-lightred"]="---\nname: reddress-lightred\ndisplay_name: Reddress Lightred\ndescription: A light red style from \"Red Dress\"\nauthor: [Drakemor](https://github.com/Drakemor)\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/Drakemor/RedDress-PlantUML\ninspiration: \n---\n\n!if (%not(%variable_exists(\"$FONTNAME\")))\n!$FONTNAME = \"Verdana\"\n!endif\n\n!if (%not(%variable_exists(\"$FONTSIZE\")))\n!$FONTSIZE = 11\n!endif\n\n!$ACCENT = \"CC0033\"\n!$ACCENTDARK = \"AA0033\"\nskinparam stereotypeCBackgroundColor $ACCENTDARK\n!$PRIMARYFONTCOLOR = \"000\"\n!$SECONDARY = \"333\"\n!$ARROWCOLOR = \"000\"\n!$ARROWFONTCOLOR = \"333\"\n!$BORDERCOLOR = \"aaa\"\n!$BOXBG = \"ccc\"\n!$LIGHTBORDERCOLOR = \"cccccc\"\n!$LIGHTBG = \"e0e0e0\"\nskinparam backgroundColor fff\n\n!procedure font_style()\n  fontColor $PRIMARYFONTCOLOR\n  fontName $FONTNAME\n  fontSize $FONTSIZE\n  stereotypeFontColor $SECONDARY\n  stereotypeFontSize $FONTSIZE\n!endprocedure\n\n!procedure basic_style()\n  backgroundColor $BOXBG\n  borderColor $BORDERCOLOR\n!endprocedure\n\n!procedure light_style()\n  backgroundColor $LIGHTBG\n  borderColor $LIGHTBORDERCOLOR\n!endprocedure\n\n!procedure accent_style()\n  backgroundColor $ACCENT\n  borderColor $ACCENTDARK\n!endprocedure\n\n!procedure arrow_style()\n  arrowColor $ARROWCOLOR\n  arrowFontName $FONTNAME\n  arrowFontColor $ARROWFONTCOLOR\n  arrowFontSize $FONTSIZE\n!endprocedure\n\n' Class diagrams\n\nskinparam circledCharacter {\n  radius 8\n  fontSize $FONTSIZE\n  fontName $FONTNAME\n}\n\nskinparam class {\n  basic_style()\n  font_style()\n  arrow_style()\n\n  attributeFontColor $SECONDARY\n  attributeFontSize $FONTSIZE\n  attributeIconSize $FONTSIZE\n}\n\n' Sequence diagrams\n\nskinparam actor {\n  accent_style()\n  font_style()\n}\n\nskinparam participant {\n  basic_style()\n  font_style()\n}\n\nskinparam collections {\n  basic_style()\n  font_style()\n}\n\nskinparam SequenceBox{\n  light_style()\n  font_style()\n}\n\n' Component diagrams\n\nskinparam interface {\n  accent_style()\n  font_style()\n}\n\nskinparam component {\n  basic_style()\n  font_style()\n}\n\nskinparam node {\n  basic_style()\n  font_style()\n}\n\nskinparam database {\n  basic_style()\n  font_style()\n}\n\nskinparam queue {\n  basic_style()\n  font_style()\n}\n\n' Use Case diagrams\n\nskinparam usecase {\n  basic_style()\n  font_style()\n  arrow_style()\n}\n\nskinparam activity {\n  basic_style()\n  font_style()\n  arrow_style()\n}\n\nskinparam sequence {\n  font_style()\n  arrow_style()\n\n  lifeLineBorderColor $ACCENT\n  lifeLineBackgroundColor $LIGHTBG\n}\n\nskinparam boundary {\n  accent_style()\n  font_style()\n}\n\nskinparam control {\n  accent_style()\n  font_style()\n}\n\nskinparam entity {\n  accent_style()\n  font_style()\n}\n\n' State diagrams\n\nskinparam state {\n  basic_style()\n  font_style()\n  arrow_style()\n  startColor $ACCENT\n  endColor $ACCENTDARK\n}\n\n' Object diagrams\n\nskinparam object {\n  basic_style()\n  font_style()\n  arrow_style()\n}\n\n' Common\n\nskinparam note {\n  accent_style()\n  font_style()\n}\n\nskinparam cloud {\n  basic_style()\n  font_style()\n  arrow_style()\n}\n\nskinparam rectangle {\n  basic_style()\n  font_style()\n}\n\nskinparam storage {\n  basic_style()\n  font_style()\n}\n";
g.PLANTUML_THEMES["sandstone"]="---\nname: sandstone\ndisplay_name: Sandstone\ndescription: Theme based off of the bootstrap theme of the same name\nauthor: Brett Schwarz\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/bschwarz/puml-themes\ninspiration: https://bootswatch.com/sandstone/\n---\n\n!$THEME = \"sandstone\"\n\n!if %not(%variable_exists(\"$BGCOLOR\"))\n!$BGCOLOR = \"transparent\"\n!endif\n\nskinparam backgroundColor $BGCOLOR\nskinparam useBetaStyle false\n\n''\n'' Colors taken from the css file of the BS theme\n''\n!$BLUE = \"#325d88\"\n!$INDIGO = \"#6610f2\"\n!$PURPLE = \"#6f42c1\"\n!$PINK = \"#e83e8c\"\n!$RED = \"#d9534f\"\n!$ORANGE = \"#f47c3c\"\n!$YELLOW = \"#ffc107\"\n!$GREEN = \"#93c54b\"\n!$TEAL = \"#20c997\"\n!$CYAN = \"#29abe0\"\n!$WHITE = \"#fff\"\n!$GRAY = \"#8e8c84\"\n!$GRAYDARK = \"#3e3f3a\"\n!$PRIMARY = \"#325d88\"\n!$SECONDARY = \"#8e8c84\"\n!$SUCCESS = \"#93c54b\"\n!$INFO = \"#29abe0\"\n!$WARNING = \"#f47c3c\"\n!$DANGER = \"#d9534f\"\n!$LIGHT = \"#f8f5f0\"\n!$DARK = \"#3e3f3a\"\n\n'' *_DARK = tint (lighter) of the main color of 80%\n''          where TINT is calculated by clr + (255-clr) * tint_factor\n'' *_LIGHT = shade (darker) of the main color of 80%\n''          and SHADE is calculated by clr * (1 - shade_factor)\n''\n!$FGCOLOR = $WHITE\n!$PRIMARY_DARK = \"#2d547a\"\n!$PRIMARY_LIGHT = \"#476d94\"\n!$PRIMARY_TEXT = $WHITE\n!$SECONDARY_DARK = \"#807e77\"\n!$SECONDARY_LIGHT = \"#999890\"\n!$SECONDARY_TEXT = $WHITE\n!$INFO_DARK = \"#259aca\"\n!$INFO_LIGHT = \"#3eb3e3\"\n!$INFO_TEXT = $WHITE\n!$SUCCESS_DARK = \"#84b144\"\n!$SUCCESS_LIGHT = \"#9ecb5d\"\n!$SUCCESS_TEXT = $WHITE\n!$WARNING_DARK = \"#dc7036\"\n!$WARNING_LIGHT = \"#f58950\"\n!$WARNING_TEXT = $WHITE\n!$DANGER_DARK = \"#c34b47\"\n!$DANGER_LIGHT = \"#AE423F\"\n!$DANGER_TEXT = $WHITE\n!$DARK_DARK = \"#383934\"\n!$DARK_LIGHT = \"#51524e\"\n!$LIGHT_DARK = \"#dfddd8\"\n!$LIGHT_LIGHT = \"#f9f6f2\"\n\n!procedure $success($msg)\n  <font color=$SUCCESS><b>$msg\n!endprocedure\n\n!procedure $failure($msg)\n  <font color=$DANGER><b>$msg\n!endprocedure\n\n!procedure $warning($msg)\n  <font color=$WARNING><b>$msg\n!endprocedure\n\n!procedure $primary_scheme()\n\tFontColor $PRIMARY_TEXT\n\tBorderColor $PRIMARY_DARK\n\tBackgroundColor $PRIMARY\n!endprocedure\n''\n'' Style settings\n''\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $PRIMARY_TEXT\n    HyperLinkColor $ORANGE\n    LineColor $PRIMARY_DARK\n    LineThickness 1\n    Margin 10\n    Padding 6\n    Shadowing 0.0\n  }\n  node {\n   Padding 15\n   roundcorner 20\n   BackgroundColor $PRIMARY-$PRIMARY_DARK\n  }\n  caption {\n    LineThickness 0\n  }\n  footer {\n    LineThickness 0\n  }\n  groupHeader {\n    BackgroundColor $SECONDARY\n    FontColor $INFO\n    FontStyle bold\n  }\n  header {\n    LineThickness 0\n  }\n  referenceHeader {\n    BackgroundColor $BGCOLOR\n    FontColor $DARK\n    FontStyle bold\n  }\n  separator {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  title {\n\tFontSize 20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tFontColor $PRIMARY\n\tBorderColor $SECONDARY\n  }\n  nwdiagDiagram {\n\tnetwork {\n\t\t$primary_scheme()    \n\t\tLineColor $PRIMARY\n\t\tLineThickness 1.0\n\t\tFontColor $PRIMARY_DARK\n\t}\n\tserver {\n\t\t$primary_scheme()\n\t}\n\tarrow {\n\t\tFontColor $PRIMARY_DARK\n\t\tLineColor $PRIMARY_DARK\n\t}\n\tgroup {\n\t\tBackGroundColor $LIGHT\n\t\tLineColor $LIGHT_DARK\n\t\tLineThickness 2.0\n\t\tMargin 5\n\t\tPadding 5\n\t}\n  }\n  participant {\n    Margin 5 40\n    Padding 15 20\n  }\n  ganttDiagram {\n\ttask {\n\t\t$primary_scheme()\n\t\tLineColor $PRIMARY\n\t\tMargin 10 2 2 2\n\t\tPadding 6\n\t}\n\tnote {\n\t\tFontColor $INFO_TEXT\n\t\tLineColor $INFO_DARK\n\t\tBackGroundColor $INFO\n\t}\n\tseparator {\n\t\tLineColor $SECONDARY\n\t\tBackGroundColor $SECONDARY-$SECONDARY_DARK\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tmilestone {\n\t\tFontColor $INFO\n\t\tFontSize 16\n\t\tFontStyle italic\n\t\tBackGroundColor $SECONDARY\n\t\tLineColor $SECONDARY_DARK\n\t}\n\ttimeline {\n\t\tBackgroundColor $SECONDARY\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tclosed {\n\t\tBackgroundColor $WARNING_DARK\n\t\tFontColor $WARNING_TEXT\n\t}\n  }\n</style>\n''\n'' Global Default Values\n''\nskinparam defaultFontName       \"Verdana\"\nskinparam defaultFontSize       12\nskinparam dpi                   100\nskinparam shadowing             false\nskinparam roundcorner           8\nskinparam BoxPadding            40\nskinparam ArrowColor            $DARK\nskinparam stereotype {\n    CBackgroundColor $SECONDARY_LIGHT\n    CBorderColor $SECONDARY_DARK\n    ABackgroundColor $SUCCESS_LIGHT\n    ABorderColor $SUCCESS_DARK\n    IBackgroundColor $DANGER_LIGHT\n    IBorderColor $DANGER_DARK\n    EBackgroundColor $WARNING_LIGHT\n    EBorderColor $WARNING_DARK\n    NBackgroundColor $INFO_LIGHT\n    NBorderColor $INFO_DARK\n}\nskinparam title {\n\tFontColor\t                 $PRIMARY\n\tBorderColor\t                 $SECONDARY_DARK\n\tFontSize\t    \t         20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor              $SECONDARY_LIGHT-$SECONDARY\n}\n\nskinparam legend {\n\tBackgroundColor $SECONDARY\n\tBorderColor $SECONDARY_DARK\n\tFontColor $LIGHT\n}\n\n!startsub swimlane\nskinparam swimlane {\n\tBorderColor $INFO\n\tBorderThickness 2\n\tTitleBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tTitleFontColor $PRIMARY\n}\n!endsub\n\n!startsub activity\n\nskinparam activity {\n\t$primary_scheme()\n\tBarColor $SUCCESS\n\tStartColor $INFO\n\tEndColor $INFO\n\t''\n\tDiamondBackgroundColor $SECONDARY_LIGHT\n  \tDiamondBorderColor $SECONDARY_DARK\n  \tDiamondFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub participant\n\nskinparam participant {\n\t$primary_scheme()\n\tParticipantBorderThickness 2\n}\n!endsub\n\n!startsub actor\n\nskinparam actor {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub arrow\n\nskinparam arrow {\n\tThickness 3\n\tColor $PRIMARY\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub sequence\n\nskinparam sequence {\n\tBorderColor $PRIMARY\n\t' For some reason sequence title font color does not pick up from global\n\tTitleFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n\tStartColor $PRIMARY\n\tEndColor $PRIMARY\n\t''\n\tBoxBackgroundColor $BGCOLOR\n\tBoxBorderColor $DARK\n\tBoxFontColor $DARK\n\t''\n\tDelayFontColor $DARK\n\t''\n\tLifeLineBorderColor $SECONDARY\n\tLifeLineBorderThickness 2\n\tLifeLineBackgroundColor $SECONDARY_DARK\n\t''\n\tGroupBorderColor $DARK\n\tGroupFontColor $DARK\n\tGroupHeaderFontColor $INFO\n\tGroupBackgroundColor $SECONDARY\n\tGroupHeaderBackgroundColor $BGCOLOR\n\t''\n\tDividerBackgroundColor $DARK\n    DividerBorderColor $DARK\n    DividerBorderThickness 2\n    DividerFontColor $LIGHT\n\t''\n\tReferenceBackgroundColor $BGCOLOR\n\tReferenceBorderColor $DARK\n\tReferenceFontColor $DARK\n\tReferenceHeaderFontColor $INFO\n\tReferenceHeaderBackgroundColor $SECONDARY\n\t''\n\tStereotypeFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub partition\n\nskinparam partition {\n\tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n}\n!endsub\n\n!startsub collections\n\nskinparam collections {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub control\n\nskinparam control {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub entity\n\nskinparam entity {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub boundary\n\nskinparam boundary {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub agent\n\nskinparam agent {\n\tBackgroundColor $WARNING\n\tBorderColor $WARNING_LIGHT\n\tFontColor $DARK\n}\n!endsub\n\n!startsub note\n\nskinparam note {\n\tBorderThickness 1\n\tBackgroundColor $INFO\n\tBorderColor $INFO_DARK\n\tFontColor $WHITE\n}\n!endsub\n\n!startsub artifact\n\nskinparam artifact {\n\tBackgroundColor $DARK\n\tBorderColor $DARK_DARK\n\tFontColor $LIGHT\n}\n!endsub\n\n!startsub component\n\nskinparam component {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub interface\n\nskinparam interface {\n\tBackgroundColor  $DANGER_DARK\n\tBorderColor  $DANGER\n\tFontColor $DARK\n}\n!endsub\n\n!startsub storage\n\nskinparam storage {\n\tBackgroundColor $WARNING\n  \tBorderColor $WARNING_DARK\n\tFontColor $WARNING_TEXT\n}\n!endsub\n\n!startsub node\n\nskinparam node {\n\tBackgroundColor  $SECONDARY\n\tBorderColor $LIGHT\n\tFontColor $LIGHT\n}\n!endsub\n\n!startsub cloud\n\nskinparam cloud {\n\tBackgroundColor #F2FCFE-#eeeeee\n\tBorderColor #F2FCFE\n\tFontColor $DARK\n}\n!endsub\n\n!startsub database\n\nskinparam database {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub class\n\nskinparam class {\n\t$primary_scheme()\n\tHeaderBackgroundColor $PRIMARY_LIGHT\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $PRIMARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub object\n\nskinparam object {\n\t$primary_scheme()\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub usecase\n\nskinparam usecase {\n\t$primary_scheme()\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub rectangle\n\nskinparam rectangle {\n\t$primary_scheme()\n\tBackgroundColor $SECONDARY_LIGHT\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub package\n\nskinparam package {\n\tBackgroundColor $SECONDARY\n  \tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBorderThickness 2\n}\n!endsub\n\n!startsub folder\n\nskinparam folder {\n\tBackgroundColor $SECONDARY_LIGHT\n  \tBorderColor $WARNING\n\tFontColor $WARNING\n\tBorderThickness 2\n}\n!endsub\n\n!startsub frame\n\nskinparam frame {\n\tBackgroundColor $SECONDARY_LIGHT\n  \tBorderColor $INFO\n\tFontColor $INFO\n\tBorderThickness 2\n}\n!endsub\n\n!startsub state\n\nskinparam state {\n\t$primary_scheme()\n\tBackgroundColor $PRIMARY_LIGHT\n\tStartColor $INFO\n\tEndColor $INFO\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub queue\n\nskinparam queue {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub card\n\nskinparam card {\n\tBackgroundColor $INFO\n\tBorderColor $INFO_DARK\n\tFontColor $INFO_TEXT\n}\n!endsub\n\n!startsub file\n\nskinparam file {\n\tBackgroundColor $SECONDARY_DARK\n\tBorderColor $LIGHT\n\tFontColor $LIGHT\n}\n!endsub\n\n!startsub stack\n\nskinparam stack {\n\t$primary_scheme()\n}\n!endsub\n";
g.PLANTUML_THEMES["silver"]="---\nname: silver\ndisplay_name: Silver\ndescription: Mostly silver grays Theme\nauthor: Brett Schwarz\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/bschwarz/puml-themes\ninspiration: \n---\n\n!$THEME = \"silver\"\n\n!if %not(%variable_exists(\"$BGCOLOR\"))\n!$BGCOLOR = \"transparent\"\n!endif\n\nskinparam backgroundColor $BGCOLOR\nskinparam useBetaStyle false\n\n!$WHITE = \"#FFF\"\n!$GRAY_DARK = \"#4d4d4d\"\n!$GRAY = \"#737373\"\n!$LIGHT = \"#ffffff\"\n!$DARK = \"#303030\"\n\n'' *_LIGHT = tint (lighter) of the main color of 80%\n''          where TINT is calculated by clr + (255-clr) * tint_factor\n'' *_DARK = shade (darker) of the main color of 80%\n''          and SHADE is calculated by clr * (1 - shade_factor)\n''\n!$FGCOLOR = $DARK\n!$PRIMARY = \"#eeeeee\"\n!$PRIMARY_LIGHT = \"#f1f1f1\"\n!$PRIMARY_DARK = \"#bebebe\"\n!$PRIMARY_TEXT = \"#336699\"\n!$SECONDARY = \"#d6d6d6\"\n!$SECONDARY_LIGHT = \"#dedede\"\n!$SECONDARY_DARK = \"#ababab\"\n!$SECONDARY_TEXT = $LIGHT\n!$INFO = \"#336699\"\n!$INFO_LIGHT = \"#5c85ad\"\n!$INFO_DARK = \"#29527a\"\n!$INFO_TEXT = $WHITE\n!$SUCCESS = \"#339933\"\n!$SUCCESS_LIGHT = \"#5cad5c\"\n!$SUCCESS_DARK = \"#297a29\"\n!$SUCCESS_TEXT = $WHITE\n!$WARNING = \"#ffae42\"\n!$WARNING_LIGHT = \"#ffbe68\"\n!$WARNING_DARK = \"#cc8b35\"\n!$WARNING_TEXT = $WHITE\n!$DANGER = \"#ff3333\"\n!$DANGER_LIGHT = \"#ff5c5c\"\n!$DANGER_DARK = \"#cc2929\"\n!$DANGER_TEXT = $WHITE\n\n!procedure $success($msg)\n  <font color=$SUCCESS><b>$msg\n!endprocedure\n\n!procedure $failure($msg)\n  <font color=$DANGER><b>$msg\n!endprocedure\n\n!procedure $warning($msg)\n  <font color=$WARNING><b>$msg\n!endprocedure\n\n!procedure $primary_scheme()\n\tFontColor $PRIMARY_TEXT\n\tBorderColor $PRIMARY_LIGHT\n\tBackgroundColor $PRIMARY-$PRIMARY_DARK\n!endprocedure\n''\n'' Style settings\n''\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $PRIMARY_TEXT\n    HyperLinkColor $ORANGE\n    LineColor $PRIMARY_DARK\n    LineThickness 1\n    Margin 10\n    Padding 6\n    Shadowing 0.0\n  }\n  node {\n   Padding 15\n   roundcorner 20\n   BackgroundColor $PRIMARY-$PRIMARY_DARK\n  }\n  caption {\n    LineThickness 0\n  }\n  footer {\n    LineThickness 0\n  }\n  groupHeader {\n    BackgroundColor $SECONDARY\n    FontColor $INFO\n    FontStyle bold\n  }\n  header {\n    LineThickness 0\n  }\n  referenceHeader {\n    BackgroundColor $BGCOLOR\n    FontColor $DARK\n    FontStyle bold\n  }\n  separator {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  title {\n\tFontSize 20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tFontColor $PRIMARY\n\tBorderColor $SECONDARY\n  }\n  nwdiagDiagram {\n\tnetwork {\n\t\t$primary_scheme()    \n\t\tLineColor $PRIMARY\n\t\tLineThickness 1.0\n\t\tFontColor $PRIMARY_DARK\n\t}\n\tserver {\n\t\t$primary_scheme()\n\t}\n\tarrow {\n\t\tFontColor $PRIMARY_DARK\n\t\tLineColor $PRIMARY_DARK\n\t}\n\tgroup {\n\t\tBackGroundColor $LIGHT\n\t\tLineColor $LIGHT_DARK\n\t\tLineThickness 2.0\n\t\tMargin 5\n\t\tPadding 5\n\t}\n  }\n  participant {\n    Margin 5 30\n    Padding 15 20\n  }\n  ganttDiagram {\n\ttask {\n\t\t$primary_scheme()\n\t\tLineColor $PRIMARY\n\t\tMargin 10 2 2 2\n\t\tPadding 6\n\t}\n\tnote {\n\t\tFontColor $INFO_TEXT\n\t\tLineColor $INFO_DARK\n\t\tBackGroundColor $INFO\n\t}\n\tseparator {\n\t\tLineColor $SECONDARY\n\t\tBackGroundColor $SECONDARY-$SECONDARY_DARK\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tmilestone {\n\t\tFontColor $INFO\n\t\tFontSize 16\n\t\tFontStyle italic\n\t\tBackGroundColor $SECONDARY\n\t\tLineColor $SECONDARY_DARK\n\t}\n\ttimeline {\n\t\tBackgroundColor $SECONDARY\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tclosed {\n\t\tBackgroundColor $WARNING_DARK\n\t\tFontColor $WARNING_TEXT\n\t}\n  }\n</style>\n''\n'' Global Default Values\n''\nskinparam defaultFontName        \"Verdana\"\nskinparam defaultFontSize        12\nskinparam dpi                    100\nskinparam shadowing              false\nskinparam roundcorner            15\nskinparam BoxPadding             30\nskinparam ArrowColor             $GRAY\nskinparam stereotype {\n    CBackgroundColor $SECONDARY_LIGHT\n    CBorderColor $SECONDARY_DARK\n    ABackgroundColor $SUCCESS_LIGHT\n    ABorderColor $SUCCESS_DARK\n    IBackgroundColor $DANGER_LIGHT\n    IBorderColor $DANGER_DARK\n    EBackgroundColor $WARNING_LIGHT\n    EBorderColor $WARNING_DARK\n    NBackgroundColor $INFO_LIGHT\n    NBorderColor $INFO_DARK\n}\nskinparam title {\n\tFontColor\t                 $PRIMARY\n\tBorderColor\t                 $SECONDARY_DARK\n\tFontSize\t    \t         20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor              $SECONDARY_LIGHT-$SECONDARY\n}\n\n\nskinparam legend {\n\tBackgroundColor $SECONDARY\n\tBorderColor $SECONDARY_DARK\n\tFontColor $SECONDARY_TEXT\n}\n\n!startsub swimlane\nskinparam swimlane {\n\tBorderColor $INFO\n\tBorderThickness 2\n\tTitleBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tTitleFontColor $PRIMARY\n}\n!endsub\n\n!startsub activity\n\nskinparam activity {\n\t$primary_scheme()\n\tBarColor $SUCCESS\n\tStartColor $INFO\n\tEndColor $INFO\n\t''\n\tDiamondBackgroundColor $SECONDARY-$SECONDARY_DARK\n  \tDiamondBorderColor $SECONDARY_DARK\n\tDiamondFontColor $SECONDARY_TEXT\n}\n\n!endsub\n\n!startsub participant\n\nskinparam participant {\n\t$primary_scheme()\n\tParticipantBorderThickness 2\n}\n\n!endsub\n\n!startsub actor\n\nskinparam actor {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n\n!endsub\n\n!startsub arrow\n\nskinparam arrow {\n\tThickness 3\n\tColor $PRIMARY\n\tFontColor $FGCOLOR\n}\n\n!endsub\n\n!startsub sequence\n\nskinparam sequence {\n\tBorderColor $PRIMARY\n\t' For some reason sequence title font color does not pick up from global\n\tTitleFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n\tStartColor $PRIMARY\n\tEndColor $PRIMARY\n\t''\n\tBoxBackgroundColor $LIGHT\n\tBoxBorderColor $GRAY\n\tBoxFontColor $DARK\n\t''\n\tDelayFontColor $DARK\n\t''\n\tLifeLineBorderColor $SECONDARY_DARK\n\tLifeLineBorderThickness 2\n\tLifeLineBackgroundColor $SECONDARY_LIGHT\n\t''\n\tGroupBorderColor $GRAY\n\tGroupFontColor $DARK\n\tGroupHeaderFontColor $INFO\n\t''\n\tDividerBackgroundColor $WHITE-$LIGHT\n    DividerBorderColor $GRAY\n    DividerBorderThickness 2\n    DividerFontColor $DARK\n\t''\n\tReferenceBackgroundColor $BGCOLOR\n\tReferenceBorderColor $GRAY\n\tReferenceFontColor $DARK\n\tReferenceHeaderFontColor $INFO\n\t''\n\tStereotypeFontColor $PRIMARY_TEXT\n}\n\n!endsub\n\n!startsub partition\n\nskinparam partition {\n\tBorderColor $PRIMARY\n\tFontColor $PRIMARY_DARK\n\tBackgroundColor $BGCOLOR\n}\n\n!endsub\n\n!startsub collections\n\nskinparam collections {\n\t$primary_scheme()\n}\n\n!endsub\n\n!startsub control\n\nskinparam control {\n\t$primary_scheme()\n}\n\n!endsub\n\n!startsub entity\n\nskinparam entity {\n\t$primary_scheme()\n}\n\n!endsub\n\n!startsub boundary\n\nskinparam boundary {\n\t$primary_scheme()\n}\n\n!endsub\n\n!startsub agent\n\nskinparam agent {\n\tBackgroundColor #orange\n\tBorderColor #999999\n\tFontColor #333333\n}\n\n!endsub\n\n!startsub note\n\nskinparam note {\n\tBorderThickness 1\n\tBackgroundColor $INFO_LIGHT-$INFO\n\tBorderColor $INFO\n\tFontColor $WHITE\n}\n\n!endsub\n\n!startsub artifact\n\nskinparam artifact {\n\tBackgroundColor $SECONDARY_LIGHT-$SECONDARY_DARK\n\tBorderColor $SECONDARY_DARK\n\tFontColor $SECONDARY_TEXT\n}\n\n!endsub\n\n!startsub component\n\nskinparam component {\n\t$primary_scheme()\n}\n\n!endsub\n\n!startsub interface\n\nskinparam interface {\n\tBackgroundColor  $DANGER_LIGHT\n\tBorderColor  $DANGER\n\tFontColor $DARK\n}\n\n!endsub\n\n!startsub storage\n\nskinparam storage {\n\tBackgroundColor $WARNING_LIGHT-$WARNING\n  \tBorderColor $WARNING\n\tFontColor $WARNING_TEXT\n}\n\n!endsub\n\n!startsub node\n\nskinparam node {\n\tBackgroundColor $PRIMARY_LIGHT-$PRIMARY_DARK\n\tBorderColor $PRIMARY_LIGHT\n\tFontColor $PRIMARY_TEXT\n}\n\n!endsub\n\n!startsub cloud\n\nskinparam cloud {\n\tBackgroundColor #F2FCFE-#eeeeee\n\tBorderColor #F2FCFE\n\tFontColor $DARK\n}\n\n!endsub\n\n!startsub database\n\nskinparam database {\n\t$primary_scheme()\n\tFontColor $DARK\n}\n\n!endsub\n\n!startsub class\n\nskinparam class {\n\t$primary_scheme()\n\tHeaderBackgroundColor $PRIMARY_LIGHT-$PRIMARY_DARK\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $DARK\n\tAttributeFontSize 9\n}\n\n!endsub\n\n!startsub object\n\nskinparam object {\n\t$primary_scheme()\n\tStereotypeFontColor $LIGHT\n\tBorderThickness 1\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n\n!endsub\n\n!startsub usecase\n\nskinparam usecase {\n\t$primary_scheme()\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n\n!endsub\n\n!startsub rectangle\n\nskinparam rectangle {\n\t$primary_scheme()\n\tBackgroundColor $PRIMARY_LIGHT\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n\n!endsub\n\n!startsub package\n\nskinparam package {\n\t$primary_scheme()\n\tBorderThickness 2\n}\n\n!endsub\n\n!startsub folder\n\nskinparam folder {\n\tBackgroundColor $PRIMARY-$PRIMARY_DARK\n  \tBorderColor $WARNING\n\tFontColor $WARNING\n\tBorderThickness 2\n}\n\n!endsub\n\n!startsub frame\n\nskinparam frame {\n\tBackgroundColor $PRIMARY-$PRIMARY_DARK\n  \tBorderColor $INFO\n\tFontColor $INFO\n\tBorderThickness 2\n}\n\n!endsub\n\n!startsub state\n\nskinparam state {\n\t$primary_scheme()\n\tStartColor $INFO\n\tEndColor $INFO\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n\n!endsub\n\n!startsub queue\n\nskinparam queue {\n\t$primary_scheme()\n}\n\n!endsub\n\n!startsub card\n\nskinparam card {\n\tBackgroundColor $INFO_LIGHT-$INFO\n\tBorderColor $INFO\n\tFontColor $INFO_TEXT\n}\n\n!endsub\n\n!startsub file\n\nskinparam file {\n\tBackgroundColor $SECONDARY_LIGHT-$SECONDARY\n\tBorderColor $LIGHT\n\tFontColor $LIGHT\n\n}\n\n!endsub\n\n!startsub stack\n\nskinparam stack {\n\t$primary_scheme()\n}\n\n!endsub\n";
g.PLANTUML_THEMES["sketchy"]="---\nname: sketchy\ndisplay_name: Sketchy\ndescription: Theme based off of the bootstrap theme of the same name\nauthor: Brett Schwarz\nrelease: \nlicense: MIT\nversion: \nsource: https://github.com/bschwarz/puml-themes\ninspiration: https://bootswatch.com/sketchy/\n---\n\n!$THEME = \"sketchy\"\n\n!if %not(%variable_exists(\"$BGCOLOR\"))\n!$BGCOLOR = \"transparent\"\n!endif\n\nskinparam backgroundColor $BGCOLOR\nskinparam useBetaStyle false\n!option handwritten true\nskinparam shadowing false\n\n''\n'' Colors taken from the css file of the BS theme\n''\n!$BLUE = \"#007bff\"\n!$INDIGO = \"#6610f2\"\n!$PURPLE = \"#6f42c1\"\n!$PINK = \"#e83e8c\"\n!$RED = \"#dc3545\"\n!$ORANGE = \"#fd7e14\"\n!$YELLOW = \"#ffc107\"\n!$GREEN = \"#28a745\"\n!$TEAL = \"#20c997\"\n!$CYAN = \"#17a2b8\"\n!$WHITE = \"#ffffff\"\n!$GRAY = \"#868e96\"\n!$GRAYDARK = \"#333333\"\n!$PRIMARY = \"#333333\"\n!$SECONDARY = \"#555555\"\n!$SUCCESS = \"#28a745\"\n!$INFO = \"#17a2b8\"\n!$WARNING = \"#ffc107\"\n!$DANGER = \"#dc3545\"\n!$LIGHT = \"#ffffff\"\n!$DARK = \"#555555\"\n\n'' *_DARK = tint (lighter) of the main color of 80%\n''          where TINT is calculated by clr + (255-clr) * tint_factor\n'' *_LIGHT = shade (darker) of the main color of 80%\n''          and SHADE is calculated by clr * (1 - shade_factor)\n''\n!$FGCOLOR = $WHITE\n!$PRIMARY_DARK = \"#2e2e2e\"\n!$PRIMARY_LIGHT = \"#474747\"\n!$PRIMARY_TEXT = $WHITE\n!$SECONDARY_DARK = \"#4d4d4d\"\n!$SECONDARY_LIGHT = \"#666666\"\n!$SECONDARY_TEXT = $WHITE\n!$INFO_DARK = \"#1592a6\"\n!$INFO_LIGHT = \"#2eabbf\"\n!$INFO_TEXT = $WHITE\n!$SUCCESS_DARK = \"#24963e\"\n!$SUCCESS_LIGHT = \"#3eb058\"\n!$SUCCESS_TEXT = $WHITE\n!$WARNING_DARK = \"#e6ae06\"\n!$WARNING_LIGHT = \"#ffc720\"\n!$WARNING_TEXT = $WHITE\n!$DANGER_DARK = \"#c6303e\"\n!$DANGER_LIGHT = \"#e04958\"\n!$DANGER_TEXT = $WHITE\n!$DARK_DARK = \"#4d4d4d\"\n!$DARK_LIGHT = \"#666666\"\n!$LIGHT_DARK = \"#e6e6e6\"\n!$LIGHT_LIGHT = \"#ffffff\"\n\n!procedure $success($msg)\n  <font color=$SUCCESS><b>$msg\n!endprocedure\n\n!procedure $failure($msg)\n  <font color=$DANGER><b>$msg\n!endprocedure\n\n!procedure $warning($msg)\n  <font color=$WARNING><b>$msg\n!endprocedure\n\n!procedure $primary_scheme()\n\tFontColor $PRIMARY_TEXT\n\tBorderColor $PRIMARY\n\tBackgroundColor $PRIMARY_LIGHT\n!endprocedure\n''\n'' Style settings\n''\n<style>\n  root {\n    BackgroundColor $BGCOLOR\n    FontColor $PRIMARY_TEXT\n    HyperLinkColor $ORANGE\n    LineColor $PRIMARY_DARK\n    LineThickness 1\n    Margin 10\n    Padding 6\n    Shadowing 0.0\n  }\n  node {\n   Padding 15\n   roundcorner 20\n   BackgroundColor $PRIMARY-$PRIMARY_DARK\n  }\n  caption {\n    LineThickness 0\n  }\n  footer {\n    LineThickness 0\n  }\n  groupHeader {\n    BackgroundColor $SECONDARY\n    FontColor $INFO\n    FontStyle bold\n  }\n  header {\n    LineThickness 0\n  }\n  referenceHeader {\n    BackgroundColor $BGCOLOR\n    FontColor $DARK\n    FontStyle bold\n  }\n  separator {\n    BackgroundColor $FGCOLOR\n    FontColor $BGCOLOR\n    FontStyle bold\n  }\n  title {\n\tFontSize 20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tFontColor $PRIMARY\n\tBorderColor $SECONDARY\n  }\n  nwdiagDiagram {\n\tnetwork {\n\t\t$primary_scheme()    \n\t\tLineColor $PRIMARY\n\t\tLineThickness 1.0\n\t\tFontColor $PRIMARY_DARK\n\t}\n\tserver {\n\t\t$primary_scheme()\n\t}\n\tarrow {\n\t\tFontColor $PRIMARY_DARK\n\t\tLineColor $PRIMARY_DARK\n\t}\n\tgroup {\n\t\tBackGroundColor $LIGHT\n\t\tLineColor $LIGHT_DARK\n\t\tLineThickness 2.0\n\t\tMargin 5\n\t\tPadding 5\n\t}\n  }\n  participant {\n    Margin 5 40\n    Padding 15 20\n  }\n  ganttDiagram {\n\ttask {\n\t\t$primary_scheme()\n\t\tLineColor $PRIMARY\n\t\tMargin 10 2 2 2\n\t\tPadding 6\n\t}\n\tnote {\n\t\tFontColor $INFO_TEXT\n\t\tLineColor $INFO_DARK\n\t\tBackGroundColor $INFO\n\t}\n\tseparator {\n\t\tLineColor $SECONDARY\n\t\tBackGroundColor $SECONDARY-$SECONDARY_DARK\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tmilestone {\n\t\tFontColor $INFO\n\t\tFontSize 16\n\t\tFontStyle italic\n\t\tBackGroundColor $SECONDARY\n\t\tLineColor $SECONDARY_DARK\n\t}\n\ttimeline {\n\t\tBackgroundColor $SECONDARY\n\t\tFontColor $SECONDARY_TEXT\n\t}\n\tclosed {\n\t\tBackgroundColor $WARNING_DARK\n\t\tFontColor $WARNING_TEXT\n\t}\n  }\n</style>\n''\n'' Global Default Values\n''\nskinparam defaultFontName       \"Segoe Print\"\nskinparam defaultFontSize       12\nskinparam dpi                   100\nskinparam shadowing             false\nskinparam roundcorner           8\nskinparam BoxPadding            40\nskinparam ArrowColor            $DARK\nskinparam stereotype {\n    CBackgroundColor $SECONDARY_LIGHT\n    CBorderColor $SECONDARY_DARK\n    ABackgroundColor $SUCCESS_LIGHT\n    ABorderColor $SUCCESS_DARK\n    IBackgroundColor $DANGER_LIGHT\n    IBorderColor $DANGER_DARK\n    EBackgroundColor $WARNING_LIGHT\n    EBorderColor $WARNING_DARK\n    NBackgroundColor $INFO_LIGHT\n    NBorderColor $INFO_DARK\n}\nskinparam title {\n\tFontColor\t                 $FGCOLOR\n\tBorderColor\t                 $SECONDARY_DARK\n\tFontSize\t    \t         20\n\tBorderRoundCorner            8\n\tBorderThickness \t         1\n\tBackgroundColor              $SECONDARY_LIGHT-$SECONDARY\n}\n\nskinparam legend {\n\tBackgroundColor $SECONDARY\n\tBorderColor $SECONDARY_DARK\n\tFontColor $LIGHT\n}\n\n!startsub swimlane\nskinparam swimlane {\n\tBorderColor $INFO\n\tBorderThickness 2\n\tTitleBackgroundColor  $SECONDARY_LIGHT-$SECONDARY\n\tTitleFontColor $FGCOLOR\n}\n!endsub\n\n!startsub activity\n\nskinparam activity {\n\t$primary_scheme()\n\tBarColor $SUCCESS\n\tStartColor $INFO\n\tEndColor $INFO\n\t''\n\tDiamondBackgroundColor $SECONDARY_LIGHT\n  \tDiamondBorderColor $SECONDARY_DARK\n  \tDiamondFontColor $SECONDARY_TEXT\n}\n!endsub\n\n!startsub participant\n\nskinparam participant {\n\t$primary_scheme()\n\tParticipantBorderThickness 2\n}\n!endsub\n\n!startsub actor\n\nskinparam actor {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub arrow\n\nskinparam arrow {\n\tThickness 3\n\tColor $PRIMARY\n\tFontColor $FGCOLOR\n}\n!endsub\n\n!startsub sequence\n\nskinparam sequence {\n\tBorderColor $PRIMARY\n\t' For some reason sequence title font color does not pick up from global\n\tTitleFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n\tStartColor $PRIMARY\n\tEndColor $PRIMARY\n\t''\n\tBoxBackgroundColor $BGCOLOR\n\tBoxBorderColor $DARK\n\tBoxFontColor $DARK\n\t''\n\tDelayFontColor $DARK\n\t''\n\tLifeLineBorderColor $SECONDARY\n\tLifeLineBorderThickness 2\n\tLifeLineBackgroundColor $SECONDARY_DARK\n\t''\n\tGroupBorderColor $DARK\n\tGroupFontColor $DARK\n\tGroupHeaderFontColor $INFO\n\tGroupBackgroundColor $SECONDARY\n\tGroupHeaderBackgroundColor $BGCOLOR\n\t''\n\tDividerBackgroundColor $DARK\n    DividerBorderColor $DARK\n    DividerBorderThickness 2\n    DividerFontColor $LIGHT\n\t''\n\tReferenceBackgroundColor $BGCOLOR\n\tReferenceBorderColor $DARK\n\tReferenceFontColor $DARK\n\tReferenceHeaderFontColor $INFO\n\tReferenceHeaderBackgroundColor $SECONDARY\n\t''\n\tStereotypeFontColor $PRIMARY_TEXT\n}\n!endsub\n\n!startsub partition\n\nskinparam partition {\n\tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBackgroundColor $BGCOLOR\n}\n!endsub\n\n!startsub collections\n\nskinparam collections {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub control\n\nskinparam control {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub entity\n\nskinparam entity {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub boundary\n\nskinparam boundary {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub agent\n\nskinparam agent {\n\tBackgroundColor $WARNING\n\tBorderColor $WARNING_LIGHT\n\tFontColor $DARK\n}\n!endsub\n\n!startsub note\n\nskinparam note {\n\tBorderThickness 1\n\tBackgroundColor $INFO\n\tBorderColor $INFO_DARK\n\tFontColor $WHITE\n}\n!endsub\n\n!startsub artifact\n\nskinparam artifact {\n\tBackgroundColor $DARK\n\tBorderColor $DARK_DARK\n\tFontColor $LIGHT\n}\n!endsub\n\n!startsub component\n\nskinparam component {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub interface\n\nskinparam interface {\n\tBackgroundColor  $DANGER_DARK\n\tBorderColor  $DANGER\n\tFontColor $DARK\n}\n!endsub\n\n!startsub storage\n\nskinparam storage {\n\tBackgroundColor $WARNING\n  \tBorderColor $WARNING_DARK\n\tFontColor $WARNING_TEXT\n}\n!endsub\n\n!startsub node\n\nskinparam node {\n\tBackgroundColor  $SECONDARY\n\tBorderColor $LIGHT\n\tFontColor $LIGHT\n}\n!endsub\n\n!startsub cloud\n\nskinparam cloud {\n\tBackgroundColor #F2FCFE-#eeeeee\n\tBorderColor #F2FCFE\n\tFontColor $DARK\n}\n!endsub\n\n!startsub database\n\nskinparam database {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub class\n\nskinparam class {\n\t$primary_scheme()\n\tFontColor $FGCOLOR\n\tHeaderBackgroundColor $PRIMARY_LIGHT\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $LIGHT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub object\n\nskinparam object {\n\t$primary_scheme()\n\tStereotypeFontColor $DARK\n\tBorderThickness 1\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub usecase\n\nskinparam usecase {\n\t$primary_scheme()\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub rectangle\n\nskinparam rectangle {\n\t$primary_scheme()\n\tBackgroundColor $SECONDARY_LIGHT\n\tBorderThickness 2\n\tStereotypeFontColor $PRIMARY\n}\n!endsub\n\n!startsub package\n\nskinparam package {\n\tBackgroundColor $SECONDARY\n  \tBorderColor $PRIMARY\n\tFontColor $PRIMARY\n\tBorderThickness 2\n}\n!endsub\n\n!startsub folder\n\nskinparam folder {\n\tBackgroundColor $SECONDARY_LIGHT\n  \tBorderColor $WARNING\n\tFontColor $WARNING\n\tBorderThickness 2\n}\n!endsub\n\n!startsub frame\n\nskinparam frame {\n\tBackgroundColor $SECONDARY_LIGHT\n  \tBorderColor $INFO\n\tFontColor $INFO\n\tBorderThickness 2\n}\n!endsub\n\n!startsub state\n\nskinparam state {\n\t$primary_scheme()\n\tStartColor $INFO\n\tEndColor $INFO\n\tAttributeFontColor $SECONDARY_TEXT\n\tAttributeFontSize 11\n}\n!endsub\n\n!startsub queue\n\nskinparam queue {\n\t$primary_scheme()\n}\n!endsub\n\n!startsub card\n\nskinparam card {\n\tBackgroundColor $INFO\n\tBorderColor $INFO_DARK\n\tFontColor $INFO_TEXT\n}\n!endsub\n\n!startsub file\n\nskinparam file {\n\tBackgroundColor $SECONDARY_DARK\n\tBorderColor $LIGHT\n\tFontColor $LIGHT\n}\n!endsub\n\n!startsub stack\n\nskinparam stack {\n\t$primary_scheme()\n}\n!endsub\n";
